const TERMINAL_START_RETRY_INTERVAL: Duration = Duration::from_millis(350);
const TERMINAL_ECHO_RETRY_INTERVAL: Duration = Duration::from_millis(16);
/// How long one outstanding `TaskTerminals` query suppresses the next.
///
/// This is a lease, not a poll: nothing fires when it expires. It exists only
/// so a lost answer cannot leave the strip permanently unrefreshable, which a
/// bare in-flight boolean would.
const TASK_TERMINALS_QUERY_LEASE: Duration = Duration::from_secs(5);
/// Shown over the Terminal dock's photo while the Task's strip focuses nothing.
/// Hover text for a live "+" on the terminal strip.
const TERMINAL_ADD_SHELL_TOOLTIP: &str = "New shell terminal · Ctrl+Shift+`";
const TERMINAL_DOCK_EMPTY_MESSAGE: &str = "No terminal selected · press + or Ctrl+Shift+`";
const TERMINAL_ECHO_MAX_UNMATCHED_REFRESHES: u8 = 16;
/// Host worker command/subscription idle slice — separate from UI scheduling.
const HOST_WORKER_IDLE_WAIT: Duration = Duration::from_millis(50);
const COMPOSER_CARET_BLINK_INTERVAL: Duration = Duration::from_millis(512);
const HOST_BOOTSTRAP_REATTACH_INTERVAL: Duration = Duration::from_secs(1);
const PROVIDER_SETTINGS_REFRESH_INTERVAL: Duration = Duration::from_secs(2);
const PROVIDER_SETTINGS_IDLE_INTERVAL: Duration = Duration::from_secs(30);
/// A provider startup choice is a single PTY gesture and should settle almost
/// immediately. Never leave the panel permanently blocked if the provider
/// changes its prompt or fails to consume the gesture.
const PROVIDER_SETUP_RESOLUTION_TIMEOUT: Duration = Duration::from_secs(8);

/// Shared edge-triggered wake so projection/action publication can interrupt a
/// deadline wait without a 60Hz idle timer. Cloning shares the same core.
#[derive(Clone, Debug)]
struct ControllerWake {
    pending: Arc<AtomicBool>,
    lock: Arc<Mutex<()>>,
    cvar: Arc<Condvar>,
    notify: Arc<tokio::sync::Notify>,
}

impl Default for ControllerWake {
    fn default() -> Self {
        Self::new()
    }
}

impl ControllerWake {
    fn new() -> Self {
        Self {
            pending: Arc::new(AtomicBool::new(false)),
            lock: Arc::new(Mutex::new(())),
            cvar: Arc::new(Condvar::new()),
            notify: Arc::new(tokio::sync::Notify::new()),
        }
    }

    fn notify(&self) {
        self.pending.store(true, Ordering::Release);
        {
            let _guard = self.lock.lock();
            self.cvar.notify_one();
        }
        self.notify.notify_one();
    }

    fn take_pending(&self) -> bool {
        self.pending.swap(false, Ordering::AcqRel)
    }

    fn wait_timeout_blocking(&self, timeout: Duration) {
        if self.take_pending() {
            return;
        }
        let Ok(guard) = self.lock.lock() else {
            return;
        };
        let result = self
            .cvar
            .wait_timeout_while(guard, timeout, |_| !self.pending.load(Ordering::Acquire));
        drop(result);
        let _ = self.take_pending();
    }

    async fn wait_timeout_async(&self, timeout: Duration, timer: &gpui::BackgroundExecutor) {
        if self.take_pending() {
            return;
        }
        let sleep = timer.timer(timeout);
        let notified = self.notify.notified();
        futures_util::pin_mut!(sleep);
        futures_util::pin_mut!(notified);
        let _ = futures_util::future::select(notified, sleep).await;
        let _ = self.take_pending();
    }
}

/// Worker-facing retargetable handle. Many host runtimes bind to one shell wake
/// without replacing the controller's stable clone.
#[derive(Clone, Debug)]
struct ControllerWakeBridge {
    target: Arc<Mutex<ControllerWake>>,
}

impl ControllerWakeBridge {
    fn unbound() -> Self {
        Self {
            target: Arc::new(Mutex::new(ControllerWake::new())),
        }
    }

    fn bind(&self, wake: &ControllerWake) {
        if let Ok(mut target) = self.target.lock() {
            *target = wake.clone();
        }
    }

    fn notify(&self) {
        if let Ok(target) = self.target.lock() {
            target.notify();
        }
    }
}

#[derive(Clone, Copy, Debug)]
struct ControllerWaitInputs {
    composer_focused: bool,
    drafts_dirty: bool,
    layout_dirty: bool,
    remote_settings_open: bool,
    remote_poll_in_flight: bool,
    provider_settings_refreshing: bool,
    provider_poll_in_flight: bool,
    bootstrap_retry_armed: bool,
    since_last_composer_persist: Option<Duration>,
    since_last_layout_persist: Option<Duration>,
    since_last_remote_poll: Option<Duration>,
    since_last_provider_poll: Option<Duration>,
    since_last_bootstrap_retry: Option<Duration>,
    since_last_conversation_recovery: Option<Duration>,
    since_last_caret_toggle: Option<Duration>,
    next_terminal_requery: Option<Duration>,
}

fn duration_until(interval: Duration, since: Duration) -> Duration {
    interval.saturating_sub(since)
}

fn duration_until_phase_boundary(interval: Duration, since: Duration) -> Duration {
    let interval_ms = interval.as_millis().max(1);
    let phase = since.as_millis() % interval_ms;
    let remaining = interval_ms - phase;
    Duration::from_millis(remaining as u64).max(Duration::from_millis(1))
}

fn next_controller_wait(inputs: ControllerWaitInputs) -> Duration {
    let mut wait = CONTROLLER_IDLE_RECOVERY_INTERVAL;
    let consider = |wait: Duration, candidate: Duration| wait.min(candidate);

    if inputs.composer_focused {
        let since = inputs.since_last_caret_toggle.unwrap_or(Duration::ZERO);
        wait = consider(
            wait,
            duration_until_phase_boundary(COMPOSER_CARET_BLINK_INTERVAL, since),
        );
    }
    if inputs.drafts_dirty {
        let since = inputs
            .since_last_composer_persist
            .unwrap_or(COMPOSER_DRAFT_PERSIST_INTERVAL);
        wait = consider(wait, duration_until(COMPOSER_DRAFT_PERSIST_INTERVAL, since));
    }
    if inputs.layout_dirty {
        let since = inputs
            .since_last_layout_persist
            .unwrap_or(LAYOUT_PERSIST_INTERVAL);
        wait = consider(wait, duration_until(LAYOUT_PERSIST_INTERVAL, since));
    }
    if inputs.remote_settings_open && !inputs.remote_poll_in_flight {
        let since = inputs
            .since_last_remote_poll
            .unwrap_or(Duration::from_secs(1));
        wait = consider(wait, duration_until(Duration::from_secs(1), since));
    }
    if inputs.bootstrap_retry_armed {
        let since = inputs
            .since_last_bootstrap_retry
            .unwrap_or(HOST_BOOTSTRAP_REATTACH_INTERVAL);
        wait = consider(
            wait,
            duration_until(HOST_BOOTSTRAP_REATTACH_INTERVAL, since),
        );
    }
    let provider_interval = if inputs.provider_settings_refreshing {
        PROVIDER_SETTINGS_REFRESH_INTERVAL
    } else {
        PROVIDER_SETTINGS_IDLE_INTERVAL
    };
    if !inputs.provider_poll_in_flight {
        if let Some(since) = inputs.since_last_provider_poll {
            wait = consider(wait, duration_until(provider_interval, since));
        }
    }
    let since_recovery = inputs
        .since_last_conversation_recovery
        .unwrap_or(Duration::ZERO);
    wait = consider(
        wait,
        duration_until(CONVERSATION_RECOVERY_HEARTBEAT, since_recovery),
    );
    if let Some(next_terminal_requery) = inputs.next_terminal_requery {
        wait = consider(wait, next_terminal_requery.max(Duration::from_millis(1)));
    }
    wait
}

fn should_schedule_host_bootstrap_retry(
    enabled: bool,
    has_runtime: bool,
    has_pending_bootstrap: bool,
    connection_failed: bool,
    since_last_retry: Option<Duration>,
) -> bool {
    enabled
        && !has_runtime
        && !has_pending_bootstrap
        && connection_failed
        && since_last_retry.is_none_or(|elapsed| elapsed >= HOST_BOOTSTRAP_REATTACH_INTERVAL)
}

fn idle_photo_fetch_matches_current_canvas(
    fetch_generation: u64,
    current_generation: u64,
    selected_task: Option<TaskId>,
) -> bool {
    fetch_generation == current_generation && selected_task.is_none()
}

#[derive(Clone, Debug, PartialEq, Eq)]
enum ComposerDraftPart {
    Text(String),
    Selected(String),
    Placeholder,
    Caret,
}

fn composer_caret_visible(focused: bool, since_caret_epoch: Duration) -> bool {
    focused && (since_caret_epoch.as_millis() / COMPOSER_CARET_BLINK_INTERVAL.as_millis()) % 2 == 0
}

fn caret_phase_repaint(
    focused: bool,
    elapsed: Duration,
    last_rendered: Option<bool>,
) -> (bool, Option<bool>) {
    if !focused {
        return (false, None);
    }
    let visible = composer_caret_visible(true, elapsed);
    if last_rendered == Some(visible) {
        (false, last_rendered)
    } else {
        (true, Some(visible))
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum CodexReasoningPickerPath {
    Standard(usize),
    Advanced(usize),
}

/// Drive Codex's own live `/model` picker using stable navigation keys rather
/// than mutating a launch-only label. The provider catalog supplies the two
/// indices; Home/End make the sequence independent of the highlighted rows.
fn codex_model_picker_input(
    model_index: usize,
    effort: Option<CodexReasoningPickerPath>,
) -> String {
    let mut input = String::from("/model\r\u{1b}[F\r\u{1b}[H");
    input.push_str(&"\u{1b}[B".repeat(model_index));
    input.push('\r');
    match effort {
        None => {}
        Some(CodexReasoningPickerPath::Standard(index)) => {
            input.push_str("\u{1b}[H");
            input.push_str(&"\u{1b}[B".repeat(index));
            input.push('\r');
        }
        Some(CodexReasoningPickerPath::Advanced(index)) => {
            input.push_str("\u{1b}[F\r\u{1b}[H");
            input.push_str(&"\u{1b}[B".repeat(index));
            input.push('\r');
        }
    }
    input
}

/// Matching live Terminal runtime for the task's primary agent — enough to
/// refuse a duplicate StartProviderSession. Does not require identity attestation.
fn first_send_terminal_runtime_live(
    snapshot: &crate::domain::TaskSnapshot,
    terminal: &crate::domain::TaskTerminalProjection,
) -> bool {
    terminal.task_id == snapshot.task.id
        && snapshot.primary_agent_id == Some(terminal.agent_session_id)
        && terminal.action_epoch != 0
        && snapshot
            .agents
            .get(&terminal.agent_session_id)
            .is_some_and(|agent| agent.runtime_generation == terminal.runtime_generation)
        && snapshot
            .resources
            .get(&terminal.resource_id)
            .is_some_and(|resource| {
                resource.lifecycle == crate::domain::ResourceLifecycle::Active
                    && resource.resource_kind == crate::domain::ResourceKind::Terminal
                    && resource.task_id == Some(snapshot.task.id)
                    && resource.runtime_generation == terminal.resource_generation
                    && resource.runtime_generation == terminal.runtime_generation
            })
}

fn first_send_terminal_ready(
    snapshot: &crate::domain::TaskSnapshot,
    terminal: &crate::domain::TaskTerminalProjection,
) -> bool {
    terminal.accepts_input_without_conversation_id
        && first_send_terminal_runtime_live(snapshot, terminal)
        && snapshot
            .agents
            .get(&terminal.agent_session_id)
            .is_some_and(|agent| {
                agent.provider_kind == ProviderKind::Codex && agent.provider_session_id.is_none()
            })
}

fn terminal_projection_requires_provider_setup(
    snapshot: &crate::domain::TaskSnapshot,
    terminal: &crate::domain::TaskTerminalProjection,
) -> bool {
    first_send_terminal_runtime_live(snapshot, terminal)
        && snapshot
            .agents
            .get(&terminal.agent_session_id)
            .is_some_and(|agent| {
                crate::providers::input::provider_identityless_setup_required(
                    agent.provider_kind,
                    &terminal.text_lines,
                )
            })
}

/// Authoritative TerminalReadiness says no live runtime and no pending launch.
fn first_send_terminal_probe_not_started(result: &crate::domain::TaskCockpitResult) -> bool {
    matches!(
        result,
        crate::domain::TaskCockpitResult::Unavailable {
            surface: crate::domain::TaskCockpitSurface::Terminal,
            reason: crate::domain::TaskCockpitUnavailableReason::TerminalNotStarted,
            ..
        }
    )
}

/// Launch/restore is in flight — wait and requery; never StartProviderSession.
fn first_send_terminal_probe_start_pending(result: &crate::domain::TaskCockpitResult) -> bool {
    matches!(
        result,
        crate::domain::TaskCockpitResult::Unavailable {
            surface: crate::domain::TaskCockpitSurface::Terminal,
            reason: crate::domain::TaskCockpitUnavailableReason::TerminalStartPending,
            ..
        }
    )
}

/// Live Codex PTY is on a blocking trust/setup screen for this host.
fn first_send_terminal_probe_provider_setup_required(
    result: &crate::domain::TaskCockpitResult,
) -> bool {
    matches!(
        result,
        crate::domain::TaskCockpitResult::Unavailable {
            surface: crate::domain::TaskCockpitSurface::Terminal,
            reason: crate::domain::TaskCockpitUnavailableReason::TerminalProviderSetupRequired,
            ..
        }
    )
}

fn hold_pending_draft_first_send_for_provider_setup(
    slot: &mut HostUiState,
    request_id: Option<RequestId>,
) {
    if let Some(request_id) = request_id {
        slot.first_send_readiness_requests.remove(&request_id);
    }
    let Some(pending) = slot.pending_draft_first_send.as_mut() else {
        return;
    };
    pending.readiness_request_id = None;
    pending.readiness_requested_at = None;
    let owner = pending.owner.clone();
    let first_hold = !slot.provider_setup_approvals.contains_key(&owner.task_id);
    slot.provider_setup_approvals
        .entry(owner.task_id)
        .or_insert_with(|| ProviderSetupApproval {
            owner,
            state: ProviderSetupApprovalState::Waiting,
        });
    if first_hold {
        slot.composer_error = None;
    }
}

fn composer_provider_identity(
    provider: Option<&crate::domain::ProviderSessionProjection>,
) -> (
    Option<crate::domain::TurnId>,
    Option<crate::domain::QuestionId>,
    Option<crate::domain::ApprovalId>,
) {
    provider
        .map(|provider| {
            (
                provider.current_turn,
                provider.open_question,
                provider.open_approval,
            )
        })
        .unwrap_or((None, None, None))
}

fn composer_waits_for_provider_identity(
    unstarted_draft: bool,
    provider_kind: ProviderKind,
    provider_session_present: bool,
) -> bool {
    !unstarted_draft && !provider_session_present && provider_kind != ProviderKind::Codex
}

fn automatic_task_title(current_title: &str, first_prompt: &str) -> Option<String> {
    let is_placeholder = matches!(
        current_title.trim(),
        "New task" | "New Claude task" | "New Codex task"
    );
    is_placeholder
        .then(|| crate::remote::presentation::normalize_task_title(first_prompt))
        .flatten()
}

fn composer_draft_parts(
    draft: &str,
    cursor: usize,
    selection: Option<Range<usize>>,
    focused: bool,
    caret_visible: bool,
    _placeholder: &str,
) -> Vec<ComposerDraftPart> {
    let mut parts = Vec::new();
    if draft.is_empty() {
        if caret_visible {
            parts.push(ComposerDraftPart::Caret);
        }
        parts.push(ComposerDraftPart::Placeholder);
        let _ = focused;
        return parts;
    }
    let len = draft.chars().count();
    let cursor = cursor.min(len);
    let selection = selection
        .map(|range| range.start.min(len)..range.end.min(len))
        .filter(|range| range.start < range.end);
    let chars: Vec<char> = draft.chars().collect();
    let push_text =
        |parts: &mut Vec<ComposerDraftPart>, start: usize, end: usize, selected: bool| {
            if start >= end {
                return;
            }
            let text: String = chars[start..end].iter().collect();
            if selected {
                parts.push(ComposerDraftPart::Selected(text));
            } else {
                parts.push(ComposerDraftPart::Text(text));
            }
        };
    if let Some(range) = selection {
        push_text(&mut parts, 0, range.start, false);
        push_text(&mut parts, range.start, range.end, true);
        if caret_visible && cursor == range.end {
            parts.push(ComposerDraftPart::Caret);
        } else if caret_visible && cursor == range.start {
            // caret already conceptually at start; keep after selected for simplicity
        }
        push_text(&mut parts, range.end, len, false);
        if caret_visible && cursor != range.start && cursor != range.end {
            // unusual caret inside selection ignored
        }
        if caret_visible && cursor == range.start {
            let mut with_caret = Vec::new();
            push_text(&mut with_caret, 0, range.start, false);
            with_caret.push(ComposerDraftPart::Caret);
            push_text(&mut with_caret, range.start, range.end, true);
            push_text(&mut with_caret, range.end, len, false);
            return with_caret;
        }
    } else {
        push_text(&mut parts, 0, cursor, false);
        if caret_visible {
            parts.push(ComposerDraftPart::Caret);
        }
        push_text(&mut parts, cursor, len, false);
    }
    parts
}

fn provider_inbox_affordance(connected: bool, checking: bool) -> ProviderInboxAffordance {
    if connected {
        ProviderInboxAffordance::ConnectedAdd
    } else if checking {
        ProviderInboxAffordance::Checking
    } else {
        ProviderInboxAffordance::DisconnectedAdd
    }
}

fn project_creation_affordance(
    can_add_local_project: bool,
    provider_affordance: ProviderInboxAffordance,
) -> ProviderInboxAffordance {
    if can_add_local_project {
        ProviderInboxAffordance::ConnectedAdd
    } else if provider_affordance == ProviderInboxAffordance::Checking {
        ProviderInboxAffordance::Checking
    } else {
        ProviderInboxAffordance::DisconnectedAdd
    }
}

fn cycle_project_choice(
    current: ProjectId,
    choices: &[ProjectId],
    backwards: bool,
) -> Option<ProjectId> {
    let current_index = choices.iter().position(|project_id| *project_id == current);
    match (choices.len(), current_index, backwards) {
        (0, _, _) => None,
        (len, Some(0), true) => choices.get(len - 1).copied(),
        (_, Some(index), true) => choices.get(index - 1).copied(),
        (len, Some(index), false) => choices.get((index + 1) % len).copied(),
        (_, None, true) => choices.last().copied(),
        (_, None, false) => choices.first().copied(),
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ProviderInboxAffordance {
    ConnectedAdd,
    Checking,
    DisconnectedAdd,
}

/// Why the "New project..." row refuses, or `None` when it is live.
///
/// The words are not copied: `connect_canvas_copy` is CALLED for the state the
/// affordance names, so this row and the empty-board canvas cannot drift apart.
/// `DisconnectedAdd` asks with `None`, which is that function's own
/// not-connected branch; `Checking` asks with the real snapshot, which is only
/// ever in the checking state when the affordance says so.
///
/// Ledgered: a `CheckFailed` snapshot reaches here as `DisconnectedAdd`, because
/// `provider_inbox_affordance` already collapses the two, so the row says
/// "connect an agent" rather than the canvas's "could not check agents".
fn new_project_disabled(
    affordance: ProviderInboxAffordance,
    snapshot: Option<&AgentConnectionSnapshot>,
) -> Option<BoardMenuDisabled> {
    let (heading, detail) = match affordance {
        ProviderInboxAffordance::ConnectedAdd => return None,
        ProviderInboxAffordance::Checking => connect_canvas_copy(snapshot),
        ProviderInboxAffordance::DisconnectedAdd => connect_canvas_copy(None),
    };
    Some(BoardMenuDisabled {
        suffix: format!("({})", heading.to_lowercase()),
        detail,
    })
}

fn action_lane_total(
    channel_count: usize,
    pending_count: usize,
    shell_retained_count: usize,
) -> usize {
    channel_count
        .saturating_add(pending_count)
        .saturating_add(shell_retained_count)
}

/// One absolute budget shared by worker, subscription, child, and runtime
/// cleanup.  A fresh timeout for each phase would allow a hung phase to turn
/// shutdown into an unbounded chain of waits.
#[derive(Clone, Copy, Debug)]
struct NativeShutdownDeadline {
    at: Instant,
}

impl NativeShutdownDeadline {
    fn from_now(budget: Duration) -> Self {
        Self {
            at: Instant::now() + budget,
        }
    }

    fn until(at: Instant) -> Self {
        Self { at }
    }

    fn remaining(self) -> Duration {
        self.at.saturating_duration_since(Instant::now())
    }

    fn expired(self) -> bool {
        self.remaining().is_zero()
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ReaperKind {
    Worker,
    Child,
    ActionBatch,
}

#[derive(Debug, Default)]
struct ReaperCounts {
    workers: usize,
    children: usize,
    action_batches: usize,
}

#[derive(Debug)]
struct ReaperPermit {
    kind: ReaperKind,
}

fn reaper_counts() -> &'static Mutex<ReaperCounts> {
    static COUNTS: OnceLock<Mutex<ReaperCounts>> = OnceLock::new();
    COUNTS.get_or_init(|| Mutex::new(ReaperCounts::default()))
}

fn acquire_reaper_permit(kind: ReaperKind) -> Option<ReaperPermit> {
    // A timed-out owner remains in the bounded reaper until its handle exits.
    // Reap before checking the cap so a later launch can recover immediately
    // instead of permanently treating completed work as live capacity.
    match kind {
        ReaperKind::Worker => reap_retained_workers(),
        ReaperKind::Child => reap_retained_children(),
        ReaperKind::ActionBatch => reap_retained_action_batches(),
    }
    let mut counts = reaper_counts()
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    let (count, limit) = match kind {
        ReaperKind::Worker => (&mut counts.workers, MAX_RETAINED_WORKERS),
        ReaperKind::Child => (&mut counts.children, MAX_RETAINED_CHILDREN),
        ReaperKind::ActionBatch => (&mut counts.action_batches, MAX_RETAINED_ACTION_BATCHES),
    };
    if *count >= limit {
        return None;
    }
    *count += 1;
    Some(ReaperPermit { kind })
}

impl Drop for ReaperPermit {
    fn drop(&mut self) {
        let mut counts = reaper_counts()
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        match self.kind {
            ReaperKind::Worker => counts.workers = counts.workers.saturating_sub(1),
            ReaperKind::Child => counts.children = counts.children.saturating_sub(1),
            ReaperKind::ActionBatch => {
                counts.action_batches = counts.action_batches.saturating_sub(1)
            }
        }
    }
}

struct OwnedWorker {
    handle: JoinHandle<()>,
    _permit: ReaperPermit,
}

struct OwnedChild {
    child: Child,
    _permit: ReaperPermit,
}

struct OwnedActionBatch {
    outcomes: VecDeque<NativeHostActionOutcome>,
    _permit: ReaperPermit,
}

fn retained_workers() -> &'static Mutex<Vec<OwnedWorker>> {
    static RETAINED: OnceLock<Mutex<Vec<OwnedWorker>>> = OnceLock::new();
    RETAINED.get_or_init(|| Mutex::new(Vec::new()))
}

fn retained_children() -> &'static Mutex<Vec<OwnedChild>> {
    static RETAINED: OnceLock<Mutex<Vec<OwnedChild>>> = OnceLock::new();
    RETAINED.get_or_init(|| Mutex::new(Vec::new()))
}

fn retained_action_batches() -> &'static Mutex<VecDeque<OwnedActionBatch>> {
    static RETAINED: OnceLock<Mutex<VecDeque<OwnedActionBatch>>> = OnceLock::new();
    RETAINED.get_or_init(|| Mutex::new(VecDeque::new()))
}

fn retained_action_emergency() -> &'static Mutex<VecDeque<NativeHostActionOutcome>> {
    static RETAINED: OnceLock<Mutex<VecDeque<NativeHostActionOutcome>>> = OnceLock::new();
    RETAINED.get_or_init(|| Mutex::new(VecDeque::new()))
}

fn reap_retained_workers() {
    let mut workers = retained_workers()
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    let mut pending = Vec::with_capacity(workers.len());
    for worker in workers.drain(..) {
        if worker.handle.is_finished() {
            // Joining an already finished worker cannot block and proves
            // ownership was reaped rather than detached.
            let _ = worker.handle.join();
        } else {
            pending.push(worker);
        }
    }
    *workers = pending;
}

fn reap_retained_children() {
    let mut children = retained_children()
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    children.retain_mut(|child| match child.child.try_wait() {
        Ok(Some(_)) => false,
        Ok(None) | Err(_) => true,
    });
}

fn reap_retained_action_batches() {
    let mut batches = retained_action_batches()
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    batches.retain(|batch| !batch.outcomes.is_empty());
}

fn retain_worker(worker: OwnedWorker) {
    let mut workers = retained_workers()
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    debug_assert!(workers.len() < MAX_RETAINED_WORKERS);
    workers.push(worker);
}

fn retain_child(child: OwnedChild) {
    let mut children = retained_children()
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    debug_assert!(children.len() < MAX_RETAINED_CHILDREN);
    children.push(child);
}

fn retain_action_batch(outcomes: VecDeque<NativeHostActionOutcome>, permit: ReaperPermit) {
    if outcomes.is_empty() {
        drop(permit);
        return;
    }
    let mut batches = retained_action_batches()
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    if batches.len() >= MAX_RETAINED_ACTION_BATCHES {
        drop(batches);
        drop(permit);
        for outcome in outcomes {
            let _ = retain_emergency_action_outcome(outcome);
        }
        return;
    }
    batches.push_back(OwnedActionBatch {
        outcomes,
        _permit: permit,
    });
}

fn retain_emergency_action_outcome(outcome: NativeHostActionOutcome) -> bool {
    let mut retained = retained_action_emergency()
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    if retained.len() >= MAX_ACTION_LANE_RECORDS * MAX_RETAINED_ACTION_BATCHES {
        return false;
    }
    retained.push_back(outcome);
    true
}

pub(crate) fn take_retained_action_outcomes(max: usize) -> Vec<NativeHostActionOutcome> {
    let limit = max.min(MAX_ACTION_LANE_RECORDS);
    let mut outcomes = Vec::with_capacity(limit);
    let mut emergency = retained_action_emergency()
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    while outcomes.len() < limit {
        let Some(outcome) = emergency.pop_front() else {
            break;
        };
        outcomes.push(outcome);
    }
    drop(emergency);
    if outcomes.len() >= limit {
        return outcomes;
    }
    let mut batches = retained_action_batches()
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    while outcomes.len() < limit {
        let Some(mut batch) = batches.pop_front() else {
            break;
        };
        while outcomes.len() < limit {
            let Some(outcome) = batch.outcomes.pop_front() else {
                break;
            };
            outcomes.push(outcome);
        }
        if !batch.outcomes.is_empty() {
            batches.push_front(batch);
            break;
        }
    }
    outcomes
}

fn join_worker_with_deadline(worker: OwnedWorker, deadline: NativeShutdownDeadline) {
    reap_retained_workers();
    let mut worker = Some(worker);
    while !deadline.expired() {
        if worker
            .as_ref()
            .is_some_and(|worker| worker.handle.is_finished())
        {
            let _ = worker.take().expect("finished worker handle").handle.join();
            return;
        }
        std::thread::sleep(Duration::from_millis(2).min(deadline.remaining()));
    }
    if let Some(worker) = worker {
        retain_worker(worker);
    }
}

fn terminate_child_with_deadline(mut child: OwnedChild, deadline: NativeShutdownDeadline) {
    reap_retained_children();
    if child.child.kill().is_err() {
        match child.child.try_wait() {
            Ok(Some(_)) => return,
            Ok(None) | Err(_) => {
                retain_child(child);
                return;
            }
        }
    }
    while !deadline.expired() {
        match child.child.try_wait() {
            Ok(Some(_)) => return,
            Ok(None) => std::thread::sleep(Duration::from_millis(2).min(deadline.remaining())),
            Err(_) => {
                retain_child(child);
                return;
            }
        }
    }
    retain_child(child);
}

/// Wait for a host that has accepted an intentional full-quit request to
/// complete its durable cleanup before releasing the child handle. The host
/// owns the cleanup state machine; killing it immediately after the Accepted
/// receipt could strand the Closing journal. If it outlives the bounded wait,
/// retain the handle for the existing child reaper (the isolated host also has
/// its parent-pid watchdog).
fn wait_for_child_exit_with_deadline(mut child: OwnedChild, deadline: NativeShutdownDeadline) {
    reap_retained_children();
    while !deadline.expired() {
        match child.child.try_wait() {
            Ok(Some(_)) => return,
            Ok(None) => std::thread::sleep(Duration::from_millis(2).min(deadline.remaining())),
            Err(_) => {
                retain_child(child);
                return;
            }
        }
    }
    retain_child(child);
}

pub(crate) fn host_identity_digest_bytes(host: &HostId) -> Vec<u8> {
    match host {
        HostId::LocalProfile(name) => {
            let mut bytes = Vec::with_capacity(1 + name.len());
            bytes.push(b'L');
            bytes.extend_from_slice(name.as_bytes());
            bytes
        }
        HostId::Remote(id) => {
            let mut bytes = Vec::with_capacity(17);
            bytes.push(b'R');
            bytes.extend_from_slice(id);
            bytes
        }
    }
}

fn stable_task_element_id(task_id: TaskId) -> ElementId {
    // Compatibility constructor for local-only callers. Prefer
    // [`stable_host_task_element_id`] whenever a HostTaskKey is available.
    ElementId::Uuid(Uuid::from_bytes(*task_id.as_bytes()))
}

/// The board painter owns this identity now; the shell keeps the old name so
/// the accessibility tree and its tests keep publishing the same node ids.
/// One definition only: see [`crate::ui::board::render::board_row_element_id`].
fn stable_host_task_element_id(key: &HostTaskKey) -> ElementId {
    board_row_element_id(key)
}

/// The board column's width: the narrow rail when it is collapsed, otherwise
/// the user's chosen inbox width held inside the pane's own bounds. A free
/// function because the static geometry helpers have a layout but no shell.
fn board_column_width_for(layout: &KeyedWorkspaceLayout<HostTaskKey>, archived: bool) -> f32 {
    if layout.board_rail && !archived {
        BOARD_RAIL_WIDTH
    } else {
        layout.inbox_width.clamp(INBOX_MIN, INBOX_MAX)
    }
}

/// The accessibility id of a board section. Forwards to the painter's own
/// mapping rather than restating it: two copies would let an id the tree
/// publishes drift from the id the element actually carries, and nothing would
/// go red -- automation would just address a section that is not there.
fn board_group_element_id(group: BoardGroup) -> &'static str {
    crate::ui::board::render::board_group_element_id(group)
}

fn stable_host_task_row_element_id(key: &HostTaskKey) -> String {
    let mut digest = Sha256::new();
    digest.update(b"native-host-task-row");
    digest.update([0]);
    digest.update(host_identity_digest_bytes(&key.host));
    digest.update([0]);
    digest.update(key.task_id.as_bytes());
    let hash = digest.finalize();
    format!(
        "native-task-row-{}",
        hash[..16]
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect::<String>()
    )
}

fn stable_task_element_key(task_id: TaskId, suffix: &str) -> u64 {
    let mut digest = Sha256::new();
    digest.update(b"native-task");
    digest.update([0]);
    digest.update(task_id.as_bytes());
    digest.update([0]);
    digest.update(suffix.as_bytes());
    let bytes: [u8; 8] = digest.finalize()[..8]
        .try_into()
        .expect("sha256 prefixes are always eight bytes");
    u64::from_le_bytes(bytes)
}

/// The accessibility id of one panel's view tab.
///
/// The painted tab's own GPUI id is a tuple of the label and the panel digest,
/// which no accessibility tree can carry, so the tree names the same tab in a
/// form a screen reader (and `activate_accessibility_element`) can round-trip.
/// One builder for the publish and the activation, so they cannot drift.
fn panel_view_tab_element_id(key: &HostTaskKey, view: PaneView) -> String {
    format!(
        "native-panel-tab-{}-{:016x}",
        view.label().to_ascii_lowercase(),
        stable_host_task_element_key(key, "pane")
    )
}

/// The accessibility id of one panel's single primary action.
fn panel_primary_element_id(key: &HostTaskKey) -> String {
    format!(
        "native-panel-primary-{:016x}",
        stable_host_task_element_key(key, "pane")
    )
}

/// Whether the shell must leave this chord to an armed provider terminal.
///
/// Ruling (a): while terminal input is armed, Ctrl+D is EOF and the Ctrl+arrows
/// are word motion, so those three chords belong to the program on the other
/// end of the PTY. Declining means returning WITHOUT stopping propagation,
/// which is what leaves the keystroke reaching the terminal exactly as it does
/// today.
///
/// A free function taking `armed` rather than a method reading it, so both
/// branches are testable without a live PTY -- the armed branch is the one that
/// cannot be reached from a headless shell, and it is the one that matters.
fn armed_terminal_declines_chord(
    keyboard: &KeyboardModel,
    shortcut: KeyboardShortcut,
    terminal_armed: bool,
) -> bool {
    terminal_armed
        && keyboard
            .resolve(shortcut)
            .is_some_and(keyboard_action_yields_to_armed_terminal)
}

