#[derive(Clone, Debug, Eq, PartialEq)]
pub struct NativeActionRecord {
    pub id: &'static str,
    pub focus_epoch: FocusEpoch,
    pub request_generation: u64,
    /// Monotonic UI action capture. A later action invalidates an older one.
    pub action_epoch: u64,
    pub connection_epoch: u64,
    pub client_epoch: u64,
    pub navigation_epoch: u64,
    pub resource_generation: u64,
    pub runtime_generation: u64,
    /// Task identity captured at activation time, never reconstructed by the
    /// transport worker from mutable selection state.
    pub task_id: Option<TaskId>,
    /// Immutable fleet admission captured at activation before queueing.
    /// Preview/test contexts may omit this; live Client enqueue requires an
    /// exact matching admission and never rewrites host/generation/client on
    /// rebind/retry after reconnect.
    pub fleet_admission: Option<FleetAdmission>,
    /// Immutable delete-confirmation provenance. Set only by the explicit
    /// Archive/Delete confirmation dispatcher before enqueue — never inferred
    /// from the current modal or selection. Late outcomes with this flag must
    /// never enter generic Failed/Uncertain retry after cancel/tombstone reclaim.
    pub(crate) purpose: NativeActionPurpose,
    /// A bounded, read-only conversation query for an open background pane.
    /// It is independent of interactive selection but remains fenced to the
    /// exact task and host runtime generations.
    pub(crate) background_read: bool,
    /// Durable task revision and task action epoch observed by the immutable
    /// client model when this action was captured.
    pub expected_task_revision: Option<u64>,
    pub captured_task_action_epoch: Option<u64>,
    /// Capability required by the catalog entry and an explicit disabled
    /// reason when a caller ever records a disabled action.
    pub capability: Option<Capability>,
    pub disabled_reason: Option<String>,
    pub event: ActionEvent,
    /// Every captured action has an explicit typed host command or a typed
    /// HOLD. Read-only actions must never disappear as `None` at dispatch.
    pub command: NativeHostCommand,
}

#[derive(Debug)]
struct NativeActionDispatchFailure {
    /// Captured record when interaction admitted the request before enqueue.
    record: Option<NativeActionRecord>,
    /// True only when the exact record was retained under a reserved lane slot
    /// for parked-submission retry. Captured-but-unretained failures must use
    /// no-record cancellation semantics so the composer never parks an orphan.
    retained: bool,
    message: String,
}

