type ProviderSetupInputCompletion = Arc<Mutex<Option<Result<InputAck, String>>>>;

/// Build one raw-input request for the exact terminal this projection names.
///
/// The projection's own fences travel through unchanged, including the
/// documented plain-shell sentinels (`AgentSessionId::nil()`, a zero provider
/// runtime generation and a zero launch action epoch). The host decides
/// whether that shape is admissible for the terminal it addresses; the client
/// never invents a fence to make one fit.
/// Which of a Task's terminals one client-side pending record belongs to.
///
/// The provider slot is addressed by the legacy provider-only cockpit queries
/// (`Terminal`, `TerminalScroll`, `TerminalResize`, `TerminalReadiness`), and
/// those carry no resource id at all -- a retry armed before any projection
/// has landed has no `ResourceId` to name. Spelling the provider slot as a
/// distinct variant rather than a reserved `ResourceId` keeps "the provider"
/// and "this exact resource" two facts that cannot be confused, and mirrors
/// exactly the two query families the host offers.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
enum TerminalTarget {
    Provider,
    Resource(ResourceId),
}

/// Owner-qualified identity of one terminal surface on one host.
type TerminalKey = (HostTaskKey, TerminalTarget);

impl TerminalTarget {
    /// The terminal a projection describes.
    ///
    /// Shell recognition is the one shared rule on the projection itself, so a
    /// projection decoded from a host that predates plain shells still keys as
    /// the provider slot -- which is the only terminal such a host has.
    fn for_projection(projection: &crate::domain::TaskTerminalProjection) -> Self {
        if projection.is_plain_shell() {
            Self::Resource(projection.resource_id)
        } else {
            Self::Provider
        }
    }

    /// The terminal a screen-producing cockpit query addresses, or `None` when
    /// the query is not one. Resize is deliberately absent: a resize reply is
    /// not admitted as a screen, exactly as before plain shells.
    fn for_screen_query(query: &TaskCockpitQuery) -> Option<Self> {
        match query {
            TaskCockpitQuery::Terminal
            | TaskCockpitQuery::TerminalScroll { .. }
            | TaskCockpitQuery::TerminalReadiness => Some(Self::Provider),
            TaskCockpitQuery::TerminalFor { resource_id }
            | TaskCockpitQuery::TerminalScrollFor { resource_id, .. }
            | TaskCockpitQuery::TerminalReadinessFor { resource_id } => {
                Some(Self::Resource(*resource_id))
            }
            _ => None,
        }
    }

    /// The terminal one strip chip describes.
    ///
    /// A chip may address the provider by its durable resource on the way OUT
    /// (`TerminalFor { resource_id }`), but the provider's screen answers as
    /// `Provider` however it was asked for -- `for_projection` says so. So
    /// anything a REPLY settles, the attachment lease above all, must key the
    /// chip this way and not by its resource id.
    fn for_chip(resource_id: ResourceId, is_provider: bool) -> Self {
        if is_provider {
            Self::Provider
        } else {
            Self::Resource(resource_id)
        }
    }

    /// The surface registry's attachment slot for this terminal.
    ///
    /// The registry spells the same split as `Option<ResourceId>` because it
    /// cannot see this private enum; this is the ONE conversion between them.
    fn surface_target(self) -> crate::ui::task_workspace::surfaces::TerminalSurfaceTarget {
        match self {
            Self::Provider => None,
            Self::Resource(resource_id) => Some(resource_id),
        }
    }

    /// The bounded screen query that addresses this exact terminal.
    fn screen_query(self) -> TaskCockpitQuery {
        match self {
            Self::Provider => TaskCockpitQuery::Terminal,
            Self::Resource(resource_id) => TaskCockpitQuery::TerminalFor { resource_id },
        }
    }

    /// The readiness query that addresses this exact terminal.
    fn readiness_query(self) -> TaskCockpitQuery {
        match self {
            Self::Provider => TaskCockpitQuery::TerminalReadiness,
            Self::Resource(resource_id) => TaskCockpitQuery::TerminalReadinessFor { resource_id },
        }
    }

    /// The scrollback query that addresses this exact terminal.
    fn scroll_query(self, delta_lines: i32) -> TaskCockpitQuery {
        match self {
            Self::Provider => TaskCockpitQuery::TerminalScroll { delta_lines },
            Self::Resource(resource_id) => TaskCockpitQuery::TerminalScrollFor {
                resource_id,
                delta_lines,
            },
        }
    }

    /// The resize query that addresses this exact terminal.
    fn resize_query(self, cols: u16, rows: u16) -> TaskCockpitQuery {
        match self {
            Self::Provider => TaskCockpitQuery::TerminalResize { cols, rows },
            Self::Resource(resource_id) => TaskCockpitQuery::TerminalResizeFor {
                resource_id,
                cols,
                rows,
            },
        }
    }
}

/// One rendered chip on a Task's terminal strip.
///
/// This is presentation only: every field is derived from the host-owned
/// [`TaskTerminalsProjection`], and nothing here is a second copy of strip
/// state that could drift from it.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct TerminalChipRow {
    pub resource_id: ResourceId,
    pub label: String,
    pub selected: bool,
    pub state: crate::domain::cockpit::TerminalRuntimeStateWire,
    pub is_provider: bool,
    /// Redacted working directory as the host reported it, for the hover
    /// tooltip. Display only -- never a path the client may open or send back.
    pub live_cwd: Option<String>,
}

/// Which terminal chip's context menu is open, where it was opened, and any
/// in-progress rename or close confirmation on it.
#[derive(Clone, Debug, PartialEq)]
struct TerminalChipMenu {
    owner: HostTaskKey,
    resource_id: ResourceId,
    position: Point<Pixels>,
    /// Inline rename draft once the Rename row has been chosen.
    rename: Option<String>,
    /// Why the last submitted title was refused, shown under the field. The
    /// menu stays open carrying this so the title can be corrected in place.
    rename_error: Option<String>,
    /// A running terminal takes a second Close to actually close.
    confirming_close: bool,
}

/// The capability one terminal's raw input actually needs.
///
/// Separated from the shell so the rule is provable without a granted-capability
/// fixture: a provider terminal needs `ProviderInput`, a plain shell needs only
/// `TaskCockpit`.
fn terminal_input_capability_granted(granted: CapabilitySet, target: TerminalTarget) -> bool {
    match target {
        TerminalTarget::Provider => granted.contains(Capability::ProviderInput),
        TerminalTarget::Resource(_) => granted.contains(Capability::TaskCockpit),
    }
}

/// Which dock surface paints the Terminal tool for one owner.
///
/// The durable `devmanager-host` connection is bootstrapped into the shell's
/// LOCAL slot -- `attach_host_runtime_attachment` writes `local_slot_mut()`
/// and takes no HostId at all -- so the host this client was started for is
/// always `HostId::LocalProfile` and always takes [`TerminalDockBranch::Local`].
/// [`TerminalDockBranch::Remote`] is for the additional fleet hosts attached
/// through `attach_installed_fleet_host`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum TerminalDockBranch {
    Local,
    Remote,
}

/// Everything the Terminal dock paints for one owner.
///
/// Derived from the ONE admitted strip and separated from the element tree so
/// what the dock shows is assertable without a window: which chips, whether
/// the "+" is live and what it says when it is not, and the empty-state
/// message that replaces the body when no shell is focused.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct TerminalDockModel {
    pub chips: Vec<TerminalChipRow>,
    pub add_enabled: bool,
    pub add_tooltip: String,
    /// `Some` when the splash replaces the dock body.
    pub empty_state: Option<&'static str>,
}

/// Why a Task cannot take another shell.
///
/// Built from the domain constant the host actually enforces, so the number in
/// the message cannot drift from the number in the rule.
fn terminal_shell_cap_message() -> String {
    format!(
        "Task has the maximum of {} shells",
        crate::domain::terminal_facts::MAX_PLAIN_SHELLS_PER_TASK
    )
}

/// The one terminal-title rule the chip menu and the rename dispatch share.
///
/// `validate_terminal_title` is the rule; this only says it in words, and it
/// reads the bound from the same constant rather than re-spelling it.
fn terminal_title_rejection(title: &str) -> Option<String> {
    crate::domain::resource::validate_terminal_title(title)
        .err()
        .map(|_| {
            format!(
                "Title must be 1–{} characters",
                crate::domain::resource::MAX_TERMINAL_TITLE_CHARS
            )
        })
}

/// Hover text for one terminal chip.
///
/// The exit summary and the live working directory are the two facts a chip is
/// too small to show, and both are already redacted by the host. An exited
/// terminal reports why; a running one reports where it is.
pub(crate) fn terminal_chip_tooltip(row: &TerminalChipRow) -> String {
    let mut parts = vec![row.label.clone()];
    match &row.state {
        crate::domain::cockpit::TerminalRuntimeStateWire::Exited { summary } => {
            parts.push(format!("exited · {summary}"));
        }
        crate::domain::cockpit::TerminalRuntimeStateWire::Unknown => {
            parts.push("state unknown".to_string());
        }
        crate::domain::cockpit::TerminalRuntimeStateWire::Running => {}
    }
    if let Some(cwd) = row.live_cwd.as_ref() {
        parts.push(cwd.clone());
    }
    parts.join(" · ")
}

/// Project a Task's terminal strip into its chips, provider first.
///
/// The provider chip leads because it is not in the durable `order` (which is
/// the plain-shell order alone). A resource named by `order` with no matching
/// chip is skipped rather than invented, and a chip's title wins over its
/// launch label. `focused: None` selects nothing -- the caller renders the
/// splash for that state, and a provider chip must not silently absorb it.
pub(crate) fn terminal_chip_rows(
    strip: &crate::domain::cockpit::TaskTerminalsProjection,
) -> Vec<TerminalChipRow> {
    let by_id = strip
        .terminals
        .iter()
        .map(|chip| (chip.resource_id, chip))
        .collect::<BTreeMap<_, _>>();
    let mut rows = Vec::new();
    if let Some(provider) = strip.terminals.iter().find(|chip| chip.is_provider) {
        rows.push(TerminalChipRow {
            resource_id: provider.resource_id,
            label: provider
                .title
                .clone()
                .unwrap_or_else(|| provider.label.clone()),
            selected: strip.focused == Some(provider.resource_id),
            state: provider.runtime_state.clone(),
            is_provider: true,
            live_cwd: provider.live_cwd.clone(),
        });
    }
    for resource_id in &strip.order {
        let Some(chip) = by_id.get(resource_id) else {
            continue;
        };
        rows.push(TerminalChipRow {
            resource_id: *resource_id,
            label: chip.title.clone().unwrap_or_else(|| chip.label.clone()),
            selected: strip.focused == Some(*resource_id),
            state: chip.runtime_state.clone(),
            is_provider: false,
            live_cwd: chip.live_cwd.clone(),
        });
    }
    rows
}

fn terminal_input_request(
    client_id: ClientId,
    terminal: &crate::domain::TaskTerminalProjection,
    input_sequence: u64,
    bytes: Vec<u8>,
) -> Result<TerminalInputRequest, String> {
    let terminal_generation = TerminalGeneration::from_raw(terminal.resource_generation)
        .map_err(|error| format!("terminal generation is invalid: {error}"))?;
    let request = TerminalInputRequest {
        client_id,
        input_id: InputId::new(),
        terminal_id: terminal.terminal_id,
        context: TerminalInputContext {
            task_id: terminal.task_id,
            agent_session_id: terminal.agent_session_id,
            resource_id: terminal.resource_id,
            runtime_generation: terminal.runtime_generation,
            resource_generation: terminal.resource_generation,
            session_id: terminal.session_id,
            terminal_generation,
            focus_epoch: terminal.focus_epoch,
            action_epoch: terminal.action_epoch,
            input_sequence,
        },
        bytes,
    };
    request
        .validate()
        .map_err(|error| format!("terminal input is invalid: {error}"))?;
    Ok(request)
}

fn provider_setup_terminal_input_requests(
    client_id: ClientId,
    terminal: &crate::domain::TaskTerminalProjection,
    provider_kind: ProviderKind,
    allow: bool,
) -> Result<Vec<TerminalInputRequest>, String> {
    // Provider TUIs consume one keyboard gesture at a time. Claude's Ink prompt
    // also enables application-cursor mode, which changes Down from CSI-B to
    // SS3-B. Preserve both the negotiated cursor encoding and the distinct-write
    // choreography used by normal provider composer input.
    let cursor_down = if terminal.screen.mode.app_cursor {
        b"\x1bOB".as_slice()
    } else {
        b"\x1b[B".as_slice()
    };
    let steps: Vec<&[u8]> = match (provider_kind, allow) {
        (ProviderKind::ClaudeCode, true) => vec![cursor_down, b"\r"],
        (ProviderKind::ClaudeCode, false) => vec![b"\r"],
        // Codex's ratatui trust prompt highlights "Yes, continue" by default
        // and explicitly asks for Enter. Numeric characters are editor input,
        // not menu shortcuts, so sending `1` leaves the prompt unchanged.
        (_, true) => vec![b"\r"],
        (_, false) => vec![cursor_down, b"\r"],
    };
    steps
        .iter()
        .enumerate()
        .map(|(index, bytes)| {
            let input_sequence = terminal
                .accepted_input_sequence
                .checked_add(index as u64 + 1)
                .ok_or_else(|| "provider terminal input sequence overflowed".to_string())?;
            terminal_input_request(client_id, terminal, input_sequence, bytes.to_vec())
        })
        .collect()
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct PendingDraftFirstSend {
    /// Immutable owner captured at the Send gesture — never reminted from focus.
    owner: HostTaskKey,
    task_id: TaskId,
    /// Set only after NewConversation is dispatched; None while probing / live-reuse.
    start_command_id: Option<CommandId>,
    control: ComposerControl,
    attachment_only: bool,
    /// Exact provider choice captured with the Send gesture. Promotion, focus,
    /// and asynchronous readiness replies must not recompute it.
    provider_kind: ProviderKind,
    /// Exact model/reasoning/access selection captured with the Send gesture.
    launch_options: crate::providers::ProviderLaunchOptions,
    stage: PendingDraftFirstSendStage,
    captured_draft: String,
    captured_artifact_ids: Vec<crate::domain::id::ArtifactId>,
    captured_image_ids: Vec<u64>,
    /// Exact admission captured with the probe (then start); never reminted.
    fleet_admission: Option<FleetAdmission>,
    connection_epoch: u64,
    resource_generation: u64,
    runtime_generation: u64,
    started_at: Instant,
    readiness_request_id: Option<RequestId>,
    readiness_requested_at: Option<Instant>,
    ready_without_conversation_id: bool,
}

/// Last painted composer layout reused for caret, selection, and pointer hit-testing.
/// Indices are utf-8 byte offsets within each shaped paragraph; conversion to the
/// composer scalar cursor happens at the hit-test boundary.
struct ComposerPaintedLayout {
    lines: Vec<WrappedLine>,
    bounds: Bounds<Pixels>,
    line_height: Pixels,
    text: String,
}

/// Provenance of a parked composer Send relative to the host runtime channel.
/// Never inferred from `last_action_failure`; only exact per-submission state.
#[derive(Clone, Debug)]
enum ComposerSubmissionRetention {
    /// Exact record was retained before runtime enqueue; Retry/Edit draft allowed.
    NeverEnqueued { record: NativeActionRecord },
    /// Runtime accepted the enqueue (or work may have reached the host).
    AwaitingHostOutcome,
}

struct PendingComposerSubmission {
    key: KeyedComposerDraftKey<HostTaskKey>,
    draft: ComposerDraftProjection,
    image_ids: Vec<u64>,
    open_provider_terminal: bool,
    automatic_title_seed: Option<String>,
    retention: ComposerSubmissionRetention,
}

