impl NativeActionDispatchFailure {
    fn before_capture(message: impl Into<String>) -> Self {
        Self {
            record: None,
            retained: false,
            message: message.into(),
        }
    }

    fn after_capture_retained(record: NativeActionRecord, message: impl Into<String>) -> Self {
        Self {
            record: Some(record),
            retained: true,
            message: message.into(),
        }
    }

    fn after_capture_unretained(record: NativeActionRecord, message: impl Into<String>) -> Self {
        Self {
            record: Some(record),
            retained: false,
            message: message.into(),
        }
    }
}

impl NativeActionRecord {
    fn rebind_transport_epochs(&mut self, epochs: NativeHostRuntimeEpochs, navigation_epoch: u64) {
        // Transport/UI epochs may advance after reconnect. Captured fleet
        // host/generation/client must never be rewritten to authorize stale work.
        // Delete-flow confirmation purpose is also immutable across rebind.
        self.connection_epoch = epochs.connection_epoch;
        self.navigation_epoch = navigation_epoch;
        self.resource_generation = epochs.resource_generation;
        self.runtime_generation = epochs.runtime_generation;
    }

    fn is_delete_flow_confirmation(&self) -> bool {
        matches!(self.purpose, NativeActionPurpose::DeleteFlowConfirmation)
    }
}

/// Immutable capture-time purpose for host actions. Ordinary is the default;
/// DeleteFlowConfirmation is set only by the confirmation Archive/Delete
/// dispatcher before enqueue.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
enum NativeActionPurpose {
    #[default]
    Ordinary,
    DeleteFlowConfirmation,
}

/// Owner tag for fleet-delivered projections and stream frames.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct NativeProjectionOwner {
    pub host: HostId,
    pub generation: u64,
    pub client_id: ClientId,
}

impl NativeProjectionOwner {
    fn from_owned<T>(owned: &FleetOwned<T>) -> Self {
        Self {
            host: owned.host.clone(),
            generation: owned.generation,
            client_id: owned.client_id,
        }
    }

    fn from_admission(admission: &FleetAdmission) -> Self {
        Self {
            host: admission.host.clone(),
            generation: admission.generation,
            client_id: admission.client_id,
        }
    }

    fn matches_admission(&self, admission: &FleetAdmission) -> bool {
        self.host == admission.host
            && self.generation == admission.generation
            && self.client_id == admission.client_id
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct OwnedStreamFrame {
    owner: NativeProjectionOwner,
    frame: StreamFrame,
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub enum NativeHostCommand {
    Envelope(crate::domain::command::CommandEnvelope),
    /// Exact already-attached PTY input. Unlike semantic provider input this
    /// remains valid while a provider startup/resume prompt is waiting before
    /// the current-generation SessionStart hook has rebound conversation ID.
    TerminalInput(TerminalInputRequest),
    /// UI-thread browser surface command. It is intentionally not serialized
    /// through the generic host worker: the WebView host owns this exact
    /// lease and must apply it on its GPUI/COM thread.
    Browser(BrowserNativeHostCommand),
    TaskCreate {
        arguments: crate::client::action::TaskCreateArguments,
        command_id: CommandId,
        issued_at_ms: i64,
    },
    TaskCreateV2 {
        arguments: crate::client::action::TaskCreateV2Arguments,
        command_id: CommandId,
        issued_at_ms: i64,
    },
    TaskRename {
        arguments: crate::client::action::TaskRenameArguments,
        expected_task_revision: u64,
        command_id: CommandId,
        issued_at_ms: i64,
    },
    TaskArchive {
        task_id: TaskId,
        expected_task_revision: u64,
        command_id: CommandId,
        issued_at_ms: i64,
    },
    TaskLifecycle {
        task_id: TaskId,
        expected_task_revision: u64,
        command: crate::domain::command::Command,
        command_id: CommandId,
        issued_at_ms: i64,
    },
    ServiceControl {
        action_id: &'static str,
        arguments: crate::client::action::ServiceControlArguments,
        command_id: CommandId,
        issued_at_ms: i64,
    },
    ProviderInput {
        action_id: &'static str,
        arguments: crate::client::action::ProviderInputArguments,
        expected_task_revision: u64,
        command_id: CommandId,
        issued_at_ms: i64,
    },
    ProviderStart {
        arguments: crate::client::action::ProviderStartArguments,
        expected_task_revision: u64,
        command_id: CommandId,
        issued_at_ms: i64,
    },
    /// Canonical `task.show` query via [`crate::client::action::task_show_query`].
    TaskShowQuery {
        request_id: RequestId,
        task_id: TaskId,
    },
    /// Canonical host paged snapshot query for `task.list`.
    TaskListQuery {
        request_id: RequestId,
    },
    /// Host/catalog status observation through the live [`HostClient`] hello seam.
    HostStatusQuery {
        request_id: RequestId,
    },
    AgentConnectionQuery {
        request_id: RequestId,
    },
    /// Local-authority provider settings (no task id). Snapshot/refresh/mutate.
    ProviderSettingsQuery {
        request_id: RequestId,
        request: crate::providers::settings::ProviderSettingsHostRequest,
    },
    RemoteAccessQuery {
        request_id: RequestId,
        request: crate::host::remote_setup::RemoteSetupRequest,
    },
    /// Shared action catalog observation through the live host grant seam.
    HostActionsQuery {
        request_id: RequestId,
    },
    TaskCockpitQuery {
        request_id: RequestId,
        task_id: TaskId,
        query: TaskCockpitQuery,
    },
    /// Host-authority `terminal.open_shell`. Deliberately not a mutation
    /// envelope: the client has no program, arguments, or resolved working
    /// directory to put in one, so it names the Task and its revision fence
    /// and the host builds the durable command.
    OpenShellTerminal {
        request_id: RequestId,
        task_id: TaskId,
        cwd: Option<String>,
        expected_task_revision: u64,
    },
    TerminalClose {
        task_id: TaskId,
        resource_id: crate::domain::ResourceId,
        expected_task_revision: u64,
        command_id: CommandId,
        issued_at_ms: i64,
    },
    TerminalRename {
        arguments: crate::client::action::TerminalRenameArguments,
        expected_task_revision: u64,
        command_id: CommandId,
        issued_at_ms: i64,
    },
    TerminalSetStrip {
        task_id: TaskId,
        strip: crate::domain::terminal_facts::TaskTerminalStrip,
        expected_task_revision: u64,
        command_id: CommandId,
        issued_at_ms: i64,
    },
    PromptLibraryQuery {
        request_id: RequestId,
        query: PromptLibraryQuery,
    },
    Updater {
        request_id: RequestId,
        action: UpdaterAction,
        handoff_ids: NativeUpdateCommandIds,
    },
    /// Explicitly surfaced typed hold. Visible query actions must never map here.
    Hold {
        action_id: &'static str,
        reason: &'static str,
    },
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct NativeUpdateCommandIds {
    prepare: CommandId,
    confirm_drain: CommandId,
    arm_install: CommandId,
    confirm_quit: CommandId,
}

impl NativeUpdateCommandIds {
    fn new() -> Self {
        Self {
            prepare: CommandId::new(),
            confirm_drain: CommandId::new(),
            arm_install: CommandId::new(),
            confirm_quit: CommandId::new(),
        }
    }
}

fn native_command_id(command: &NativeHostCommand) -> Option<CommandId> {
    match command {
        NativeHostCommand::Envelope(envelope) => Some(envelope.command_id),
        NativeHostCommand::Browser(_) | NativeHostCommand::TerminalInput(_) => None,
        NativeHostCommand::TaskCreate { command_id, .. }
        | NativeHostCommand::TaskCreateV2 { command_id, .. }
        | NativeHostCommand::TaskRename { command_id, .. }
        | NativeHostCommand::TaskArchive { command_id, .. }
        | NativeHostCommand::TaskLifecycle { command_id, .. }
        | NativeHostCommand::TerminalClose { command_id, .. }
        | NativeHostCommand::TerminalRename { command_id, .. }
        | NativeHostCommand::TerminalSetStrip { command_id, .. } => Some(*command_id),
        NativeHostCommand::ServiceControl { command_id, .. } => Some(*command_id),
        NativeHostCommand::ProviderInput { command_id, .. } => Some(*command_id),
        NativeHostCommand::ProviderStart { command_id, .. } => Some(*command_id),
        NativeHostCommand::TaskShowQuery { .. }
        | NativeHostCommand::TaskListQuery { .. }
        | NativeHostCommand::HostStatusQuery { .. }
        | NativeHostCommand::AgentConnectionQuery { .. }
        | NativeHostCommand::ProviderSettingsQuery { .. }
        | NativeHostCommand::RemoteAccessQuery { .. }
        | NativeHostCommand::HostActionsQuery { .. }
        | NativeHostCommand::TaskCockpitQuery { .. }
        | NativeHostCommand::PromptLibraryQuery { .. }
        | NativeHostCommand::OpenShellTerminal { .. }
        | NativeHostCommand::Hold { .. } => None,
        NativeHostCommand::Updater {
            action: UpdaterAction::Install,
            handoff_ids,
            ..
        } => Some(handoff_ids.prepare),
        NativeHostCommand::Updater { .. } => None,
    }
}

/// The raw bits of a request id, used as the round-trip log's key.
///
/// The log is deliberately free of domain types so it stays unit testable, so
/// the shell is what turns an id into a key. UUIDs are already unique, so the
/// whole 128 bits go in rather than a hash that could collide two requests
/// into one measurement.
fn request_trace_key(request_id: RequestId) -> u128 {
    u128::from_be_bytes(*request_id.as_bytes())
}

/// Which cockpit surface a request is for. A stable, grepped label — the log
/// exists so "which kind of request is slow" is one grep away.
fn request_trace_kind(command: &NativeHostCommand) -> &'static str {
    match command {
        NativeHostCommand::TaskCockpitQuery { query, .. } => match query {
            TaskCockpitQuery::Conversation { .. }
            | TaskCockpitQuery::OpenConversationSubscription { .. } => "conversation",
            TaskCockpitQuery::Terminal
            | TaskCockpitQuery::TerminalFor { .. }
            | TaskCockpitQuery::TerminalScroll { .. }
            | TaskCockpitQuery::TerminalScrollFor { .. } => "terminal",
            TaskCockpitQuery::TerminalReadiness | TaskCockpitQuery::TerminalReadinessFor { .. } => {
                "terminal-readiness"
            }
            TaskCockpitQuery::TaskTerminals => "task-terminals",
            TaskCockpitQuery::FilesList { .. } | TaskCockpitQuery::FilesRead { .. } => "files",
            TaskCockpitQuery::GitStatus | TaskCockpitQuery::GitStatusTargeted { .. } => {
                "git-status"
            }
            _ => "cockpit",
        },
        NativeHostCommand::TaskShowQuery { .. } => "task-show",
        NativeHostCommand::TaskListQuery { .. } => "task-list",
        NativeHostCommand::HostStatusQuery { .. } => "host-status",
        NativeHostCommand::AgentConnectionQuery { .. } => "agent-connection",
        NativeHostCommand::ProviderSettingsQuery { .. } => "provider-settings",
        NativeHostCommand::RemoteAccessQuery { .. } => "remote-access",
        NativeHostCommand::HostActionsQuery { .. } => "host-actions",
        NativeHostCommand::PromptLibraryQuery { .. } => "prompt-library",
        NativeHostCommand::OpenShellTerminal { .. } => "open-shell-terminal",
        NativeHostCommand::Updater { .. } => "updater",
        _ => "action",
    }
}

/// The round-trip log's key and labels for `record`, or `None` for a command
/// that carries no request id and therefore has no reply to wait for.
fn request_trace_identity(
    record: &NativeActionRecord,
) -> Option<(u128, &'static str, Option<u128>)> {
    let key = request_trace_key(native_request_id(&record.command)?);
    let task = record
        .task_id
        .map(|task_id| u128::from_be_bytes(*task_id.as_bytes()));
    Some((key, request_trace_kind(&record.command), task))
}

fn native_request_id(command: &NativeHostCommand) -> Option<RequestId> {
    match command {
        NativeHostCommand::TaskShowQuery { request_id, .. }
        | NativeHostCommand::TaskListQuery { request_id }
        | NativeHostCommand::HostStatusQuery { request_id }
        | NativeHostCommand::AgentConnectionQuery { request_id }
        | NativeHostCommand::ProviderSettingsQuery { request_id, .. }
        | NativeHostCommand::RemoteAccessQuery { request_id, .. }
        | NativeHostCommand::HostActionsQuery { request_id }
        | NativeHostCommand::TaskCockpitQuery { request_id, .. }
        | NativeHostCommand::PromptLibraryQuery { request_id, .. }
        | NativeHostCommand::OpenShellTerminal { request_id, .. }
        | NativeHostCommand::Updater { request_id, .. } => Some(*request_id),
        _ => None,
    }
}

fn is_agent_connection_query_command(command: &NativeHostCommand) -> bool {
    matches!(command, NativeHostCommand::AgentConnectionQuery { .. })
}

fn is_conversation_query_command(command: &NativeHostCommand) -> bool {
    matches!(
        command,
        NativeHostCommand::TaskCockpitQuery {
            query: TaskCockpitQuery::Conversation { .. },
            ..
        }
    )
}

fn is_native_query_command(command: &NativeHostCommand) -> bool {
    matches!(
        command,
        NativeHostCommand::TaskShowQuery { .. }
            | NativeHostCommand::TaskListQuery { .. }
            | NativeHostCommand::HostStatusQuery { .. }
            | NativeHostCommand::AgentConnectionQuery { .. }
            | NativeHostCommand::ProviderSettingsQuery { .. }
            | NativeHostCommand::RemoteAccessQuery { .. }
            | NativeHostCommand::HostActionsQuery { .. }
            | NativeHostCommand::TaskCockpitQuery { .. }
            | NativeHostCommand::PromptLibraryQuery { .. }
    )
}

fn is_global_native_query_command(command: &NativeHostCommand) -> bool {
    matches!(
        command,
        NativeHostCommand::HostStatusQuery { .. }
            | NativeHostCommand::AgentConnectionQuery { .. }
            | NativeHostCommand::ProviderSettingsQuery { .. }
            | NativeHostCommand::RemoteAccessQuery { .. }
            | NativeHostCommand::HostActionsQuery { .. }
    )
}

fn is_native_query_request(request: &ActionRequest) -> bool {
    matches!(
        request,
        ActionRequest::HostActions
            | ActionRequest::HostStatus
            | ActionRequest::TaskList
            | ActionRequest::TaskShow { .. }
            | ActionRequest::TaskCockpit { .. }
            | ActionRequest::PromptLibrary { .. }
    )
}

fn same_native_action_identity(left: &NativeActionRecord, right: &NativeActionRecord) -> bool {
    if left.purpose != right.purpose {
        return false;
    }
    match (
        native_command_id(&left.command),
        native_command_id(&right.command),
    ) {
        (Some(left_id), Some(right_id)) => left_id == right_id,
        _ => match (
            native_request_id(&left.command),
            native_request_id(&right.command),
        ) {
            (Some(left_id), Some(right_id)) => left_id == right_id,
            _ => {
                left.id == right.id
                    && left.action_epoch == right.action_epoch
                    && left.request_generation == right.request_generation
            }
        },
    }
}

