fn decode_idle_conversation_photo_bytes(bytes: &[u8]) -> Option<Arc<RenderImage>> {
    decode_bounded_render_image_bytes(bytes)
}

fn decode_bounded_render_image_bytes(bytes: &[u8]) -> Option<Arc<RenderImage>> {
    let reader = image::ImageReader::new(std::io::Cursor::new(bytes))
        .with_guessed_format()
        .ok()?;
    let (width, height) = reader.into_dimensions().ok()?;
    if !idle_photo_dimensions_allowed(width, height) {
        return None;
    }
    let format = image::guess_format(bytes).ok()?;
    let mut rgba = image::load_from_memory_with_format(bytes, format)
        .ok()?
        .into_rgba8();
    // GPUI's native image renderer expects BGRA pixel order.
    for pixel in rgba.chunks_exact_mut(4) {
        pixel.swap(0, 2);
    }
    Some(Arc::new(RenderImage::new(vec![image::Frame::new(rgba)])))
}

const IDLE_PHOTO_MAX_DIMENSION: u32 = 4096;
const IDLE_PHOTO_MAX_PIXELS: u64 = 16_000_000;

fn idle_photo_dimensions_allowed(width: u32, height: u32) -> bool {
    if width == 0 || height == 0 {
        return false;
    }
    if width > IDLE_PHOTO_MAX_DIMENSION || height > IDLE_PHOTO_MAX_DIMENSION {
        return false;
    }
    (width as u64).saturating_mul(height as u64) <= IDLE_PHOTO_MAX_PIXELS
}

/// Pure one-shot admission for the idle photo fetch. Separated from spawn so
/// unit tests never exercise the production network branch.
fn admit_idle_conversation_photo_fetch(
    has_selected_task: bool,
    has_cached_image: bool,
    fetch_attempted: bool,
    fetch_in_flight: bool,
) -> bool {
    !has_selected_task && !has_cached_image && !fetch_attempted && !fetch_in_flight
}

fn test_idle_conversation_photo() -> Arc<RenderImage> {
    let pixels = vec![0x40, 0x30, 0x20, 0xff].repeat(4);
    let rgba = image::RgbaImage::from_raw(2, 2, pixels).expect("valid test image dimensions");
    Arc::new(RenderImage::new(vec![image::Frame::new(rgba)]))
}

fn workspace_projection_label(workspace: &crate::domain::task::WorkspaceRef) -> String {
    use crate::domain::task::{WorkspaceBindingKind, WorkspaceRef};

    match workspace {
        WorkspaceRef::Main | WorkspaceRef::MainWithFingerprint { .. } => "main".to_string(),
        WorkspaceRef::Worktree { branch, .. }
        | WorkspaceRef::WorktreeWithFingerprint { branch, .. } => {
            format!("worktree · {}", bounded_header_text(branch.clone()))
        }
        WorkspaceRef::External { .. } | WorkspaceRef::ExternalWithFingerprint { .. } => {
            "external".to_string()
        }
        WorkspaceRef::HostBound { binding } => match binding.kind() {
            WorkspaceBindingKind::Main => "main · host-bound".to_string(),
            WorkspaceBindingKind::Worktree => format!(
                "worktree · {} · host-bound",
                binding
                    .branch()
                    .map(|branch| bounded_header_text(branch.to_string()))
                    .unwrap_or_else(|| "branch unavailable".to_string())
            ),
            WorkspaceBindingKind::External => "external · host-bound".to_string(),
        },
    }
}

fn workspace_context_labels(workspace: &crate::domain::task::WorkspaceRef) -> (String, String) {
    use crate::domain::task::{WorkspaceBindingKind, WorkspaceRef};

    match workspace {
        WorkspaceRef::Main | WorkspaceRef::MainWithFingerprint { .. } => {
            ("Local checkout".to_string(), "main".to_string())
        }
        WorkspaceRef::Worktree { branch, .. }
        | WorkspaceRef::WorktreeWithFingerprint { branch, .. } => (
            "Local worktree".to_string(),
            bounded_header_text(branch.clone()),
        ),
        WorkspaceRef::External { .. } => (
            "External checkout".to_string(),
            "branch unavailable".to_string(),
        ),
        WorkspaceRef::HostBound { binding }
        | WorkspaceRef::ExternalWithFingerprint { binding, .. } => {
            let checkout = match binding.kind() {
                WorkspaceBindingKind::Main => "Local checkout",
                WorkspaceBindingKind::Worktree => "Local worktree",
                WorkspaceBindingKind::External => "External checkout",
            };
            let branch = binding.branch().unwrap_or(match binding.kind() {
                WorkspaceBindingKind::Main => "main",
                WorkspaceBindingKind::Worktree | WorkspaceBindingKind::External => {
                    "branch unavailable"
                }
            });
            (
                checkout.to_string(),
                bounded_header_text(branch.to_string()),
            )
        }
    }
}

fn visible_status_label(status: VisibleTaskStatus) -> &'static str {
    match status {
        VisibleTaskStatus::Disconnected => "Disconnected",
        VisibleTaskStatus::Failed => "Failed",
        VisibleTaskStatus::UncertainOutcome => "Uncertain",
        VisibleTaskStatus::NeedsApproval => "Needs approval",
        VisibleTaskStatus::NeedsAnswer => "Needs answer",
        VisibleTaskStatus::Working => "Working",
        VisibleTaskStatus::Settling => "Settling",
        VisibleTaskStatus::ReadyForReview => "Ready for review",
        VisibleTaskStatus::Idle => "Waiting",
    }
}

fn validate_connected_host_for_shell_launch(
    profile_matches: bool,
    connected: bool,
    _projection_bootstrapped: bool,
) -> Result<(), NativeShellError> {
    if !profile_matches {
        return Err(NativeShellError::HostConnect {
            message: "native host runtime profile binding does not match shell profile".to_string(),
        });
    }
    if !connected {
        return Err(NativeShellError::HostConnect {
            message: "native host runtime is disconnected".to_string(),
        });
    }
    // Projection bootstrap is owned by the single background worker after the
    // shell window attaches. Connect/attach must not wait for snapshot/replay.
    Ok(())
}

fn runtime_connection_visible(
    client_connected: Option<bool>,
    worker_running: bool,
    cancellation: bool,
) -> bool {
    match client_connected {
        Some(connected) => connected,
        // Fleet keeps connection metadata queryable without a HostClient loan.
        // Absence is terminal only when the worker has stopped or cancelled.
        None => worker_running && !cancellation,
    }
}

fn worker_should_run_deferred_bootstrap(bootstrapped: bool) -> bool {
    !bootstrapped
}

/// Fail closed until the host is connected and the canonical ClientModel bootstrap
/// has succeeded. Preview attachment alone must not admit mutations.
fn admits_host_actions(connected: bool, bootstrapped: bool) -> bool {
    connected && bootstrapped
}

fn validated_runtime_attachment(
    profile: &IsolatedDevProfile,
    host_runtime: Option<NativeHostClientRuntime>,
) -> (Option<NativeHostClientRuntime>, NativeHostState) {
    let Some(runtime) = host_runtime else {
        return (None, NativeHostState::Disconnected);
    };
    match runtime.validate_attachment(profile) {
        Ok(()) => {
            let endpoint = runtime.endpoint().to_string();
            (Some(runtime), NativeHostState::Connected { endpoint })
        }
        Err(error) => (
            None,
            NativeHostState::Error {
                message: bounded_host_error(error.to_string()),
            },
        ),
    }
}

fn enqueue_pending_preference(
    pending: &mut VecDeque<RuntimePreferencesSnapshot>,
    preferences: RuntimePreferencesSnapshot,
) {
    if pending.len() >= MAX_PENDING_PREFERENCES {
        pending.pop_front();
    }
    pending.push_back(preferences);
}

#[cfg(test)]
mod terminal_target_tests {
    use super::TerminalTarget;
    use crate::domain::cockpit::{TaskCockpitQuery, TaskTerminalProjection};
    use crate::domain::id::{AgentSessionId, ResourceId, TaskId, TerminalId};

    fn projection(is_provider: bool, resource_id: ResourceId) -> TaskTerminalProjection {
        TaskTerminalProjection {
            task_id: TaskId::new(),
            terminal_id: TerminalId::new(),
            session_id: crate::terminal::protocol::TerminalSessionId::new(),
            agent_session_id: if is_provider {
                AgentSessionId::new()
            } else {
                AgentSessionId::nil()
            },
            resource_id,
            runtime_generation: if is_provider { 1 } else { 0 },
            resource_generation: 1,
            action_epoch: if is_provider { 1 } else { 0 },
            focus_epoch: crate::terminal::protocol::FocusEpoch::initial(),
            accepted_input_sequence: 0,
            accepts_input_without_conversation_id: false,
            sequence: 1,
            title: None,
            text_lines: Vec::new(),
            screen: crate::terminal::session::TerminalScreenSnapshot::default(),
            is_provider,
            runtime_state: crate::domain::cockpit::TerminalRuntimeStateWire::Running,
        }
    }

    /// The whole per-terminal keying rests on this: a pending record armed
    /// when a query goes out must be found again when that query's projection
    /// comes back. The provider slot is named two different ways on the wire
    /// -- a legacy unit query, and a projection carrying a real resource id --
    /// and both must key identically or a retry armed by one is never retired
    /// by the other.
    #[test]
    fn a_provider_query_and_its_projection_key_to_the_same_terminal() {
        let target = TerminalTarget::for_screen_query(&TaskCockpitQuery::Terminal);
        assert_eq!(target, Some(TerminalTarget::Provider));
        assert_eq!(
            TerminalTarget::for_projection(&projection(true, ResourceId::new())),
            TerminalTarget::Provider
        );
        assert_eq!(
            TerminalTarget::for_screen_query(&TaskCockpitQuery::TerminalReadiness),
            Some(TerminalTarget::Provider)
        );
        assert_eq!(
            TerminalTarget::for_screen_query(&TaskCockpitQuery::TerminalScroll { delta_lines: -3 }),
            Some(TerminalTarget::Provider)
        );
        assert!(matches!(
            TerminalTarget::Provider.screen_query(),
            TaskCockpitQuery::Terminal
        ));
    }

    #[test]
    fn a_shell_query_and_its_projection_key_to_the_same_terminal() {
        let resource_id = ResourceId::new();
        assert_eq!(
            TerminalTarget::for_projection(&projection(false, resource_id)),
            TerminalTarget::Resource(resource_id)
        );
        assert_eq!(
            TerminalTarget::for_screen_query(&TaskCockpitQuery::TerminalFor { resource_id }),
            Some(TerminalTarget::Resource(resource_id))
        );
        assert_eq!(
            TerminalTarget::Resource(resource_id).screen_query(),
            TaskCockpitQuery::TerminalFor { resource_id }
        );
        assert_eq!(
            TerminalTarget::Resource(resource_id).readiness_query(),
            TaskCockpitQuery::TerminalReadinessFor { resource_id }
        );
        assert_eq!(
            TerminalTarget::Resource(resource_id).resize_query(80, 24),
            TaskCockpitQuery::TerminalResizeFor {
                resource_id,
                cols: 80,
                rows: 24
            }
        );
    }

    /// A projection from a host that predates plain shells decodes with
    /// `is_provider: false` and still carries a real agent session. Keying it
    /// as a shell would strand every retry armed by the legacy query it
    /// answered.
    #[test]
    fn an_older_hosts_provider_projection_still_keys_as_the_provider_slot() {
        let mut legacy = projection(true, ResourceId::new());
        legacy.is_provider = false;
        assert_eq!(
            TerminalTarget::for_projection(&legacy),
            TerminalTarget::Provider
        );
    }

    /// Two shells on one task are two independent surfaces. Nothing about
    /// them may collapse to one key, or a keystroke echo on one paints on the
    /// other.
    #[test]
    fn two_shells_on_one_task_never_share_a_key() {
        let first = projection(false, ResourceId::new());
        let second = projection(false, ResourceId::new());
        assert_ne!(
            TerminalTarget::for_projection(&first),
            TerminalTarget::for_projection(&second)
        );
    }

    /// Resize does not produce a screen, so it must not be admitted as one --
    /// the behaviour before plain shells, preserved for both query families.
    #[test]
    fn resize_is_not_a_screen_query() {
        assert_eq!(
            TerminalTarget::for_screen_query(&TaskCockpitQuery::TerminalResize {
                cols: 80,
                rows: 24
            }),
            None
        );
        assert_eq!(
            TerminalTarget::for_screen_query(&TaskCockpitQuery::TerminalResizeFor {
                resource_id: ResourceId::new(),
                cols: 80,
                rows: 24
            }),
            None
        );
        assert_eq!(
            TerminalTarget::for_screen_query(&TaskCockpitQuery::TaskTerminals),
            None
        );
    }

    /// Scroll is a screen-producing query, so the same round-trip invariant the
    /// other three obey has to hold for it: the query a target emits must key
    /// back to that exact target, in both families.
    #[test]
    fn a_scroll_query_keys_back_to_the_terminal_that_emitted_it() {
        let resource_id = ResourceId::new();
        for target in [
            TerminalTarget::Provider,
            TerminalTarget::Resource(resource_id),
        ] {
            let query = target.scroll_query(-7);
            assert_eq!(
                TerminalTarget::for_screen_query(&query),
                Some(target),
                "{query:?} must key back to {target:?}"
            );
        }
        assert_eq!(
            TerminalTarget::Provider.scroll_query(-7),
            TaskCockpitQuery::TerminalScroll { delta_lines: -7 }
        );
        assert_eq!(
            TerminalTarget::Resource(resource_id).scroll_query(-7),
            TaskCockpitQuery::TerminalScrollFor {
                resource_id,
                delta_lines: -7
            }
        );
    }
}

