    #[test]
    fn target_composer_geometry_and_affordance_copy_are_pinned() {
        // The shell paints the composer; the composer module says what it
        // looks like. These are the two numbers the SHELL still owns -- how
        // tall the empty field stands and how much room the surfaces above it
        // reserve for it -- read from their one definition.
        // F3: the field is one line tall and grows to six, and the reserve
        // above it is the sum of the composer's parts. Both are asserted
        // part-for-part beside their definitions in `task_cockpit::composer`;
        // here the shell only pins that it reads the same two numbers.
        assert_eq!(COMPOSER_INPUT_MIN_HEIGHT, COMPOSER_LINE_HEIGHT + 12.0);
        assert_eq!(COMPOSER_INPUT_MAX_HEIGHT, 6.0 * COMPOSER_LINE_HEIGHT + 12.0);
        assert!(COMPOSER_HEIGHT_RESERVE < 200.0);
        // F4: the field invites a message to the provider that would answer
        // it, so the placeholder is built from the provider label rather than
        // pinned to one generic sentence. Its rule is asserted where it lives.
        assert_eq!(
            crate::ui::task_cockpit::composer::composer_placeholder("Claude Code"),
            "Message Claude Code\u{2026}"
        );
    }

    #[test]
    fn the_stop_node_exists_only_while_a_turn_is_streaming() {
        use crate::ui::task_cockpit::composer::{
            COMPOSER_SEND_ELEMENT_ID, COMPOSER_STOP_ELEMENT_ID,
        };
        use crate::ui::task_cockpit::TaskList;

        let task_id = TaskId::new();
        let task_list =
            TaskList::from_virtual_task_ids(vec![task_id]).expect("one task fits the inbox");
        let ids_when = |streaming: bool| {
            let composer = ComposerAccessibilityState {
                value: String::new(),
                focused: false,
                startup_loading: false,
                streaming,
            };
            AccessibilityTree::for_task_list_with_projects_and_composer(
                &task_list,
                Some(task_id),
                &NativeHeaderAttachment::default(),
                None,
                &[],
                Some(&composer),
            )
            .gpui_nodes()
            .into_iter()
            .map(|node| node.element_id)
            .collect::<Vec<_>>()
        };

        let quiet = ids_when(false);
        let streaming = ids_when(true);

        // The anchor: if the composer's nodes stop being published at all,
        // the absence assertion below would pass while guarding nothing.
        assert!(
            quiet.iter().any(|id| id == COMPOSER_SEND_ELEMENT_ID),
            "the composer's own nodes must be in the tree for this test to mean anything"
        );
        assert!(
            !quiet.iter().any(|id| id == COMPOSER_STOP_ELEMENT_ID),
            "Stop must not be offered when there is no turn to stop"
        );
        assert!(
            streaming.iter().any(|id| id == COMPOSER_STOP_ELEMENT_ID),
            "a streaming turn publishes exactly one Stop node"
        );
        assert_eq!(
            streaming
                .iter()
                .filter(|id| *id == COMPOSER_STOP_ELEMENT_ID)
                .count(),
            1
        );
        // Streaming adds Stop and takes nothing away, so an assistive client
        // that had focus on another composer node keeps it.
        assert_eq!(
            streaming.len(),
            quiet.len() + 1,
            "streaming adds the Stop node and changes nothing else"
        );
        for id in &quiet {
            assert!(streaming.contains(id), "streaming dropped the node {id}");
        }
    }

    /// Fix wave 1, F4: the composer is ONE sunken field and ONE meta line.
    ///
    /// KNOWN LIMITATION: a source assertion. The footer is built inline in
    /// `task_conversation_surface_for` and GPUI exposes no painted tree to a
    /// headless test, so this is anchored on that function and on the element
    /// ids the footer is built around -- and it asserts the anchor matched, so
    /// a rename fails loudly rather than leaving a guard that guards nothing.
    ///
    /// What it pins: the four rows the user`s `4.png` shows stacked under the
    /// field -- "Claude Code", the three dropdown pills, the quota line and
    /// the "Local checkout / main" strip -- are one line, and the parts that
    /// were controls keep the element ids the accessibility tree publishes.
    #[test]
    fn the_composer_is_one_field_and_one_meta_line() {
        let source = include_str!("native_shell.rs");
        let footer = source
            .split("    fn task_conversation_surface_for(")
            .nth(1)
            .and_then(|tail| tail.split("\n    fn ").next())
            .expect("the composer footer is built in task_conversation_surface_for");
        assert!(
            footer.contains(".id(\"native-task-composer-card\")")
                && footer.contains(".id(\"native-task-composer-input\")")
                && footer.contains(".id(\"native-task-composer-meta\")"),
            "the anchor above has stopped matching and this test is guarding nothing"
        );

        // One meta line, and only one.
        assert_eq!(
            footer.matches(".id(\"native-task-composer-meta\")").count(),
            1,
            "F4 allows exactly one line under the field"
        );
        // Every launch fact the four rows carried is still on it, reached
        // through the ids the accessibility tree publishes and
        // `dispatch_named_accessibility_action` routes.
        for segment in [
            "native-composer-provider",
            "native-composer-model",
            "native-composer-reasoning",
            "native-composer-access",
        ] {
            assert!(
                footer.contains(segment),
                "the meta line dropped the {segment} segment"
            );
        }
        assert!(
            footer.contains("branch_label") && footer.contains("usage_compact_for"),
            "the branch and the quota are segments of the line, not rows of their own"
        );
        // And the rows themselves are gone.
        for gone in [
            "native-task-composer-context-strip",
            "composer_pill",
            "usage_summary_for",
            ".dropdown_caret(",
            "launch_option_controls",
        ] {
            assert!(
                !footer.contains(gone),
                "{gone} belongs to the stacked rows the meta line replaced"
            );
        }
        // The denominator for "no other controls": the only buttons left in
        // the footer are the five conditional ones -- Answer, Reject, Approve
        // and the never-enqueued Retry / Edit draft pair. The provider, model,
        // effort, access and attach pills were five more.
        assert_eq!(
            footer.matches("Button::new(").count(),
            5,
            "the meta line is text, not a row of buttons"
        );

        // The hints and the send slot sit inside the field`s own rule, to its
        // right, as the mockup`s `.compose` does.
        assert!(
            footer.contains(".child(COMPOSER_KEY_HINTS)")
                && footer.contains(".child(send_control)"),
            "the key hints and the send slot belong to the field row"
        );
        // Attach is rule 4`s icon button now, not a labelled `+` pill.
        assert!(
            footer.contains("crate::icons::PLUS")
                && footer.contains(".id(\"native-task-composer-attach\")")
                && !footer.contains(".label(\"+\")"),
            "attach is a 14 px glyph in a 24 px hit box at the line`s right"
        );
    }

    #[test]
    fn the_composer_footer_paints_the_redesign_and_not_the_pill() {
        // KNOWN LIMITATION: a source assertion. GPUI exposes no painted style
        // to a unit test, and the composer footer is built inline inside
        // `task_conversation_surface_for`, so it is anchored on that function
        // name and on the two element ids the footer is built around -- a
        // rename fails loudly rather than silently guarding nothing.
        let source = include_str!("native_shell.rs");
        let footer = source
            .split("    fn task_conversation_surface_for(")
            .nth(1)
            .and_then(|tail| tail.split("\n    fn ").next())
            .expect("the composer footer is built in task_conversation_surface_for");
        assert!(
            footer.contains(".id(\"native-task-composer-card\")")
                && footer.contains(".id(\"native-task-composer-input\")")
                && footer.contains("let send_base = div()"),
            "the anchor above has stopped matching and this test is guarding nothing"
        );

        // Rule 3: a real rule around a sunken input, not a background ring.
        assert!(
            footer.contains(".border(px(COMPOSER_BORDER_WIDTH))")
                && footer.contains(".rounded(px(COMPOSER_RADIUS))")
                && footer.contains(".bg(tokens.surfaces.sunken.to_gpui())"),
            "the composer input is `surfaces.sunken` inside a 1 px rule at radius 6"
        );
        // Rule 11: focus is the focus token, never blue-by-accident.
        assert!(
            footer.contains("tokens.borders.focus.to_gpui()")
                && footer.contains("tokens.borders.default.to_gpui()"),
            "the rule is `borders.default`, and `borders.focus` while focused"
        );
        // Rule 1 allows exactly one elevation, the `raised` overlay, and the
        // slash-command menu is the composer's only overlay. Counted rather
        // than forbidden so a shadow put back on the composer itself is red.
        assert_eq!(
            footer.matches(".shadow_").count(),
            1,
            "the only elevation in the composer footer is the slash menu's"
        );
        assert!(
            footer
                .split(".id(\"native-task-composer-slash-menu\")")
                .nth(1)
                .is_some_and(|tail| tail
                    .split(".children(")
                    .next()
                    .is_some_and(|head| head.contains(".shadow_sm()"))),
            "that one elevation belongs to the slash menu, not to the input"
        );
        // Rule 1: no drop shadow on the composer, and no accent fill anywhere.
        for gone in [
            ".shadow_md()",
            "CONVERSATION_COMPOSER_OUTER_RADIUS",
            "CONVERSATION_COMPOSER_INNER_RADIUS",
            "CONVERSATION_COMPOSER_SEND_DIAMETER",
            "CONVERSATION_COMPOSER_CONTEXT_INSET",
            "tokens.actions.primary.default.background",
            ".rounded_full()",
        ] {
            assert!(
                !footer.contains(gone),
                "the composer keeps no part of the old pill; found {gone}"
            );
        }
        // Rule 4: the send slot is a 24 px icon button that brightens on hover
        // rather than a filled disc, and every part of its look -- glyph, id
        // and tints -- is read from the composer model rather than decided in
        // the painter.
        assert!(
            footer.contains(".size(px(COMPOSER_ICON_BUTTON_SIZE))")
                && footer.contains(
                    "composer_send_look(send_enabled, composer_pending, composer_streaming)"
                )
                && footer.contains(".id(composer_send_element_id(send_look))")
                && footer.contains(".child(composer_send_glyph(send_look))")
                && footer.contains("style.text_color(send_hover.to_gpui())"),
            "the send slot reads its look from the composer model"
        );
        // The Stop arm: the same slot, the same intent path Send uses, and the
        // `surfaces.hover` ground rule 4 gives a destructive icon button.
        assert!(
            footer.contains("ComposerControl::StopTurn")
                && footer.contains("ComposerSendLook::Busy => send_base")
                && footer.contains(".bg(tokens.surfaces.hover.to_gpui())")
                && footer.contains("let composer_streaming = self.composer_turn_is_streaming();"),
            "Stop hangs off the Busy arm and shares the send control's route"
        );
        // Idle is the one arm with no click handler, so a submission in flight
        // cannot be pressed again.
        assert!(
            footer.contains("ComposerSendLook::Idle => send_base,"),
            "a control that cannot act must carry no listener"
        );
    }

