    #[test]
    fn add_project_commit_stays_on_local_host_when_remote_composer_selected() {
        if rerun_headless_shell_test_in_child(
            "ui::native_shell::tests::add_project_commit_stays_on_local_host_when_remote_composer_selected",
        ) {
            return;
        }
        let (runtime, local_shared) = TestRuntime::new(true, NativeHostActionResult::Queued);
        let workspace = tempfile::tempdir().expect("workspace");
        let project_path = workspace.path().display().to_string();
        let profile = isolated_dev_profile(workspace.path()).expect("profile");
        let remote_host = HostId::Remote([0x51; 16]);
        let report = std::rc::Rc::new(std::cell::RefCell::new(None));
        let report_slot = std::rc::Rc::clone(&report);
        gpui::Application::headless().run(move |cx| {
            crate::ui::init(cx);
            let entity = cx.new(|cx| {
                NativeShell::new_with_host_runtime_port(
                    profile,
                    Box::new(runtime),
                    crate::ui::tokens::RuntimePreferencesSnapshot::default(),
                    cx,
                )
            });
            let observed = entity.update(cx, |shell, _cx| {
                shell.install_idle_conversation_photo_for_test();
                let (model, task_id) = terminal_bound_client_model();
                let model = Arc::new(model);
                shell.apply_client_model(Arc::clone(&model)).expect("local");
                shell.local_slot_mut().agent_connection =
                    Some(agent_connection_snapshot(AgentPresence::SignedIn));
                let (remote_runtime, remote_shared) =
                    TestRuntime::new(true, NativeHostActionResult::Queued);
                let epochs = remote_runtime.epochs();
                let mut remote_slot = HostUiState::new_empty(
                    remote_host.clone(),
                    NativeHostState::Connected {
                        endpoint: "https://add-project-remote.example:7443".into(),
                    },
                );
                remote_slot.host_runtime = Some(NativeHostRuntimeAttachment::Injected(Box::new(
                    remote_runtime,
                )));
                let _ = remote_slot.interaction.sync_host_epochs(epochs);
                shell.attach_host_ui_slot(remote_slot).expect("attach");
                shell
                    .apply_client_model_for_host(&remote_host, Arc::clone(&model))
                    .expect("remote model");
                let remote_key = HostTaskKey::new(remote_host.clone(), task_id);
                shell.open_composer_model_selector();
                shell
                    .select_fleet_task_key(remote_key, FleetSelectMode::Replace)
                    .expect("select remote");
                assert_eq!(shell.composer_selector, None);
                assert!(
                    shell.shows_add_project_plus(),
                    "connected local Welcome/Add must remain usable"
                );
                shell.open_add_project();
                {
                    let draft = shell.add_project.as_mut().expect("overlay");
                    draft.name.set_value("Local Only").expect("name");
                    draft.path = project_path.clone();
                }
                shell.commit_add_project();
                let remote_creates = remote_shared
                    .lock()
                    .expect("remote")
                    .accepted
                    .iter()
                    .filter(|record| {
                        matches!(
                            record.command,
                            NativeHostCommand::TaskCockpitQuery {
                                query: TaskCockpitQuery::ConfigCreateProject { .. },
                                ..
                            }
                        )
                    })
                    .count();
                let local_creates = local_shared
                    .lock()
                    .expect("local")
                    .accepted
                    .iter()
                    .filter(|record| {
                        matches!(
                            record.command,
                            NativeHostCommand::TaskCockpitQuery {
                                query: TaskCockpitQuery::ConfigCreateProject { .. },
                                ..
                            }
                        )
                    })
                    .count();
                (remote_creates, local_creates)
            });
            *report_slot.borrow_mut() = Some(observed);
            drop(entity);
            cx.quit();
        });
        let (remote_creates, local_creates) = report.borrow_mut().take().expect("report");
        assert_eq!(
            remote_creates, 0,
            "ConfigCreateProject must never route remotely"
        );
        assert_eq!(
            local_creates, 1,
            "project create must target the local host"
        );
    }

