    #[test]
    fn stale_signed_in_without_canonical_local_authority_hides_add_project() {
        if rerun_headless_shell_test_in_child(
            "ui::native_shell::tests::stale_signed_in_without_canonical_local_authority_hides_add_project",
        ) {
            return;
        }
        let _test_guard = HEADLESS_SHELL_TEST_LOCK
            .get_or_init(|| Mutex::new(()))
            .lock()
            .expect("headless shell test lock");
        let completed = std::rc::Rc::new(std::cell::RefCell::new(None));
        let completed_for_app = std::rc::Rc::clone(&completed);
        gpui::Application::headless().run(move |cx| {
            crate::ui::init(cx);
            let (runtime, shared) = TestRuntime::new(false, NativeHostActionResult::Queued);
            let snapshot = with_test_shell_in_app(cx, runtime, |shell| {
                shell.local_slot_mut().agent_connection =
                    Some(agent_connection_snapshot(AgentPresence::SignedIn));
                // Preview-only: SignedIn agent, no canonical client model.
                assert!(shell.local_slot().client_model.is_none());
                shell.refresh_accessibility_tree();
                let preview_ids = shell
                    .accessibility_tree()
                    .gpui_nodes()
                    .into_iter()
                    .map(|node| node.element_id)
                    .collect::<Vec<_>>();
                let preview_shows = shell.shows_add_project_plus();
                {
                    let mut state = shared.lock().expect("runtime");
                    state.connected = true;
                }
                shell
                    .apply_client_model(Arc::new(empty_canonical_client_model()))
                    .expect("canonical empty");
                shell.restore_connected_host_state();
                shell.refresh_accessibility_tree();
                let empty_shows = shell.shows_add_project_plus();
                let empty_ids = shell
                    .accessibility_tree()
                    .gpui_nodes()
                    .into_iter()
                    .map(|node| node.element_id)
                    .collect::<Vec<_>>();
                (preview_shows, preview_ids, empty_shows, empty_ids)
            });
            *completed_for_app.borrow_mut() = Some(snapshot);
            cx.quit();
        });
        let (preview_shows, preview_ids, empty_shows, empty_ids) =
            completed.borrow().clone().expect("authority snapshot");
        assert!(
            !preview_shows,
            "stale SignedIn without connected bootstrapped local must disable Add project"
        );
        assert!(
            !preview_ids.iter().any(|id| id == "native-projects-add"),
            "AT must not expose Add project without canonical local authority"
        );
        assert!(
            empty_shows,
            "connected canonical empty must enable Add project"
        );
        assert!(
            empty_ids.iter().any(|id| id == "native-projects-add"),
            "canonical empty local workspace must expose Add project"
        );
    }

