    #[test]
    fn native_worker_cancellation_wait_observes_shutdown_without_a_long_sleep() {
        let cancellation = Arc::new(AtomicBool::new(false));
        let cancellation_for_thread = Arc::clone(&cancellation);
        let setter = std::thread::spawn(move || {
            std::thread::sleep(Duration::from_millis(20));
            cancellation_for_thread.store(true, Ordering::Release);
        });
        let runtime = tokio::runtime::Builder::new_current_thread()
            .enable_time()
            .build()
            .expect("test runtime");
        let started = Instant::now();
        runtime.block_on(wait_for_cancellation(cancellation));
        setter.join().expect("cancellation setter");
        assert!(started.elapsed() < Duration::from_secs(1));
    }

    #[test]
    fn native_shutdown_deadline_is_one_absolute_budget() {
        let deadline = NativeShutdownDeadline::from_now(Duration::from_millis(25));
        let first = deadline.remaining();
        std::thread::sleep(Duration::from_millis(3));
        let second = deadline.remaining();
        assert!(second < first);
        assert!(!deadline.expired());
        std::thread::sleep(Duration::from_millis(30));
        assert!(deadline.expired());
        assert_eq!(deadline.remaining(), Duration::ZERO);
    }

    #[test]
    fn empty_inbox_accessibility_requires_a_project_before_agent_actions() {
        use crate::ui::task_cockpit::TaskList;

        let snapshot = agent_connection_snapshot(AgentPresence::SignedIn);
        let tree = AccessibilityTree::for_task_list_with_header(
            &TaskList::empty(),
            None,
            &NativeHeaderAttachment::default(),
            Some(&snapshot),
        );
        let element_ids: Vec<String> = tree
            .gpui_nodes()
            .into_iter()
            .map(|node| node.element_id)
            .filter(|id| !id.is_empty())
            .collect();
        assert!(
            !element_ids
                .iter()
                .any(|id| id == "native-inbox-plus-claude"),
            "project-scoped +Claude must not appear without a project: {element_ids:?}"
        );
        assert!(
            !element_ids.iter().any(|id| id == "native-inbox-plus-codex"),
            "project-scoped +Codex must not appear without a project: {element_ids:?}"
        );
        assert!(
            element_ids.iter().any(|id| id == "native-projects-add"),
            "an empty signed-in inbox must offer Add project: {element_ids:?}"
        );
        let status = tree
            .nodes()
            .into_iter()
            .find(|node| node.element_id() == "native-task-inbox-status")
            .expect("inbox status node");
        assert_eq!(status.name(), "No tasks yet");
        assert_eq!(
            status.description(),
            super::INBOX_EMPTY_STATE_HINT,
            "the painted empty state and its accessible description are one sentence"
        );
    }

    /// Both openness branches of the accessible name. A screen reader has no
    /// stripe and no chip to read, so if the name does not carry the panel
    /// number it hears three open panels as one selection: the same defect the
    /// board paints its way out of, one modality over.
    #[test]
    fn task_row_names_carry_open_and_active_panel_numbers() {
        use crate::ui::task_cockpit::TaskList;

        let project_id = ProjectId::new();
        let active_task = TaskId::new();
        let open_task = TaskId::new();
        let quiet_task = TaskId::new();
        let task_list = TaskList::from_virtual_task_ids(vec![active_task, open_task, quiet_task])
            .expect("three-task list");
        let host = HostId::local_profile("dev").expect("host");
        let item = |task_id: TaskId, open: Option<u8>, active: bool| ProjectInboxItem::Task {
            project_id: Some(project_id),
            task_key: HostTaskKey::new(host.clone(), task_id),
            settled: false,
            archived: false,
            open,
            active,
        };
        let items = vec![
            ProjectInboxItem::Group {
                group: BoardGroup::Working,
                task_count: 3,
                collapsed: false,
            },
            item(active_task, Some(1), true),
            item(open_task, Some(2), false),
            item(quiet_task, None, false),
        ];
        let snapshot = agent_connection_snapshot(AgentPresence::SignedIn);
        let tree = AccessibilityTree::for_task_list_with_projects(
            &task_list,
            Some(active_task),
            &NativeHeaderAttachment::default(),
            Some(&snapshot),
            &items,
        );
        let name_of = |task_id: TaskId| {
            let element_id =
                stable_host_task_row_element_id(&HostTaskKey::new(host.clone(), task_id));
            tree.gpui_nodes()
                .iter()
                .find(|node| node.element_id == element_id)
                .unwrap_or_else(|| panic!("row node for {task_id}"))
                .label
                .clone()
        };
        assert_eq!(
            name_of(active_task),
            format!("Task {active_task} (active, panel 1)"),
            "the focused panel says which panel it is, not just that it is selected"
        );
        assert_eq!(
            name_of(open_task),
            format!("Task {open_task} (open, panel 2)"),
            "an open but unfocused panel is announced as open, with its number"
        );
        assert_eq!(
            name_of(quiet_task),
            format!("Task {quiet_task}"),
            "a task with no panel gains nothing"
        );
    }

    #[test]
    fn project_inbox_accessibility_exposes_group_actions_and_keeps_task_mapping_exact() {
        use crate::ui::task_cockpit::TaskList;

        let project_id = ProjectId::new();
        let task_id = TaskId::new();
        let task_list = TaskList::from_virtual_task_ids(vec![task_id]).expect("single-task list");
        let items = vec![
            ProjectInboxItem::Group {
                group: BoardGroup::Working,
                task_count: 1,
                collapsed: false,
            },
            ProjectInboxItem::Task {
                project_id: Some(project_id),
                task_key: HostTaskKey::new(HostId::local_profile("dev").expect("host"), task_id),
                settled: false,
                archived: false,
                open: None,
                active: false,
            },
            ProjectInboxItem::NewTaskTarget {
                project_key: HostProjectKey::new(
                    HostId::local_profile("dev").expect("host"),
                    project_id,
                ),
                label: "DevManager".to_string(),
            },
        ];
        let snapshot = agent_connection_snapshot(AgentPresence::SignedIn);
        let tree = AccessibilityTree::for_task_list_with_projects(
            &task_list,
            Some(task_id),
            &NativeHeaderAttachment::default(),
            Some(&snapshot),
            &items,
        );
        let host = HostId::local_profile("dev").expect("host");
        let task_key = HostTaskKey::new(host.clone(), task_id);
        let project_key = HostProjectKey::new(host.clone(), project_id);
        let nodes = tree.gpui_nodes();
        // The board's sections replaced the project headers: a live section is
        // a label carrying its count, not an expandable button.
        assert!(nodes.iter().any(|node| {
            node.element_id == board_group_element_id(BoardGroup::Working)
                && node.label == "Working 1"
                && !node.focusable
                && !node.tab_stop
        }));
        // The per-project "+Claude"/"+Codex" buttons are gone. One reachable
        // "New task" per project replaces both, so a project with no tasks yet
        // is still reachable even though the board has no project rows.
        assert!(
            !nodes.iter().any(|node| {
                node.element_id.starts_with("native-project-claude-")
                    || node.element_id.starts_with("native-project-codex-")
            }),
            "the board publishes no per-provider project buttons"
        );
        assert!(nodes.iter().any(|node| {
            node.element_id
                == format!(
                    "native-project-new-task-{}",
                    stable_host_project_element_key(&project_key, "new-task")
                )
                && node.label == "New task in DevManager"
                && node.focusable
                && node.tab_stop
        }));
        assert!(nodes
            .iter()
            .any(|node| node.element_id == "native-task-settle"));
        assert!(!nodes
            .iter()
            .any(|node| node.element_id == "native-task-restore"));

        let (node_id, mapped_task_key) = tree.task_node_ids_for_test()[0].clone();
        assert_eq!(mapped_task_key, task_key);
        let update = tree.platform_update_for_test();
        let task_node = update
            .nodes
            .iter()
            .find(|(candidate, _)| *candidate == node_id)
            .map(|(_, node)| node)
            .expect("mapped task node");
        assert_eq!(
            task_node.author_id(),
            Some(stable_host_task_row_element_id(&task_key).as_str()),
            "project controls inserted ahead of tasks must not corrupt platform task routing"
        );

        let settled_items = vec![
            ProjectInboxItem::Group {
                group: BoardGroup::Done,
                task_count: 1,
                collapsed: false,
            },
            ProjectInboxItem::Task {
                project_id: Some(project_id),
                task_key: HostTaskKey::new(HostId::local_profile("dev").expect("host"), task_id),
                settled: true,
                archived: false,
                open: None,
                active: false,
            },
        ];
        let settled_tree = AccessibilityTree::for_task_list_with_projects(
            &task_list,
            Some(task_id),
            &NativeHeaderAttachment::default(),
            Some(&snapshot),
            &settled_items,
        );
        let settled_nodes = settled_tree.gpui_nodes();
        assert!(settled_nodes
            .iter()
            .any(|node| node.element_id == "native-task-restore"));
        assert!(!settled_nodes
            .iter()
            .any(|node| node.element_id == "native-task-settle"));
    }

    #[test]
    fn task_node_ids_maps_rendered_rows_after_toolbar_nodes() {
        use crate::ui::task_cockpit::TaskList;

        let first = TaskId::new();
        let second = TaskId::new();
        let task_list =
            TaskList::from_virtual_task_ids(vec![first, second]).expect("two-task list");
        let tree = AccessibilityTree::for_task_list_with_header(
            &task_list,
            None,
            &NativeHeaderAttachment::default(),
            None,
        );
        let mapped = tree.task_node_ids_for_test();
        assert_eq!(mapped.len(), 2);
        assert_eq!(mapped[0].1.task_id, first);
        assert_eq!(mapped[1].1.task_id, second);
        let update = tree.platform_update_for_test();
        let toolbar_end = update
            .nodes
            .iter()
            .position(|(_, node)| node.author_id() == Some("native-header-settings"))
            .expect("settings toolbar node");
        let first_row = update
            .nodes
            .iter()
            .position(|(id, _)| *id == mapped[0].0)
            .expect("first task row");
        assert!(first_row > toolbar_end);
        for (node_id, task_key) in mapped {
            let node = update
                .nodes
                .iter()
                .find(|(id, _)| *id == *node_id)
                .map(|(_, node)| node)
                .expect("platform node");
            let expected = stable_host_task_row_element_id(task_key);
            assert_eq!(
                node.author_id(),
                Some(expected.as_str()),
                "pre-order id must match the rendered row"
            );
        }
    }

    #[test]
    fn selected_task_accessibility_exposes_the_conversation_composer() {
        use crate::ui::task_cockpit::TaskList;

        let task_id = TaskId::new();
        let task_list = TaskList::from_virtual_task_ids(vec![task_id]).expect("single-task list");
        let tree = AccessibilityTree::for_task_list_with_header(
            &task_list,
            Some(task_id),
            &NativeHeaderAttachment::default(),
            None,
        );
        let nodes = tree.gpui_nodes();
        let prompt = nodes
            .iter()
            .find(|node| node.element_id == "native-task-composer-input")
            .expect("prompt field");
        assert_eq!(prompt.role, AccessibleRole::TextField);
        assert!(prompt.focusable && prompt.tab_stop);
        let platform_update = tree.platform_update_for_test();
        let platform_prompt = platform_update
            .nodes
            .iter()
            .find_map(|(_, node)| {
                (node.author_id() == Some("native-task-composer-input")).then_some(node)
            })
            .expect("platform prompt field");
        assert!(platform_prompt.supports_action(accesskit::Action::Focus));
        assert!(platform_prompt.supports_action(accesskit::Action::SetValue));
        assert_eq!(platform_prompt.value(), Some(""));
        let attach = nodes
            .iter()
            .find(|node| node.element_id == "native-task-composer-attach")
            .expect("attach button");
        assert_eq!(attach.role, AccessibleRole::Button);
        let send = nodes
            .iter()
            .find(|node| node.element_id == "native-task-composer-send")
            .expect("send button");
        assert_eq!(send.role, AccessibleRole::Button);
        assert!(send.focusable && send.tab_stop);

        let add_action = nodes
            .iter()
            .find(|node| node.element_id == "native-shell-tools-affordance")
            .expect("Add action button");
        assert_eq!(add_action.role, AccessibleRole::Button);
        assert!(add_action.focusable && add_action.tab_stop);

        for (element_id, label) in [
            ("native-dock-tab-changes", "Changes"),
            ("native-dock-tab-files", "Files"),
            ("native-dock-tab-browser", "Browser"),
            ("native-dock-tab-services", "Services"),
            ("native-dock-tab-artifacts", "Artifacts"),
            ("native-dock-tab-review", "Review"),
        ] {
            let tab = nodes
                .iter()
                .find(|node| node.element_id == element_id)
                .unwrap_or_else(|| panic!("missing accessible {label} dock tab"));
            assert_eq!(tab.role, AccessibleRole::Button);
            assert_eq!(tab.label, label);
            assert!(tab.focusable && tab.tab_stop);

            let platform_tab = platform_update
                .nodes
                .iter()
                .find_map(|(_, node)| (node.author_id() == Some(element_id)).then_some(node))
                .unwrap_or_else(|| panic!("missing platform {label} dock tab"));
            assert!(platform_tab.supports_action(accesskit::Action::Click));
        }
    }

    #[test]
    fn native_conversation_composer_shares_readable_measure_and_tools_affordance() {
        if rerun_headless_shell_test_in_child(
            "ui::native_shell::tests::native_conversation_composer_shares_readable_measure_and_tools_affordance",
        ) {
            return;
        }
        assert_eq!(CONVERSATION_CONTENT_MAX_WIDTH, 768.0);
        assert!(
            WorkspaceLayout::default().dock_collapsed,
            "conversation-first layouts start with the dock collapsed"
        );
        let (runtime, _) = TestRuntime::new(true, NativeHostActionResult::Queued);
        let _guard = HEADLESS_SHELL_TEST_LOCK
            .get_or_init(|| Mutex::new(()))
            .lock()
            .expect("headless shell test lock");
        gpui::Application::headless().run(|cx| {
            crate::ui::init(cx);
            with_test_shell_in_app_cx(cx, runtime, |shell, _cx| {
                assert!(shell.layout.dock_collapsed);
                // The right dock is retired (spec 6.2): its tools are panel
                // views, so the toggle that used to open it must not, or the
                // same tool would paint twice on one screen. The assertion is
                // inverted rather than deleted -- this is the rule now.
                shell.toggle_pane(PaneEdge::Dock);
                assert!(
                    shell.layout.dock_collapsed,
                    "the retired dock must stay closed however it is asked to open"
                );
                shell.dispatch_named_accessibility_action("native-shell-context-dock-toggle");
                assert!(shell.layout.dock_collapsed);
            });
            cx.quit();
        });
    }

    #[test]
    fn native_conversation_shift_enter_keeps_newline_and_enter_sends() {
        if rerun_headless_shell_test_in_child(
            "ui::native_shell::tests::native_conversation_shift_enter_keeps_newline_and_enter_sends",
        ) {
            return;
        }
        let _guard = HEADLESS_SHELL_TEST_LOCK
            .get_or_init(|| Mutex::new(()))
            .lock()
            .expect("headless shell test lock");
        gpui::Application::headless().run(|cx| {
            crate::ui::init(cx);
            let (runtime, _) = TestRuntime::new(true, NativeHostActionResult::Queued);
            let (model, task_id) = terminal_bound_client_model();
            with_test_shell_in_app_cx(cx, runtime, |shell, _cx| {
                shell
                    .apply_client_model(Arc::new(model))
                    .expect("apply model");
                let list = crate::ui::task_cockpit::TaskList::from_client_model_virtual(
                    shell.client_model_snapshot().as_ref().unwrap(),
                )
                .expect("task list");
                let _ = shell.local_slot_mut().interaction.navigation_mouse_down(task_id, &list);
                shell.sync_cockpit_follow();
                shell
                    .replace_composer_platform_text(None, "line one")
                    .expect("seed draft");
                shell.composer_key_for_test("enter", true, false);
                assert_eq!(
                    shell.composer.as_ref().expect("composer").draft_text(),
                    "line one\n"
                );
                let utf16_len = "line one\n".encode_utf16().count();
                shell
                    .replace_composer_platform_text(Some(0..utf16_len), "ready to send")
                    .expect("replace draft");
                assert_eq!(
                    shell.composer.as_ref().expect("composer").draft_text(),
                    "ready to send"
                );
                shell.composer_key_for_test("enter", false, false);
                let pending = shell
                    .composer
                    .as_ref()
                    .and_then(TaskComposer::pending_intent)
                    .is_some();
                let queued = !shell.pending_composer_submissions.is_empty();
                let errored = shell.local_slot_mut().composer_error.is_some();
                assert!(
                    pending || queued || errored,
                    "Enter without Shift must invoke the send path (pending={pending} queued={queued} error={:?})",
                    shell.local_slot_mut().composer_error
                );
                assert_eq!(
                    shell.composer.as_ref().expect("composer").draft_text(),
                    "ready to send",
                    "Enter must not insert a newline"
                );
            });
            cx.quit();
        });
    }

