    #[test]
    fn initial_projection_failure_reconnects_before_the_shell_stays_degraded() {
        let source = include_str!("native_shell.rs");
        let start = source
            .find("fn recover_deferred_bootstrap_projection(")
            .expect("initial bootstrap recovery function");
        let end = source[start..]
            .find("\nfn publish_cancelled_action_outcome(")
            .map(|offset| start + offset)
            .expect("initial bootstrap recovery function end");
        let body = &source[start..end];

        assert!(
            body.contains("reconnect_fleet_host("),
            "a failed initial snapshot must reconnect through fleet instead of retrying a retired client forever"
        );
        assert!(
            body.contains("bootstrapped.store(true, Ordering::Release)"),
            "successful recovery must publish canonical mutation authority"
        );
        assert!(
            body.contains("publish_resync_handoff_projections("),
            "recovery must publish through the shared resync handoff (epoch bump + replay)"
        );
        assert!(
            body.contains("reconnect_source"),
            "recovery must carry the exact trusted/local reconnect source"
        );
    }

    #[test]
    fn subscription_resync_does_not_cancel_an_admitted_wire_exchange() {
        let source = include_str!("native_shell.rs");
        let start = source
            .find("fn reconnect_fleet_host(")
            .expect("resync function");
        let end = source[start..]
            .find("\nfn publish_projection(")
            .map(|offset| start + offset)
            .expect("resync function end");
        let body = &source[start..end];

        assert!(
            body.contains("reconnect_local starts, the rotating grant must settle")
                || body.contains("HostFleet even if this waiter is cancelled"),
            "cancelling the waiter must not drop an admitted local reconnect grant"
        );
        assert!(
            body.contains("wait_for_cancellation"),
            "resync waiters must observe shutdown without a full uninterruptible sleep"
        );
    }

