    fn query_admission_failures_are_discarded_without_durable_retention(cx: &mut gpui::App) {
        let (runtime, shared) = TestRuntime::new(true, NativeHostActionResult::Queued);
        let disconnected = with_test_shell_in_app(cx, runtime, |shell| {
            shared.lock().expect("test runtime state").connected = false;
            let returned = shell
                .dispatch_action_for_test(crate::ui::components::ActionRequest::HostStatus)
                .is_some();
            (
                returned,
                shell.last_action_failure().cloned(),
                shell.pending_action_for_test().cloned(),
                shell.last_query_detail().map(str::to_string),
                matches!(
                    shell.local_slot_mut().host_state,
                    NativeHostState::Disconnected
                ),
            )
        });
        assert!(
            disconnected.0,
            "the caller still observes that the query was not admitted"
        );
        assert_eq!(
            disconnected.1, None,
            "a disconnected query admission is not a durable action failure"
        );
        assert_eq!(
            disconnected.2, None,
            "a disconnected query admission must not enter the retry lane"
        );
        assert!(
            disconnected
                .3
                .as_deref()
                .is_some_and(|detail| detail.contains("disconnected")),
            "the panel-local query detail must explain the admission failure: {:?}",
            disconnected.3
        );
        assert!(
            disconnected.4,
            "the header may still reflect the runtime's real disconnected state"
        );

        let (runtime, _shared) = TestRuntime::new(true, NativeHostActionResult::QueueFull);
        let saturated = with_test_shell_in_app(cx, runtime, |shell| {
            let returned = shell
                .dispatch_action_for_test(crate::ui::components::ActionRequest::HostStatus)
                .is_some();
            (
                returned,
                shell.last_action_failure().cloned(),
                shell.pending_action_for_test().cloned(),
                shell.last_query_detail().map(str::to_string),
                matches!(
                    shell.local_slot_mut().host_state,
                    NativeHostState::Connected { .. }
                ),
            )
        });
        assert!(
            saturated.0,
            "the caller still observes that the query was not admitted"
        );
        assert_eq!(
            saturated.1, None,
            "a saturated query admission is not a durable action failure"
        );
        assert_eq!(
            saturated.2, None,
            "a saturated query admission must not enter the retry lane"
        );
        assert!(
            saturated
                .3
                .as_deref()
                .is_some_and(|detail| detail.contains("busy")),
            "the panel-local query detail must explain queue pressure: {:?}",
            saturated.3
        );
        assert!(
            saturated.4,
            "queue pressure must preserve the runtime's connected state"
        );

        // Remote same TaskId must not overwrite local query detail.
        let remote_host = HostId::Remote([0x61; 16]);
        let (runtime, local_shared) = TestRuntime::new(true, NativeHostActionResult::Queued);
        let isolated = with_test_shell_in_app(cx, runtime, |shell| {
            local_shared.lock().expect("local").connected = false;
            let _ =
                shell.dispatch_action_for_test(crate::ui::components::ActionRequest::HostStatus);
            let local_detail = shell.last_query_detail().map(str::to_string);
            let (remote_runtime, remote_shared) =
                TestRuntime::new(true, NativeHostActionResult::QueueFull);
            let epochs = remote_runtime.epochs();
            let mut remote_slot = HostUiState::new_empty(
                remote_host.clone(),
                NativeHostState::Connected {
                    endpoint: "https://query-admit-remote.example:7443".into(),
                },
            );
            remote_slot.host_runtime = Some(NativeHostRuntimeAttachment::Injected(Box::new(
                remote_runtime,
            )));
            let _ = remote_slot.interaction.sync_host_epochs(epochs);
            shell.attach_host_ui_slot(remote_slot).expect("attach");
            let (model, task_id) = terminal_bound_client_model();
            let model = Arc::new(model);
            shell
                .apply_client_model_for_host(&remote_host, Arc::clone(&model))
                .expect("remote model");
            let _ = shell.dispatch_action_recorded_for_owner(
                &remote_host,
                crate::ui::components::ActionRequest::TaskCockpit {
                    task_id,
                    query: TaskCockpitQuery::Terminal,
                },
            );
            let remote_detail = shell
                .host_slot(&remote_host)
                .and_then(|slot| slot.last_query_detail.clone());
            let remote_retained = shell
                .host_slot(&remote_host)
                .is_some_and(|slot| !slot.pending_host_actions.is_empty());
            let local_detail_after = shell.last_query_detail().map(str::to_string);
            let remote_accepted = remote_shared.lock().expect("remote").accepted.len();
            (
                local_detail,
                remote_detail,
                remote_retained,
                local_detail_after,
                remote_accepted,
            )
        });
        assert!(
            isolated
                .0
                .as_deref()
                .is_some_and(|detail| detail.contains("disconnected")),
            "local disconnected detail must remain: {:?}",
            isolated.0
        );
        assert!(
            isolated
                .1
                .as_deref()
                .is_some_and(|detail| detail.contains("busy")),
            "remote queue-full detail must stay on the remote slot: {:?}",
            isolated.1
        );
        assert!(
            !isolated.2,
            "remote query admission must not enter durable retry"
        );
        assert_eq!(
            isolated.0, isolated.3,
            "remote same-TaskId query failure must not rewrite local last_query_detail"
        );
        assert_eq!(
            isolated.4, 0,
            "remote query must not enqueue while saturated"
        );
    }

    /// The original complaint in one scenario: while the snapshot is still
    /// paging, the center must NAME the wait rather than claim the conversation
    /// is live, and New task must refuse with a named cause rather than doing
    /// nothing at all.
    fn startup_phase_line_replaces_liveness_and_gates_task_creation(cx: &mut gpui::App) {
        use crate::ui::task_cockpit::shell::CONVERSATION_LIVE_HOLD_COPY;

        let (runtime, shared) = TestRuntime::new(true, NativeHostActionResult::Queued);
        let (model, task_id) = open_task_without_agent_client_model();
        with_test_shell_in_app(cx, runtime, |shell| {
            // The fixture seeds Ready, and reaching Ready is sticky. This
            // scenario is about a client that has NEVER been Ready, so it takes
            // a fresh trace rather than trying to rewind a sticky flag.
            shell.startup_trace = SharedStartupTrace::detached();
            let epochs = shared.lock().expect("test runtime state").epochs;
            shared
                .lock()
                .expect("test runtime state")
                .projections
                .push_back(NativeHostProjection::client_model(Arc::new(model)).at_epochs(epochs));
            let _ = shell.drain_host_projections(MAX_PENDING_HOST_ACTIONS);
            let owner = shell.local_task_key(task_id);
            shell.selected_task_key = Some(owner.clone());

            // Still paging: an admitted preview is not an admitted conversation.
            shell
                .startup_trace()
                .enter(StartupPhase::SnapshotPages, None);
            let line = shell
                .startup_status_line()
                .expect("a client below Ready always paints a line");
            assert!(
                line.primary.starts_with("Loading tasks"),
                "the paging phase names itself: {line:?}"
            );
            let hold = shell.conversation_hold_copy_for_owner(&owner);
            assert_eq!(
                hold.as_deref(),
                Some(line.primary.as_str()),
                "the hold repeats the phase line"
            );
            assert_ne!(
                hold.as_deref(),
                Some(CONVERSATION_LIVE_HOLD_COPY),
                "nothing may claim liveness before a canonical model is admitted"
            );

            assert!(
                shell.startup_gates_actions(),
                "New task is disabled below Ready"
            );
            shell.begin_new_task();
            assert!(
                shell.new_task.is_none(),
                "a create gesture must not open a draft while loading"
            );
            let refusal = shell
                .local_slot_mut()
                .composer_error
                .clone()
                .expect("a refused create names its cause");
            assert!(
                refusal.contains("still loading tasks"),
                "the refusal must name which check refused it: {refusal}"
            );

            // Ready: the line is gone and both affordances come back.
            shell.startup_trace().enter(StartupPhase::Ready, None);
            assert_eq!(shell.startup_status_line(), None);
            assert!(!shell.startup_gates_actions());
            assert_eq!(
                shell.conversation_hold_copy_for_owner(&owner).as_deref(),
                Some(CONVERSATION_LIVE_HOLD_COPY),
                "the liveness copy is honest once the model is admitted"
            );
            shell.local_slot_mut().composer_error = None;
        });
    }

    /// A reconnect after the session has loaded is a wait worth NAMING and not
    /// a reason to take the buttons away: most resyncs settle in milliseconds,
    /// and a disabled New task that flickers reads as a broken control rather
    /// than as a state.
    fn a_post_ready_resync_paints_the_phase_line_without_disabling_actions(cx: &mut gpui::App) {
        let (runtime, _shared) = TestRuntime::new(true, NativeHostActionResult::Queued);
        with_test_shell_in_app(cx, runtime, |shell| {
            // A client that has never been Ready: gated, and saying why.
            shell.startup_trace = SharedStartupTrace::detached();
            shell
                .startup_trace()
                .enter(StartupPhase::SnapshotPages, None);
            assert!(shell.startup_gates_actions());

            shell.startup_trace().enter(StartupPhase::Ready, None);
            assert!(!shell.startup_gates_actions());
            assert_eq!(
                shell.startup_status_line(),
                None,
                "a Ready client paints no loading line"
            );

            // A post-Ready NeedsResync re-enters Synchronize.
            shell.startup_trace().retry_in(
                StartupPhase::Synchronize,
                Some("fleet resync (transport reconnect=false)".to_string()),
            );
            assert_eq!(
                shell.startup_trace().current(),
                StartupPhase::Synchronize,
                "a resync rewinds the phase so the wait can be named"
            );
            let line = shell
                .startup_status_line()
                .expect("a reconnect paints the same phase line");
            assert_eq!(line.primary, "Synchronizing\u{2026}");
            assert!(
                !shell.startup_gates_actions(),
                "a reconnect must never disable New task on a loaded session"
            );
        });
    }

    fn action_outcome_retention_pressure_keeps_exact_overflow_record(cx: &mut gpui::App) {
        let (runtime, _shared) = TestRuntime::new(true, NativeHostActionResult::Queued);
        let (pending_len, overflow, failure) = with_test_shell_in_app(cx, runtime, |shell| {
            for _ in 0..MAX_RETRY_HOST_ACTIONS {
                let action = shell
                    .local_slot_mut()
                    .interaction
                    .action(test_task_create_v2("retry-lane mutation"))
                    .expect("retry-lane action identity");
                assert!(shell.retain_pending_host_action(action));
            }
            let overflow = shell
                .local_slot_mut()
                .interaction
                .action(test_task_create_v2("outcome overflow mutation"))
                .expect("outcome overflow identity");
            shell.apply_action_outcome(NativeHostActionOutcome::Uncertain {
                action: overflow.clone(),
                error: "outcome pressure".to_string(),
            });
            let observed = (
                shell.local_slot_mut().pending_host_actions.len(),
                shell.local_slot_mut().retained_action_overflow.clone(),
                (overflow, shell.last_action_failure().cloned()),
            );
            // This scenario verifies the live bounded lanes. It must not leave
            // its synthetic pressure records for the following drop scenario,
            // which owns the process-global shutdown-retention assertion.
            shell.local_slot_mut().pending_host_actions.clear();
            shell.local_slot_mut().retained_action_overflow = None;
            observed
        });
        assert_eq!(pending_len, MAX_RETRY_HOST_ACTIONS);
        assert_eq!(overflow, Some(failure.0));
        assert!(matches!(
            failure.1,
            Some(NativeHostActionFailure::ExecutionUncertain { .. })
        ));
    }

    fn native_shell_drop_retains_pending_overflow_and_deferred_as_uncertain(cx: &mut gpui::App) {
        let _ = take_retained_action_outcomes(MAX_ACTION_LANE_RECORDS);
        let (runtime, shared) = TestRuntime::new(true, NativeHostActionResult::Queued);
        let expected = with_test_shell_in_app(cx, runtime, |shell| {
            let pending = shell
                .local_slot_mut()
                .interaction
                .action(crate::ui::components::ActionRequest::HostStatus)
                .expect("pending action");
            let overflow = shell
                .local_slot_mut()
                .interaction
                .action(crate::ui::components::ActionRequest::HostStatus)
                .expect("overflow action");
            let deferred = shell
                .local_slot_mut()
                .interaction
                .action(crate::ui::components::ActionRequest::HostStatus)
                .expect("deferred action");
            let runtime_pending = shell
                .local_slot_mut()
                .interaction
                .action(crate::ui::components::ActionRequest::HostStatus)
                .expect("runtime pending action");
            shell
                .local_slot_mut()
                .pending_host_actions
                .push_back(pending.clone());
            shell.local_slot_mut().retained_action_overflow = Some(overflow.clone());
            let mut state = shared.lock().expect("test runtime state");
            state.pending.push_back(runtime_pending.clone());
            state.deferred = Some(NativeHostActionOutcome::Failed {
                action: deferred.clone(),
                error: "deferred failure".to_string(),
            });
            vec![pending, overflow, runtime_pending, deferred]
        });

        let outcomes = take_retained_action_outcomes(MAX_ACTION_LANE_RECORDS);
        let actual = outcomes
            .iter()
            .map(|outcome| match outcome {
                NativeHostActionOutcome::Uncertain { action, .. } => action.clone(),
                other => panic!("shell drop must retain uncertainty, got {other:?}"),
            })
            .collect::<Vec<_>>();
        assert_eq!(actual, expected);
    }

    #[test]
    fn shutdown_handoff_retains_disconnected_pending_actions_as_uncertain() {
        let _ = take_retained_action_outcomes(MAX_ACTION_LANE_RECORDS);
        let (command_tx, command_rx) = std::sync::mpsc::sync_channel(1);
        drop(command_rx);
        let mut interaction = NativeInteraction::new(Some(TaskId::new()));
        let first = interaction
            .action(crate::ui::components::ActionRequest::HostStatus)
            .expect("first pending action");
        let second = interaction
            .action(crate::ui::components::ActionRequest::HostStatus)
            .expect("second pending action");
        let expected = vec![first.clone(), second.clone()];
        let permit = acquire_reaper_permit(ReaperKind::ActionBatch).expect("action batch permit");
        {
            let _probe = PendingShutdownDropProbe {
                pending: VecDeque::from([first, second]),
                command_tx,
                deadline: NativeShutdownDeadline::from_now(Duration::from_secs(1)),
                permit: Some(permit),
            };
        }
        let outcomes = take_retained_action_outcomes(MAX_ACTION_LANE_RECORDS);
        let actual = outcomes
            .iter()
            .map(|outcome| match outcome {
                NativeHostActionOutcome::Uncertain { action, .. } => action.clone(),
                other => panic!("unexpected shutdown outcome: {other:?}"),
            })
            .collect::<Vec<_>>();
        assert_eq!(actual, expected);
    }

    #[test]
    fn shutdown_handoff_retains_deadline_expired_pending_actions_without_resend() {
        let _ = take_retained_action_outcomes(MAX_ACTION_LANE_RECORDS);
        let (command_tx, command_rx) = std::sync::mpsc::sync_channel(2);
        let mut interaction = NativeInteraction::new(Some(TaskId::new()));
        let filler = interaction
            .action(crate::ui::components::ActionRequest::HostStatus)
            .expect("filler action");
        let pending_action = interaction
            .action(crate::ui::components::ActionRequest::HostStatus)
            .expect("pending action");
        command_tx
            .try_send(NativeHostWorkerCommand::Execute(filler))
            .expect("fill command channel");
        let expected_action = pending_action.clone();
        let permit = acquire_reaper_permit(ReaperKind::ActionBatch).expect("action batch permit");
        {
            let _probe = PendingShutdownDropProbe {
                pending: VecDeque::from([pending_action]),
                command_tx: command_tx.clone(),
                deadline: NativeShutdownDeadline::from_now(Duration::from_secs(1)),
                permit: Some(permit),
            };
        }
        let outcomes = take_retained_action_outcomes(MAX_ACTION_LANE_RECORDS);
        assert!(matches!(
            outcomes.as_slice(),
            [NativeHostActionOutcome::Uncertain { action, .. }] if action == &expected_action
        ));
        assert!(matches!(
            command_rx.try_recv(),
            Ok(NativeHostWorkerCommand::Execute(_))
        ));
        assert!(
            command_rx.try_recv().is_err(),
            "pending action must not be enqueued after shutdown cancellation"
        );
    }

    #[test]
    fn action_admission_and_outcome_durability() {
        if rerun_headless_shell_test_in_child(
            "ui::native_shell::tests::action_admission_and_outcome_durability",
        ) {
            return;
        }
        // GPUI's Windows headless message loop is process-global. Exercise
        // every injected-runtime scenario in one app lifetime so teardown
        // cannot race the next headless application instance.
        let _test_guard = HEADLESS_SHELL_TEST_LOCK
            .get_or_init(|| Mutex::new(()))
            .lock()
            .expect("headless shell test lock");
        let completed = std::rc::Rc::new(std::cell::RefCell::new(false));
        let completed_for_app = std::rc::Rc::clone(&completed);
        gpui::Application::headless().run(move |cx| {
            crate::ui::init(cx);
            ui_queue_full_pointer_admission_returns_and_retains_exact_record(cx);
            disconnected_admission_rebinds_transport_epochs_and_retries_same_identity(cx);
            uncertain_execution_retains_and_retries_same_command_identity(cx);
            failed_execution_retains_and_retries_same_command_identity(cx);
            newer_projection_epoch_is_adopted_after_the_drain_snapshot(cx);
            mixed_newer_projection_epoch_is_merged_not_dropped(cx);
            stale_action_outcomes_are_epoch_fenced(cx);
            stale_query_outcomes_are_discarded_without_transport_failure(cx);
            global_query_outcome_survives_navigation_and_projection_advance(cx);
            failed_queries_are_discarded_without_transport_failure(cx);
            uncertain_queries_are_discarded_without_transport_failure(cx);
            query_admission_failures_are_discarded_without_durable_retention(cx);
            successful_resync_projection_restores_runtime_connection(cx);
            startup_trace_reaches_first_projection_and_records_synchronize_failures(cx);
            startup_phase_line_replaces_liveness_and_gates_task_creation(cx);
            a_post_ready_resync_paints_the_phase_line_without_disabling_actions(cx);
            action_outcome_retention_pressure_keeps_exact_overflow_record(cx);
            native_shell_drop_retains_pending_overflow_and_deferred_as_uncertain(cx);
            *completed_for_app.borrow_mut() = true;
            cx.quit();
        });
        assert!(*completed.borrow(), "action durability scenarios completed");
    }

