    #[test]
    fn action_lane_cap_aggregates_channel_pending_and_shell_retained() {
        assert_eq!(
            super::action_lane_total(MAX_ACTION_LANE_RECORDS - 2, 1, 1),
            MAX_ACTION_LANE_RECORDS
        );
        assert!(
            super::action_lane_total(MAX_ACTION_LANE_RECORDS - 1, 1, 1) > MAX_ACTION_LANE_RECORDS,
            "the admission cap must see every action lane, not only shell retries"
        );
    }

    #[test]
    fn action_lane_reservation_survives_receive_until_ui_consume() {
        // Deterministic barrier: enqueue reservation stays outstanding while the
        // worker has "received" (no early release) and only drops on consume.
        let channel_depth = AtomicUsize::new(0);
        channel_depth.fetch_add(1, Ordering::AcqRel); // enqueue try_send success
        assert_eq!(
            super::action_lane_total(channel_depth.load(Ordering::Acquire), 0, 0),
            1
        );
        // Receive must NOT release — in-flight still occupies the lane.
        assert_eq!(channel_depth.load(Ordering::Acquire), 1);
        // Concurrent UI preflight must still see the outstanding reservation.
        assert!(super::action_lane_total(channel_depth.load(Ordering::Acquire), 0, 0) >= 1);
        // Publish keeps the same reservation (outcomes are not double-counted).
        assert_eq!(
            super::action_lane_total(channel_depth.load(Ordering::Acquire), 0, 0),
            1
        );
        super::release_action_lane_reservation(&channel_depth); // UI consume
        assert_eq!(channel_depth.load(Ordering::Acquire), 0);
    }

    #[test]
    fn action_lane_reservation_owner_isolation_keeps_cap_per_host() {
        let local = AtomicUsize::new(MAX_ACTION_LANE_RECORDS);
        let remote = AtomicUsize::new(0);
        assert!(
            super::action_lane_total(local.load(Ordering::Acquire), 0, 0)
                >= MAX_ACTION_LANE_RECORDS
        );
        assert_eq!(
            super::action_lane_total(remote.load(Ordering::Acquire), 0, 0),
            0,
            "remote owner must admit independently of a saturated local lane"
        );
    }

