    /// The same bound-terminal task, plus `shells` Active plain-shell Terminal
    /// resources registered at the agent's own runtime generation -- which is
    /// exactly the shape that makes "the one Active Terminal resource on this
    /// task" ambiguous. Returns the provider resource id and the shell ids.
    fn terminal_bound_client_model_with_shells_and_lifecycle(
        attention: crate::domain::task::TaskAttention,
        provider_kind: crate::providers::ProviderKind,
        provider_session_id: Option<&str>,
        action_epoch: u64,
        lifecycle: crate::domain::task::TaskLifecycle,
        shells: usize,
    ) -> (
        crate::client::ClientModel,
        TaskId,
        crate::domain::id::ResourceId,
        Vec<crate::domain::id::ResourceId>,
    ) {
        use crate::client::ClientModelBuilder;
        use crate::domain::{
            agent::{AgentRole, AgentSessionFacts, AgentSessionLifecycle},
            id::{AgentSessionId, EnvironmentId, ProjectId, ResourceId, SnapshotId},
            resource::{OwnerKind, ResourceFacts, ResourceKind, ResourceLifecycle, ResourceRecipe},
            snapshot::{SnapshotItem, SnapshotPage, SnapshotSection, TaskSnapshotItem},
            task::{
                ReviewReadiness, TaskActivity, TaskAssignment, TaskConnectivity, TaskFacts,
                TaskLifecycle, WorkspaceRef,
            },
        };

        let uuid = |tail: u8| {
            [
                0x01, 0x8f, 0x60, 0xb0, 0x9c, 0x1a, 0x70, 0x01, 0x80, 0x00, 0x00, 0x00, 0x00, 0x00,
                0x00, tail,
            ]
        };
        let task_id = TaskId::from_bytes(uuid(0xa1)).expect("task");
        let agent_id = AgentSessionId::from_bytes(uuid(0xa2)).expect("agent");
        let resource_id = ResourceId::from_bytes(uuid(0xa3)).expect("resource");
        let snap = SnapshotId::from_bytes(uuid(0x10)).expect("snapshot");
        let page = |section, items| SnapshotPage {
            snapshot_id: snap,
            through_sequence: 1,
            section,
            after_item: None,
            items,
            encoded_bytes: 1,
            next_cursor: None,
        };
        let mut builder = ClientModelBuilder::new();
        builder
            .ingest_page(page(
                SnapshotSection::Tasks,
                vec![SnapshotItem::Task(TaskSnapshotItem {
                    task: TaskFacts {
                        id: task_id,
                        environment_id: EnvironmentId::from_bytes(uuid(0x01)).expect("env"),
                        title: "Bound terminal task".into(),
                        description: None,
                        project_id: ProjectId::from_bytes(uuid(0x02)).expect("project"),
                        workspace: WorkspaceRef::Main,
                        assignment: TaskAssignment::LocalOwner,
                        lifecycle,
                        action_epoch,
                        revision: 4,
                        created_at_ms: 1,
                    },
                    connectivity: TaskConnectivity::Connected,
                    attention,
                    activity: TaskActivity::Idle,
                    review_readiness: ReviewReadiness::NotReady,
                    primary_agent_id: Some(agent_id),
                })],
            ))
            .expect("tasks");
        builder
            .ingest_page(page(
                SnapshotSection::AgentSessions,
                vec![SnapshotItem::AgentSession(AgentSessionFacts {
                    id: agent_id,
                    task_id,
                    role: AgentRole::Primary,
                    provider_kind,
                    provider_session_id: provider_session_id.map(|value| {
                        crate::domain::ProviderSessionId::new(value)
                            .expect("provider conversation identity")
                    }),
                    lifecycle: AgentSessionLifecycle::Open,
                    runtime_generation: 1,
                    revision: 0,
                })],
            ))
            .expect("agents");
        builder
            .ingest_page(page(SnapshotSection::Artifacts, Vec::new()))
            .expect("artifacts");
        let mut resources = vec![SnapshotItem::Resource(ResourceFacts {
            id: resource_id,
            task_id: Some(task_id),
            owner_kind: OwnerKind::Task,
            resource_kind: ResourceKind::Terminal,
            recipe: ResourceRecipe::terminal(40, 8),
            lifecycle: ResourceLifecycle::Active,
            runtime_generation: 1,
            updated_at_ms: 1,
        })];
        let mut shell_ids = Vec::new();
        for index in 0..shells {
            // One shell sorts BEFORE the provider resource (0xa3) and one
            // after, so a search that walks the resource map in key order --
            // the shape this fixture exists to catch -- lands on a shell
            // whichever end it starts from.
            let tail = if index % 2 == 0 { 0x90 } else { 0xb0 } + (index as u8) / 2;
            let shell_id = ResourceId::from_bytes(uuid(tail)).expect("shell resource");
            shell_ids.push(shell_id);
            resources.push(SnapshotItem::Resource(ResourceFacts {
                id: shell_id,
                task_id: Some(task_id),
                owner_kind: OwnerKind::Task,
                resource_kind: ResourceKind::Terminal,
                recipe: ResourceRecipe::Terminal {
                    cols: 40,
                    rows: 8,
                    launch: Some(crate::domain::resource::TerminalLaunch {
                        cwd: std::path::PathBuf::from("C:/workspace"),
                        program: std::path::PathBuf::from("pwsh"),
                        args: Vec::new(),
                    }),
                    title: None,
                },
                lifecycle: ResourceLifecycle::Active,
                // Deliberately the agent's own generation: a task's shells are
                // registered at the same generation as its provider, which is
                // why a generation-only search finds them.
                runtime_generation: 1,
                updated_at_ms: 1,
            }));
        }
        builder
            .ingest_page(page(SnapshotSection::Resources, resources))
            .expect("resources");
        builder
            .ingest_page(page(SnapshotSection::Operations, Vec::new()))
            .expect("operations");
        (
            builder.finish().expect("client model"),
            task_id,
            resource_id,
            shell_ids,
        )
    }

    fn unstarted_task_client_model_for(
        task_id: TaskId,
        project_id: ProjectId,
        provider_kind: ProviderKind,
    ) -> crate::client::ClientModel {
        use crate::client::ClientModelBuilder;
        use crate::domain::{
            agent::{AgentRole, AgentSessionFacts, AgentSessionLifecycle},
            id::{AgentSessionId, EnvironmentId, ResourceId, SnapshotId},
            resource::{OwnerKind, ResourceFacts, ResourceKind, ResourceLifecycle, ResourceRecipe},
            snapshot::{SnapshotItem, SnapshotPage, SnapshotSection, TaskSnapshotItem},
            task::{
                ReviewReadiness, TaskActivity, TaskAssignment, TaskConnectivity, TaskFacts,
                TaskLifecycle, WorkspaceRef,
            },
        };

        let agent_id = AgentSessionId::new();
        let resource_id = ResourceId::new();
        let snapshot_id = SnapshotId::new();
        let page = |section, items| SnapshotPage {
            snapshot_id,
            through_sequence: 1,
            section,
            after_item: None,
            items,
            encoded_bytes: 1,
            next_cursor: None,
        };
        let mut builder = ClientModelBuilder::new();
        builder
            .ingest_page(page(
                SnapshotSection::Tasks,
                vec![SnapshotItem::Task(TaskSnapshotItem {
                    task: TaskFacts {
                        id: task_id,
                        environment_id: EnvironmentId::new(),
                        title: "New Codex task".into(),
                        description: None,
                        project_id,
                        workspace: WorkspaceRef::Main,
                        assignment: TaskAssignment::LocalOwner,
                        lifecycle: TaskLifecycle::Open,
                        action_epoch: 0,
                        revision: 4,
                        created_at_ms: 1,
                    },
                    connectivity: TaskConnectivity::Connected,
                    attention: crate::domain::task::TaskAttention::None,
                    activity: TaskActivity::Idle,
                    review_readiness: ReviewReadiness::NotReady,
                    primary_agent_id: Some(agent_id),
                })],
            ))
            .expect("tasks");
        builder
            .ingest_page(page(
                SnapshotSection::AgentSessions,
                vec![SnapshotItem::AgentSession(AgentSessionFacts {
                    id: agent_id,
                    task_id,
                    role: AgentRole::Primary,
                    provider_kind,
                    provider_session_id: None,
                    lifecycle: AgentSessionLifecycle::Open,
                    runtime_generation: 1,
                    revision: 0,
                })],
            ))
            .expect("agents");
        builder
            .ingest_page(page(SnapshotSection::Artifacts, Vec::new()))
            .expect("artifacts");
        builder
            .ingest_page(page(
                SnapshotSection::Resources,
                vec![SnapshotItem::Resource(ResourceFacts {
                    id: resource_id,
                    task_id: Some(task_id),
                    owner_kind: OwnerKind::Task,
                    resource_kind: ResourceKind::Terminal,
                    recipe: ResourceRecipe::terminal(120, 40),
                    lifecycle: ResourceLifecycle::Active,
                    runtime_generation: 1,
                    updated_at_ms: 1,
                })],
            ))
            .expect("resources");
        builder
            .ingest_page(page(SnapshotSection::Operations, Vec::new()))
            .expect("operations");
        builder.finish().expect("client model")
    }

    fn two_task_terminal_bound_client_model() -> (crate::client::ClientModel, TaskId, TaskId) {
        use crate::client::ClientModelBuilder;
        use crate::domain::{
            agent::{AgentRole, AgentSessionFacts, AgentSessionLifecycle},
            id::{AgentSessionId, EnvironmentId, ProjectId, ResourceId, SnapshotId},
            resource::{OwnerKind, ResourceFacts, ResourceKind, ResourceLifecycle, ResourceRecipe},
            snapshot::{SnapshotItem, SnapshotPage, SnapshotSection, TaskSnapshotItem},
            task::{
                ReviewReadiness, TaskActivity, TaskAssignment, TaskConnectivity, TaskFacts,
                TaskLifecycle, WorkspaceRef,
            },
        };

        let uuid = |tail: u8| {
            [
                0x01, 0x8f, 0x60, 0xb0, 0x9c, 0x1a, 0x70, 0x01, 0x80, 0x00, 0x00, 0x00, 0x00, 0x00,
                0x00, tail,
            ]
        };
        let focused_task = TaskId::from_bytes(uuid(0xb1)).expect("focused");
        let background_task = TaskId::from_bytes(uuid(0xb2)).expect("background");
        let focused_agent = AgentSessionId::from_bytes(uuid(0xb3)).expect("focused agent");
        let background_agent = AgentSessionId::from_bytes(uuid(0xb4)).expect("background agent");
        let snap = SnapshotId::from_bytes(uuid(0x10)).expect("snapshot");
        let page = |section, items| SnapshotPage {
            snapshot_id: snap,
            through_sequence: 1,
            section,
            after_item: None,
            items,
            encoded_bytes: 1,
            next_cursor: None,
        };
        let mut builder = ClientModelBuilder::new();
        let task_item = |task_id, agent_id, title: &str| {
            SnapshotItem::Task(TaskSnapshotItem {
                task: TaskFacts {
                    id: task_id,
                    environment_id: EnvironmentId::from_bytes(uuid(0x01)).expect("env"),
                    title: title.into(),
                    description: None,
                    project_id: ProjectId::from_bytes(uuid(0x02)).expect("project"),
                    workspace: WorkspaceRef::Main,
                    assignment: TaskAssignment::LocalOwner,
                    lifecycle: TaskLifecycle::Open,
                    action_epoch: 3,
                    revision: 4,
                    created_at_ms: 1,
                },
                connectivity: TaskConnectivity::Connected,
                attention: crate::domain::task::TaskAttention::None,
                activity: TaskActivity::Idle,
                review_readiness: ReviewReadiness::NotReady,
                primary_agent_id: Some(agent_id),
            })
        };
        builder
            .ingest_page(page(
                SnapshotSection::Tasks,
                vec![
                    task_item(focused_task, focused_agent, "focused"),
                    task_item(background_task, background_agent, "background"),
                ],
            ))
            .expect("tasks");
        let mut agents = Vec::new();
        let mut resources = Vec::new();
        for (task_id, agent_id, resource_tail) in [
            (focused_task, focused_agent, 0xb6),
            (background_task, background_agent, 0xb7),
        ] {
            agents.push(SnapshotItem::AgentSession(AgentSessionFacts {
                id: agent_id,
                task_id,
                role: AgentRole::Primary,
                provider_kind: crate::providers::ProviderKind::ClaudeCode,
                provider_session_id: Some(
                    crate::domain::ProviderSessionId::new("provider-ready").expect("provider id"),
                ),
                lifecycle: AgentSessionLifecycle::Open,
                runtime_generation: 1,
                revision: 0,
            }));
            resources.push(SnapshotItem::Resource(ResourceFacts {
                id: ResourceId::from_bytes(uuid(resource_tail)).expect("resource"),
                task_id: Some(task_id),
                owner_kind: OwnerKind::Task,
                resource_kind: ResourceKind::Terminal,
                lifecycle: ResourceLifecycle::Active,
                recipe: ResourceRecipe::terminal(80, 24),
                runtime_generation: 1,
                updated_at_ms: 1,
            }));
        }
        builder
            .ingest_page(page(SnapshotSection::AgentSessions, agents))
            .expect("agents");
        builder
            .ingest_page(page(SnapshotSection::Resources, resources))
            .expect("resources");
        builder
            .ingest_page(page(SnapshotSection::Artifacts, Vec::new()))
            .expect("artifacts");
        builder
            .ingest_page(page(SnapshotSection::Operations, Vec::new()))
            .expect("operations");
        (
            builder.finish().expect("client model"),
            focused_task,
            background_task,
        )
    }

    fn selected_task_composer_waits_for_durable_provider_identity(cx: &mut gpui::App) {
        let (runtime, _shared) = TestRuntime::new(true, NativeHostActionResult::Queued);
        let (pending_model, task_id) = terminal_bound_client_model_with_provider(
            crate::domain::task::TaskAttention::None,
            None,
        );
        let (ready_model, ready_task_id) = terminal_bound_client_model();
        assert_eq!(task_id, ready_task_id);

        with_test_shell_in_app(cx, runtime, |shell| {
            shell
                .apply_client_model(Arc::new(pending_model))
                .expect("apply pending provider model");
            let list = crate::ui::task_cockpit::TaskList::from_client_model_virtual(
                shell
                    .client_model_snapshot()
                    .as_ref()
                    .expect("pending model"),
            )
            .expect("task list");
            let _ = shell
                .local_slot_mut()
                .interaction
                .navigation_mouse_down(task_id, &list);
            shell.sync_cockpit_follow();
            shell
                .replace_composer_platform_text(None, "keep this draft")
                .expect("edit pending composer");

            let pending = shell
                .composer
                .as_ref()
                .expect("composer remains visible while provider connects")
                .availability(ComposerControl::SendNow)
                .expect("send availability");
            assert!(
                pending.is_available(),
                "an unstarted draft must allow first Send so the provider can be launched"
            );
            assert_eq!(pending.reason(), None);

            shell
                .apply_client_model(Arc::new(ready_model))
                .expect("apply durable provider identity");
            let composer = shell.composer.as_ref().expect("ready composer");
            assert_eq!(composer.draft_text(), "keep this draft");
            assert!(composer
                .availability(ComposerControl::SendNow)
                .expect("ready send availability")
                .is_available());
        });
    }

