    fn center_task_canvas_switches_conversation_and_terminal(cx: &mut gpui::App) {
        use crate::ui::actions::{KeyboardShortcut, ShortcutKey};
        use crate::ui::task_cockpit::dock::DockTool as CockpitDockTool;

        let (runtime, _shared) = TestRuntime::new(true, NativeHostActionResult::Queued);
        let (model, task_id) = terminal_bound_client_model();
        let project_id = model.task(task_id).expect("task").task.project_id;
        with_test_shell_in_app(cx, runtime, |shell| {
            shell.install_project_for_test("DevManager", project_id);
            shell
                .apply_client_model(Arc::new(model))
                .expect("apply model");
            assert_eq!(
                shell
                    .task_search_candidates()
                    .into_iter()
                    .find(|candidate| candidate.task_id() == task_id)
                    .expect("task search candidate")
                    .project_label,
                "DevManager",
                "task rows must resolve the configured project name"
            );
            shell.install_idle_conversation_photo_for_test();
            let list = crate::ui::task_cockpit::TaskList::from_client_model_virtual(
                shell.client_model_snapshot().as_ref().unwrap(),
            )
            .expect("task list");
            let _ = shell
                .local_slot_mut()
                .interaction
                .navigation_mouse_down(task_id, &list);
            shell.sync_cockpit_follow();
            assert!(
                shell.splash_image.is_none(),
                "leaving the idle canvas must retire its photo so returning fetches a new one"
            );

            assert_eq!(
                shell.main_conversation_canvas(),
                MainConversationCanvas::TaskConversation
            );
            assert!(
                shell.center_canvas_switch_visible_for_test(),
                "center top Conversation/Terminal switch must be visible"
            );
            assert!(
                !shell.bottom_terminal_strip_present_for_test(),
                "bottom terminal strip must be removed"
            );

            assert!(shell.layout.dock_collapsed);
            shell.dispatch_named_accessibility_action("native-shell-context-dock-toggle");
            assert!(
                shell.layout.dock_collapsed,
                "the retired right dock must not reopen; its tools are panel views"
            );
            for (element_id, expected_tool) in [
                ("native-dock-tab-changes", CockpitDockTool::Changes),
                ("native-dock-tab-files", CockpitDockTool::Files),
                ("native-dock-tab-browser", CockpitDockTool::Browser),
                ("native-dock-tab-services", CockpitDockTool::Services),
                ("native-dock-tab-artifacts", CockpitDockTool::Artifacts),
                ("native-dock-tab-review", CockpitDockTool::Review),
            ] {
                shell.dispatch_named_accessibility_action(element_id);
                assert_eq!(
                    shell.cockpit().active_tool(),
                    expected_tool,
                    "accessible dock tab {element_id} must use the production dock-selection path"
                );
            }
            shell.dispatch_dock_tool(crate::ui::actions::DockTool::Browser);
            assert_eq!(shell.cockpit().active_tool(), CockpitDockTool::Browser);

            assert!(matches!(
                shell.project_actions.mode,
                ProjectActionMenuMode::Closed
            ));
            shell.dispatch_named_accessibility_action("native-shell-tools-affordance");
            assert!(
                !matches!(shell.project_actions.mode, ProjectActionMenuMode::Closed),
                "accessible Add action must open the project-action workflow"
            );
            shell.project_actions.close();

            assert!(!shell.pending_composer_image_prompt);
            shell.dispatch_named_accessibility_action("native-task-composer-attach");
            assert!(
                shell.pending_composer_image_prompt,
                "accessible Attach must queue the production image picker"
            );

            // A selection through the production owner route owns a pane; this
            // scenario reaches the canvas through navigation_mouse_down, which
            // does not, so seed the tree the select path would have built.
            let owner = shell.local_task_key(task_id);
            shell.layout.task_workspace =
                Some(crate::ui::task_workspace::Workspace::single(owner.clone()));

            shell.dispatch_named_accessibility_action("native-task-center-terminal");
            assert_eq!(
                shell.main_conversation_canvas(),
                MainConversationCanvas::TaskTerminal
            );
            assert_eq!(
                shell.pane_view(&owner),
                PaneView::Terminal,
                "going raw names Terminal on the owning pane"
            );
            assert_eq!(
                shell.cockpit().active_tool(),
                CockpitDockTool::Browser,
                "the center-mode switch must not replace the expanded right-panel surface"
            );
            assert!(
                shell.layout.dock_collapsed,
                "the retired right dock stays closed across every centre-canvas switch"
            );
            assert!(
                shell.local_slot_mut().composer_error.as_deref() != Some("provider terminal turn is not ready yet"),
                "switching to Terminal before a turn exists must not emit a red turn-not-ready error"
            );

            // Leaving the terminal only demotes a pane that is actually showing
            // it. A pane parked on another surface keeps that surface.
            shell.set_pane_view(&owner, PaneView::Files);
            shell.dispatch_named_accessibility_action("native-task-center-conversation");
            assert_eq!(
                shell.pane_view(&owner),
                PaneView::Files,
                "going semantic must not knock a pane off Files"
            );
            shell.dispatch_named_accessibility_action("native-task-center-terminal");
            assert_eq!(shell.pane_view(&owner), PaneView::Terminal);
            assert_eq!(
                shell.main_conversation_canvas(),
                MainConversationCanvas::TaskTerminal
            );

            shell.clear_selected_task();
            assert!(
                !shell.splash_fetch_attempted,
                "returning to the idle canvas must admit a fresh random-photo request"
            );
            assert!(matches!(
                shell.main_conversation_canvas(),
                MainConversationCanvas::IdlePhoto { .. }
            ));
            let restored = shell.select_projected_task(task_id);
            assert!(restored.consumed);
            assert_eq!(
                shell.main_conversation_canvas(),
                MainConversationCanvas::TaskConversation,
                concat!(
                    "the pane is the only source for its view, and deselection ",
                    "dropped the tree, so a reselected task opens on Conversation ",
                    "rather than on the surviving ContextDock terminal memory"
                )
            );

            shell.dispatch_named_accessibility_action("native-task-center-conversation");
            assert_eq!(
                shell.main_conversation_canvas(),
                MainConversationCanvas::TaskConversation
            );
            assert_eq!(shell.cockpit().active_tool(), CockpitDockTool::Browser);
            assert!(shell.layout.dock_collapsed);
        });
    }

