    fn cockpit_refresh_only_queries_the_active_host_surface(cx: &mut gpui::App) {
        let (runtime, shared) = TestRuntime::new(true, NativeHostActionResult::Queued);
        let (model, task_id) = terminal_bound_client_model();
        with_test_shell_in_app(cx, runtime, |shell| {
            shell
                .apply_client_model(Arc::new(model))
                .expect("apply model");
            let list = crate::ui::task_cockpit::TaskList::from_client_model_virtual(
                shell.client_model_snapshot().as_ref().unwrap(),
            )
            .expect("task list");
            let _ = shell
                .local_slot_mut()
                .interaction
                .navigation_mouse_down(task_id, &list);
            shell.sync_cockpit_follow();

            let assert_queries =
                |shared: &Arc<Mutex<TestRuntimeState>>,
                 expected: &[crate::domain::TaskCockpitQuery]| {
                    let state = shared.lock().expect("runtime");
                    let actual = state
                        .accepted
                        .iter()
                        .filter_map(|record| match &record.command {
                            super::NativeHostCommand::TaskCockpitQuery { query, .. } => {
                                Some(query.clone())
                            }
                            _ => None,
                        })
                        .collect::<Vec<_>>();
                    assert_eq!(actual, expected);
                };

            let _ = shell.local_slot_mut().cockpit.handle_tool_action(
                crate::ui::task_cockpit::dock::DockTool::Files,
                crate::domain::RequestId::new(),
            );
            shared.lock().expect("runtime").accepted.clear();
            shell.refresh_selected_cockpit_surfaces();
            assert_queries(
                &shared,
                &[crate::domain::TaskCockpitQuery::FilesList {
                    relative_directory: None,
                    limit: 64,
                }],
            );

            let _ = shell.local_slot_mut().cockpit.handle_tool_action(
                crate::ui::task_cockpit::dock::DockTool::Changes,
                crate::domain::RequestId::new(),
            );
            shared.lock().expect("runtime").accepted.clear();
            shell.refresh_selected_cockpit_surfaces();
            assert_queries(
                &shared,
                &[
                    crate::domain::TaskCockpitQuery::WorkspaceStatus,
                    crate::domain::TaskCockpitQuery::GitRepositories,
                ],
            );

            shared.lock().expect("runtime").accepted.clear();
            shell.apply_keyboard_shell_effects(crate::ui::actions::KeyboardAction::SelectDock(
                crate::ui::actions::DockTool::Services,
            ));
            assert_queries(
                &shared,
                &[crate::domain::TaskCockpitQuery::ServiceSnapshots],
            );
            assert!(
                shared
                    .lock()
                    .expect("runtime")
                    .accepted
                    .iter()
                    .any(|record| matches!(
                        record.command,
                        super::NativeHostCommand::HostActionsQuery { .. }
                    )),
                "opening Services must refresh the catalog and the task-scoped snapshots"
            );
        });
    }

    fn terminal_bound_archived_client_model() -> (crate::client::ClientModel, TaskId) {
        use crate::client::ClientModelBuilder;
        use crate::domain::{
            agent::{AgentRole, AgentSessionFacts, AgentSessionLifecycle},
            id::{AgentSessionId, EnvironmentId, ProjectId, ResourceId, SnapshotId},
            resource::{OwnerKind, ResourceFacts, ResourceKind, ResourceLifecycle, ResourceRecipe},
            snapshot::{SnapshotItem, SnapshotPage, SnapshotSection, TaskSnapshotItem},
            task::{
                ReviewReadiness, TaskActivity, TaskAssignment, TaskConnectivity, TaskFacts,
                TaskLifecycle, WorkspaceRef,
            },
        };

        let uuid = |tail: u8| {
            [
                0x01, 0x8f, 0x60, 0xb0, 0x9c, 0x1a, 0x70, 0x01, 0x80, 0x00, 0x00, 0x00, 0x00, 0x00,
                0x00, tail,
            ]
        };
        let task_id = TaskId::from_bytes(uuid(0xa1)).expect("task");
        let agent_id = AgentSessionId::from_bytes(uuid(0xa2)).expect("agent");
        let resource_id = ResourceId::from_bytes(uuid(0xa3)).expect("resource");
        let snap = SnapshotId::from_bytes(uuid(0x10)).expect("snapshot");
        let page = |section, items| SnapshotPage {
            snapshot_id: snap,
            through_sequence: 1,
            section,
            after_item: None,
            items,
            encoded_bytes: 1,
            next_cursor: None,
        };
        let mut builder = ClientModelBuilder::new();
        builder
            .ingest_page(page(
                SnapshotSection::Tasks,
                vec![SnapshotItem::Task(TaskSnapshotItem {
                    task: TaskFacts {
                        id: task_id,
                        environment_id: EnvironmentId::from_bytes(uuid(0x01)).expect("env"),
                        title: "bound terminal task".into(),
                        description: None,
                        project_id: ProjectId::from_bytes(uuid(0x02)).expect("project"),
                        workspace: WorkspaceRef::Main,
                        assignment: TaskAssignment::LocalOwner,
                        lifecycle: TaskLifecycle::Archived,
                        action_epoch: 0,
                        revision: 5,
                        created_at_ms: 1,
                    },
                    connectivity: TaskConnectivity::Connected,
                    attention: crate::domain::task::TaskAttention::None,
                    activity: TaskActivity::Idle,
                    review_readiness: ReviewReadiness::NotReady,
                    primary_agent_id: Some(agent_id),
                })],
            ))
            .expect("tasks");
        builder
            .ingest_page(page(
                SnapshotSection::AgentSessions,
                vec![SnapshotItem::AgentSession(AgentSessionFacts {
                    id: agent_id,
                    task_id,
                    role: AgentRole::Primary,
                    provider_kind: crate::providers::ProviderKind::ClaudeCode,
                    provider_session_id: Some(
                        crate::domain::ProviderSessionId::new("provider-conversation-ready")
                            .expect("provider conversation identity"),
                    ),
                    lifecycle: AgentSessionLifecycle::Open,
                    runtime_generation: 1,
                    revision: 0,
                })],
            ))
            .expect("agents");
        builder
            .ingest_page(page(SnapshotSection::Artifacts, Vec::new()))
            .expect("artifacts");
        builder
            .ingest_page(page(
                SnapshotSection::Resources,
                vec![SnapshotItem::Resource(ResourceFacts {
                    id: resource_id,
                    task_id: Some(task_id),
                    owner_kind: OwnerKind::Task,
                    resource_kind: ResourceKind::Terminal,
                    recipe: ResourceRecipe::terminal(40, 8),
                    lifecycle: ResourceLifecycle::Active,
                    runtime_generation: 1,
                    updated_at_ms: 1,
                })],
            ))
            .expect("resources");
        builder
            .ingest_page(page(SnapshotSection::Operations, Vec::new()))
            .expect("operations");
        (builder.finish().expect("client model"), task_id)
    }

    fn delete_flow_active_to_archive_to_single_delete_scenarios(cx: &mut gpui::App) {
        let (runtime, shared) = TestRuntime::new(true, NativeHostActionResult::Queued);
        let (model, task_id) = terminal_bound_client_model();
        let (archived_model, archived_id) = terminal_bound_archived_client_model();
        assert_eq!(task_id, archived_id);

        with_test_shell_in_app(cx, runtime, |shell| {
            shell
                .apply_client_model(Arc::new(model))
                .expect("apply model");
            let list = crate::ui::task_cockpit::TaskList::from_client_model_virtual(
                shell.client_model_snapshot().as_ref().unwrap(),
            )
            .expect("task list");
            let _ = shell
                .local_slot_mut()
                .interaction
                .navigation_mouse_down(task_id, &list);
            shell.sync_cockpit_follow();

            shell.begin_task_delete(task_id);
            assert!(shell.delete_task.is_some());
            assert_eq!(
                shell.delete_task.as_ref().map(|draft| draft.stage.clone()),
                Some(super::DeleteTaskStage::Confirming)
            );
            shell.refresh_accessibility_tree();
            assert!(
                shell
                    .accessibility_tree()
                    .gpui_nodes()
                    .into_iter()
                    .any(|node| node.description.contains("selected task")),
                "delete confirm a11y must name the selected task"
            );

            shell.confirm_task_delete();
            let archive_command = {
                let draft = shell.delete_task.as_ref().expect("draft stays open");
                match draft.stage {
                    super::DeleteTaskStage::AwaitingArchive {
                        command_id,
                        archive_accepted,
                        ..
                    } => {
                        assert!(!archive_accepted);
                        command_id
                    }
                    other => panic!("expected awaiting archive, got {other:?}"),
                }
            };
            let accepted = shared.lock().expect("runtime").accepted.clone();
            assert_eq!(
                accepted
                    .iter()
                    .filter(|record| matches!(
                        record.command,
                        super::NativeHostCommand::TaskArchive { task_id: id, .. } if id == task_id
                    ))
                    .count(),
                1,
                "confirm queues exactly one archive"
            );

            // Double confirm while queued must not enqueue again.
            shell.confirm_task_delete();
            assert_eq!(
                shared
                    .lock()
                    .expect("runtime")
                    .accepted
                    .iter()
                    .filter(|record| matches!(
                        record.command,
                        super::NativeHostCommand::TaskArchive { task_id: id, .. } if id == task_id
                    ))
                    .count(),
                1
            );

            // Projection before receipt: still no delete.
            shell
                .apply_client_model(Arc::new(archived_model.clone()))
                .expect("apply archived");
            assert!(
                shared
                    .lock()
                    .expect("runtime")
                    .accepted
                    .iter()
                    .all(|record| {
                        !matches!(
                            record.command,
                            super::NativeHostCommand::TaskLifecycle {
                                command: crate::domain::command::Command::DeleteTask,
                                ..
                            }
                        )
                    }),
                "no delete without archive receipt"
            );

            let archive_record = accepted
                .iter()
                .find(|record| {
                    matches!(
                        record.command,
                        super::NativeHostCommand::TaskArchive { task_id: id, .. } if id == task_id
                    )
                })
                .cloned()
                .expect("archive record");
            shell.apply_epoch_fenced_action_outcome(NativeHostActionOutcome::Accepted {
                action: archive_record,
                receipt: crate::domain::command::CommandReceipt::Accepted {
                    command_id: archive_command,
                    operation_id: crate::domain::id::OperationId::new(),
                    task_revision: Some(5),
                    event_ids: Vec::new(),
                    prompt_mutation: None,
                },
            });
            let delete_count = shared
                .lock()
                .expect("runtime")
                .accepted
                .iter()
                .filter(|record| {
                    matches!(
                        record.command,
                        super::NativeHostCommand::TaskLifecycle {
                            task_id: id,
                            command: crate::domain::command::Command::DeleteTask,
                            ..
                        } if id == task_id
                    )
                })
                .count();
            assert_eq!(
                delete_count, 1,
                "receipt+archived projection queues one delete"
            );
            assert!(matches!(
                shell.delete_task.as_ref().map(|draft| &draft.stage),
                Some(super::DeleteTaskStage::AwaitingDelete { .. })
            ));

            // Closing submitted deletion progress must not restore a retry or
            // affect a replacement dialog when the exact late result arrives.
            let delete_record = shared
                .lock()
                .expect("runtime")
                .accepted
                .last()
                .unwrap()
                .clone();
            let delete_command = native_command_id(&delete_record.command).unwrap();
            shell.cancel_delete_task_flow();
            assert!(shell.delete_task.is_none());
            shell.apply_epoch_fenced_action_outcome(NativeHostActionOutcome::Accepted {
                action: delete_record,
                receipt: crate::domain::command::CommandReceipt::Accepted {
                    command_id: delete_command,
                    operation_id: crate::domain::id::OperationId::new(),
                    task_revision: Some(6),
                    event_ids: Vec::new(),
                    prompt_mutation: None,
                },
            });
            assert!(shell.delete_task.is_none());
            assert!(
                shell.retired_delete_flow_commands.iter().any(|retired| {
                    retired.command_id == delete_command && retired.terminal
                }),
                "retired delete tombstone must persist as terminal so duplicate late results cannot regain advance"
            );
            shell.begin_task_delete(task_id);
            shell.confirm_task_delete();
            let failed_delete = shared
                .lock()
                .expect("runtime")
                .accepted
                .last()
                .unwrap()
                .clone();
            shell.cancel_delete_task_flow();
            shell.begin_task_delete(task_id);
            shell.apply_epoch_fenced_action_outcome(NativeHostActionOutcome::Failed {
                action: failed_delete,
                error: "late closed deletion failure".into(),
            });
            assert_eq!(
                shell.delete_task.as_ref().unwrap().stage,
                super::DeleteTaskStage::Confirming
            );
            assert!(shell.delete_task.as_ref().unwrap().error.is_none());
            assert!(shell.local_slot_mut().pending_host_actions.is_empty());
        });
    }

    fn delete_flow_cancel_and_failure_scenarios(cx: &mut gpui::App) {
        let (runtime, shared) = TestRuntime::new(true, NativeHostActionResult::Queued);
        let (model, task_id) = terminal_bound_client_model();

        with_test_shell_in_app(cx, runtime, |shell| {
            shell
                .apply_client_model(Arc::new(model))
                .expect("apply model");
            let list = crate::ui::task_cockpit::TaskList::from_client_model_virtual(
                shell.client_model_snapshot().as_ref().unwrap(),
            )
            .expect("task list");
            let _ = shell
                .local_slot_mut()
                .interaction
                .navigation_mouse_down(task_id, &list);

            shell.begin_task_delete(task_id);
            shell.confirm_task_delete();
            let archive_record = shared
                .lock()
                .expect("runtime")
                .accepted
                .iter()
                .find(|record| {
                    matches!(
                        record.command,
                        super::NativeHostCommand::TaskArchive { task_id: id, .. } if id == task_id
                    )
                })
                .cloned()
                .expect("archive");
            let archive_command =
                native_command_id(&archive_record.command).expect("archive command id");

            shell.cancel_delete_task_flow();
            assert!(shell.delete_task.is_none());
            shell.apply_epoch_fenced_action_outcome(NativeHostActionOutcome::Accepted {
                action: archive_record.clone(),
                receipt: crate::domain::command::CommandReceipt::Accepted {
                    command_id: archive_command,
                    operation_id: crate::domain::id::OperationId::new(),
                    task_revision: Some(5),
                    event_ids: Vec::new(),
                    prompt_mutation: None,
                },
            });
            assert!(
                shared
                    .lock()
                    .expect("runtime")
                    .accepted
                    .iter()
                    .all(|record| {
                        !matches!(
                            record.command,
                            super::NativeHostCommand::TaskLifecycle {
                                command: crate::domain::command::Command::DeleteTask,
                                ..
                            }
                        )
                    }),
                "cancelled flow must never queue delete after late archive receipt"
            );
            assert!(shell.delete_task.is_none());

            // Escape/new-task/rename/new-delete disarm
            shell.begin_task_delete(task_id);
            shell.confirm_task_delete();
            shell.begin_new_task_for_project(
                shell
                    .local_slot()
                    .client_model
                    .as_ref()
                    .and_then(|model| model.tasks().get(&task_id))
                    .map(|snapshot| snapshot.task.project_id)
                    .expect("project"),
            );
            assert!(shell.delete_task.is_none());

            shell.begin_task_delete(task_id);
            shell.confirm_task_delete();
            shell.begin_task_rename(task_id);
            assert!(shell.delete_task.is_none());

            shell.begin_task_delete(task_id);
            let first_title = shell.delete_task.as_ref().map(|draft| draft.title.clone());
            shell.begin_task_delete(task_id);
            assert_eq!(
                shell.delete_task.as_ref().map(|draft| draft.title.clone()),
                first_title
            );
            assert!(matches!(
                shell.delete_task.as_ref().map(|draft| &draft.stage),
                Some(super::DeleteTaskStage::Confirming)
            ));

            // Archive failure retires deferred intent and keeps modal with error.
            shell.confirm_task_delete();
            let failing = shared
                .lock()
                .expect("runtime")
                .accepted
                .iter()
                .rev()
                .find(|record| {
                    matches!(
                        record.command,
                        super::NativeHostCommand::TaskArchive { task_id: id, .. } if id == task_id
                    )
                })
                .cloned()
                .expect("archive for failure");
            shell.apply_epoch_fenced_action_outcome(NativeHostActionOutcome::Failed {
                action: failing,
                error: "archive exploded".into(),
            });
            let draft = shell.delete_task.as_ref().expect("modal stays");
            assert!(draft
                .error
                .as_deref()
                .is_some_and(|error| error.contains("archive")));
            assert_eq!(draft.stage, super::DeleteTaskStage::Confirming);
            assert!(shell.local_slot_mut().pending_host_actions.is_empty());

            shared.lock().expect("runtime").admission = NativeHostActionResult::QueueFull;
            shell.confirm_task_delete();
            assert!(shell.delete_task.as_ref().unwrap().error.is_some());
            assert!(
                shell.local_slot_mut().pending_host_actions.is_empty(),
                "failed admission cannot retain a destructive retry"
            );
            assert!(shell.local_slot_mut().retained_action_overflow.is_none());
            assert!(shell.local_slot_mut().last_action_failure.is_none());
            shared.lock().expect("runtime").admission = NativeHostActionResult::Queued;

            let mut first_cancelled = None;
            for _ in 0..20 {
                shell.begin_task_delete(task_id);
                shell.confirm_task_delete();
                let record = shared
                    .lock()
                    .expect("runtime")
                    .accepted
                    .last()
                    .unwrap()
                    .clone();
                first_cancelled.get_or_insert(record);
                shell.cancel_delete_task_flow();
            }
            shell.begin_task_delete(task_id);
            shell.confirm_task_delete();
            let replacement_command = shell.delete_flow_command_id();
            shell.apply_epoch_fenced_action_outcome(NativeHostActionOutcome::Failed {
                action: first_cancelled.unwrap(),
                error: "late cancelled archive failure".into(),
            });
            assert_eq!(shell.delete_flow_command_id(), replacement_command);
            assert!(shell.delete_task.as_ref().unwrap().error.is_none());
            assert!(shell.local_slot_mut().pending_host_actions.is_empty());
            shell.cancel_delete_task_flow();
        });
    }

    fn delete_flow_receipt_before_projection_and_delete_success(cx: &mut gpui::App) {
        let (runtime, shared) = TestRuntime::new(true, NativeHostActionResult::Queued);
        let (model, task_id) = terminal_bound_client_model();
        let (archived_model, _) = terminal_bound_archived_client_model();

        with_test_shell_in_app(cx, runtime, |shell| {
            shell
                .apply_client_model(Arc::new(model))
                .expect("apply model");
            let list = crate::ui::task_cockpit::TaskList::from_client_model_virtual(
                shell.client_model_snapshot().as_ref().unwrap(),
            )
            .expect("task list");
            let _ = shell
                .local_slot_mut()
                .interaction
                .navigation_mouse_down(task_id, &list);
            shell.begin_task_delete(task_id);
            shell.confirm_task_delete();
            let archive_record = shared
                .lock()
                .expect("runtime")
                .accepted
                .last()
                .cloned()
                .expect("archive");
            let archive_command =
                native_command_id(&archive_record.command).expect("archive command");
            shell.apply_epoch_fenced_action_outcome(NativeHostActionOutcome::Accepted {
                action: archive_record,
                receipt: crate::domain::command::CommandReceipt::Accepted {
                    command_id: archive_command,
                    operation_id: crate::domain::id::OperationId::new(),
                    task_revision: Some(5),
                    event_ids: Vec::new(),
                    prompt_mutation: None,
                },
            });
            assert!(
                matches!(
                    shell.delete_task.as_ref().map(|draft| &draft.stage),
                    Some(super::DeleteTaskStage::AwaitingArchive {
                        archive_accepted: true,
                        ..
                    })
                ),
                "receipt alone does not delete without Archived projection"
            );
            assert!(shared
                .lock()
                .expect("runtime")
                .accepted
                .iter()
                .all(|record| {
                    !matches!(
                        record.command,
                        super::NativeHostCommand::TaskLifecycle {
                            command: crate::domain::command::Command::DeleteTask,
                            ..
                        }
                    )
                }));

            shell
                .apply_client_model(Arc::new(archived_model))
                .expect("archived projection");
            let delete_record = shared
                .lock()
                .expect("runtime")
                .accepted
                .iter()
                .find(|record| {
                    matches!(
                        record.command,
                        super::NativeHostCommand::TaskLifecycle {
                            command: crate::domain::command::Command::DeleteTask,
                            ..
                        }
                    )
                })
                .cloned()
                .expect("delete queued after projection");
            let delete_command = native_command_id(&delete_record.command).expect("delete id");
            shell.apply_epoch_fenced_action_outcome(NativeHostActionOutcome::Accepted {
                action: delete_record,
                receipt: crate::domain::command::CommandReceipt::Accepted {
                    command_id: delete_command,
                    operation_id: crate::domain::id::OperationId::new(),
                    task_revision: Some(6),
                    event_ids: Vec::new(),
                    prompt_mutation: None,
                },
            });
            assert!(shell.delete_task.is_none());
            assert_eq!(shell.local_slot_mut().interaction.selected_task(), None);

            for outcome_kind in 0..4 {
                shell.begin_task_delete(task_id);
                shell.confirm_task_delete();
                let record = shared
                    .lock()
                    .expect("runtime")
                    .accepted
                    .last()
                    .unwrap()
                    .clone();
                let command_id = native_command_id(&record.command).unwrap();
                let outcome = match outcome_kind {
                    0 => NativeHostActionOutcome::Failed {
                        action: record,
                        error: "delete failed".into(),
                    },
                    1 => NativeHostActionOutcome::Uncertain {
                        action: record,
                        error: "delete result is unknown".into(),
                    },
                    2 => NativeHostActionOutcome::Accepted {
                        action: record,
                        receipt: crate::domain::command::CommandReceipt::Rejected {
                            command_id,
                            code: crate::domain::command::RejectionCode::RevisionConflict,
                            current_revision: Some(5),
                            resolution: None,
                        },
                    },
                    _ => NativeHostActionOutcome::Accepted {
                        action: record,
                        receipt: crate::domain::command::CommandReceipt::Accepted {
                            command_id: CommandId::new(),
                            operation_id: crate::domain::id::OperationId::new(),
                            task_revision: Some(6),
                            event_ids: Vec::new(),
                            prompt_mutation: None,
                        },
                    },
                };
                shell.apply_epoch_fenced_action_outcome(outcome);
                let draft = shell.delete_task.as_ref().expect("failure stays visible");
                assert_eq!(draft.stage, super::DeleteTaskStage::Confirming);
                assert!(draft.error.is_some());
                assert!(shell.local_slot_mut().pending_host_actions.is_empty());
            }
        });
    }

    #[test]
    fn delete_task_stage_submitting_flags_cover_queued_phases() {
        assert!(!super::DeleteTaskStage::Confirming.is_submitting());
        assert!(super::DeleteTaskStage::AwaitingArchive {
            command_id: CommandId::new(),
            archive_accepted: false,
            connection_epoch: 1,
            runtime_generation: 1,
        }
        .is_submitting());
        assert!(super::DeleteTaskStage::AwaitingDelete {
            command_id: CommandId::new(),
            connection_epoch: 1,
            runtime_generation: 1,
        }
        .is_submitting());
    }

    fn bound_task_with_failed_launch_holds_conversation(cx: &mut gpui::App) {
        let (runtime, shared) = TestRuntime::new(true, NativeHostActionResult::Queued);
        let (model, task_id) =
            terminal_bound_client_model_with_attention(crate::domain::task::TaskAttention::Failed);
        let report = with_test_shell_in_app(cx, runtime, |shell| {
            shell.local_slot_mut().agent_connection =
                Some(agent_connection_snapshot(AgentPresence::SignedIn));
            shell.install_named_folder_for_test("command");
            shell
                .apply_client_model(Arc::new(model))
                .expect("apply model");
            let list = crate::ui::task_cockpit::TaskList::from_client_model_virtual(
                shell.client_model_snapshot().as_ref().unwrap(),
            )
            .expect("task list");
            let _ = shell
                .local_slot_mut()
                .interaction
                .navigation_mouse_down(task_id, &list);
            shell.sync_cockpit_follow();
            shell.refresh_accessibility_tree();
            let element_ids: Vec<String> = shell
                .accessibility_tree()
                .gpui_nodes()
                .into_iter()
                .map(|node| node.element_id)
                .filter(|id| !id.is_empty())
                .collect();
            let before = shared.lock().expect("runtime").accepted.len();
            let archive_failed = shell
                .dispatch_action_for_test(crate::ui::components::ActionRequest::TaskArchive {
                    task_id,
                })
                .is_some();
            let settle_failed = shell
                .dispatch_action_for_test(crate::ui::components::ActionRequest::TaskSettle {
                    task_id,
                })
                .is_some();
            assert!(
                !settle_failed,
                "task.settle must enqueue without a capture failure"
            );
            let accepted = shared.lock().expect("runtime").accepted.clone();
            let delete_opened = {
                shell.begin_task_delete(task_id);
                shell.delete_task.as_ref().map(|draft| draft.owner.task_id)
            };
            (
                shell
                    .local_slot()
                    .cockpit
                    .conversation_hold_message()
                    .unwrap_or("")
                    .to_string(),
                shell.composer.is_none(),
                shell.host_status_text(),
                element_ids,
                archive_failed,
                before,
                accepted,
                delete_opened,
            )
        });
        assert!(
            report.0.contains("didn't start"),
            "a bound task whose agent failed to launch must surface that on the task, got {}",
            report.0
        );
        assert!(
            !report.0.contains("missing field") && !report.0.contains("agent_session_id"),
            "launch failure must not leak a developer field name: {}",
            report.0
        );
        assert!(report.1, "composer must stay closed when launch failed");
        assert!(
            !report.2.contains("Can't connect"),
            "launch failure must not paint host transport failure: {}",
            report.2
        );
        assert!(
            report.3.iter().any(|id| id == "native-task-archive"),
            "a selected failed task must expose Archive: {:?}",
            report.3
        );
        assert!(
            report.3.iter().any(|id| id == "native-task-delete"),
            "a selected task must expose Delete beside Archive: {:?}",
            report.3
        );
        assert!(
            !report.3.iter().any(|id| id == "native-task-open"),
            "visible Open must be removed; Files stays on the dock/keyboard path: {:?}",
            report.3
        );
        assert!(
            report.3.iter().any(|id| id == "native-task-settle"),
            "an active selected task must expose Done: {:?}",
            report.3
        );
        assert!(
            !report.4,
            "task.archive must enqueue without a capture failure"
        );
        assert!(
            report.6.len() > report.5
                && report.6.iter().any(|record| {
                    matches!(
                        record.command,
                        super::NativeHostCommand::TaskArchive { task_id: id, .. } if id == task_id
                    )
                }),
            "Archive must dispatch TaskArchive for the selected task"
        );
        assert_eq!(
            report.7,
            Some(task_id),
            "Delete on an active selected task must open begin_task_delete confirmation"
        );
        assert!(
            report.6.iter().any(|record| {
                matches!(
                    record.command,
                    super::NativeHostCommand::TaskLifecycle {
                        task_id: id,
                        command: crate::domain::command::Command::SettleTask,
                        ..
                    } if id == task_id
                )
            }),
            "Done must dispatch the reversible SettleTask command"
        );
    }

    fn dock_shortcuts_and_open_task_details_bind_selection(cx: &mut gpui::App) {
        use crate::ui::actions::{KeyboardShortcut, ShortcutKey};
        use crate::ui::task_cockpit::dock::DockTool as CockpitDockTool;

        let (runtime, shared) = TestRuntime::new(true, NativeHostActionResult::Queued);
        let (model, task_id) = terminal_bound_client_model();
        with_test_shell_in_app(cx, runtime, |shell| {
            shell
                .apply_client_model(Arc::new(model))
                .expect("apply model");
            let list = crate::ui::task_cockpit::TaskList::from_client_model_virtual(
                shell.client_model_snapshot().as_ref().unwrap(),
            )
            .expect("task list");
            let _ = shell
                .local_slot_mut()
                .interaction
                .navigation_mouse_down(task_id, &list);
            shell.sync_cockpit_follow();

            shell.dispatch_dock_tool(crate::ui::actions::DockTool::Browser);
            assert_eq!(
                shell.last_keyboard_action(),
                Some(crate::ui::actions::KeyboardAction::SelectDock(
                    crate::ui::actions::DockTool::Browser
                ))
            );
            assert_eq!(shell.cockpit().selected_task(), Some(task_id));
            assert_eq!(shell.cockpit().active_tool(), CockpitDockTool::Browser);

            shell.dispatch_keyboard_for_test(KeyboardShortcut::ctrl(ShortcutKey::Backtick));
            assert_eq!(
                shell.last_keyboard_action(),
                Some(crate::ui::actions::KeyboardAction::OpenTerminal)
            );
            assert_eq!(
                shell.cockpit().active_tool(),
                CockpitDockTool::Browser,
                "the full-canvas terminal switch must not replace the right context tool"
            );
            assert_eq!(
                shell.main_conversation_canvas(),
                MainConversationCanvas::TaskTerminal
            );
            assert!(
                shell
                    .local_slot_mut()
                    .interaction
                    .keyboard_state()
                    .terminal_open
            );

            let before = shared.lock().expect("runtime").accepted.len();
            shell.dispatch_keyboard_for_test(KeyboardShortcut::ctrl(ShortcutKey::Character('m')));
            assert_eq!(
                shell.last_keyboard_action(),
                Some(crate::ui::actions::KeyboardAction::OpenTaskDetails)
            );
            assert!(
                shell
                    .local_slot_mut()
                    .interaction
                    .keyboard_state()
                    .task_details_open
            );
            let accepted = shared.lock().expect("runtime").accepted.clone();
            assert!(
                accepted.len() > before && accepted.iter().any(|record| {
                    matches!(
                        record.command,
                        super::NativeHostCommand::TaskShowQuery { task_id: id, .. } if id == task_id
                    )
                }),
                "OpenTaskDetails must dispatch TaskShowQuery for the selected task"
            );
        });
    }

