    #[test]
    fn disconnected_remote_resolve_uses_trusted_source_not_local_grant() {
        let host_public_id = [0x33u8; 16];
        let host = HostId::remote(host_public_id).expect("remote");
        let store_root = PathBuf::from("C:/tmp/native-reconnect-trust-root");
        let source = NativeReconnectSource::TrustedRemote {
            store_root: store_root.clone(),
            host_public_id,
        };
        let kind = resolve_fleet_transport_reconnect(&host, false, &source).expect("trusted");
        assert_eq!(
            kind,
            FleetTransportReconnect::Trusted {
                store_root,
                host_public_id,
            }
        );
        assert!(
            resolve_fleet_transport_reconnect(&host, true, &NativeReconnectSource::Local).is_err(),
            "remote host must never fall back to local reconnect grant"
        );
        let mismatched = NativeReconnectSource::TrustedRemote {
            store_root: PathBuf::from("C:/tmp/other"),
            host_public_id: [0x44u8; 16],
        };
        assert!(
            resolve_fleet_transport_reconnect(&host, false, &mismatched).is_err(),
            "exact public id mismatch must fail closed"
        );

        // Missing fleet slot: still builds the trusted factory (not reconnect_local).
        let fleet = Arc::new(HostFleet::new());
        let runtime = tokio::runtime::Builder::new_multi_thread()
            .worker_threads(1)
            .enable_all()
            .build()
            .expect("runtime");
        let cancellation = Arc::new(AtomicBool::new(false));
        let source = NativeReconnectSource::TrustedRemote {
            store_root: PathBuf::from("C:/tmp/native-reconnect-trust-root"),
            host_public_id,
        };
        let probe = TrustedReconnectFactoryProbe::new();
        let err = resync_or_reconnect_fleet_host(
            &fleet,
            &host,
            false,
            &source,
            &runtime,
            &cancellation,
            true,
            Some(&probe),
        )
        .expect_err("missing remote host");
        assert!(
            err.contains("reconnect_with_factory") || err.contains("HostNotFound"),
            "disconnected remote must enter factory reconnect, got {err}"
        );
        assert_eq!(
            probe.builds(),
            1,
            "trusted factory must be built exactly once for the reconnect attempt"
        );
        assert!(
            !err.contains("reconnect_local"),
            "remote reconnect must not use local grant path"
        );
    }

    #[test]
    fn healthy_connected_resync_does_not_build_trusted_factory() {
        assert!(!fleet_resync_needs_transport_reconnect(false, true));
        assert!(fleet_resync_needs_transport_reconnect(true, true));
        assert!(fleet_resync_needs_transport_reconnect(false, false));

        let workspace = tempfile::tempdir().expect("workspace");
        let profile = isolated_dev_profile(workspace.path()).expect("profile");
        let host = HostId::local_profile(profile.named_profile()).expect("host");
        let fleet = Arc::new(HostFleet::new());
        let client_id = ClientId::from_bytes([
            0x01, 0x8f, 0x60, 0xb0, 0x9c, 0x1a, 0x70, 0x01, 0x80, 0x00, 0x00, 0x00, 0x00, 0x00,
            0x00, 0xa1,
        ])
        .expect("client");
        let hello = crate::protocol::ServerHello {
            protocol_major: crate::protocol::PROTOCOL_MAJOR,
            protocol_minor: crate::protocol::PROTOCOL_MINOR,
            server_build: "devmanager-host/native-resync-test".into(),
            host_boot_id: uuid::Uuid::from_bytes([
                0x01, 0x8f, 0x60, 0xb0, 0x9c, 0x1a, 0x70, 0x01, 0x80, 0x00, 0x00, 0x00, 0x00, 0x00,
                0x00, 0xb0,
            ]),
            connection_id: uuid::Uuid::from_bytes([
                0x01, 0x8f, 0x60, 0xb0, 0x9c, 0x1a, 0x70, 0x01, 0x80, 0x00, 0x00, 0x00, 0x00, 0x00,
                0x00, 0xc0,
            ]),
            profile_fingerprint: ProfileFingerprint::hash_normalized(profile.named_profile()),
            granted: CapabilitySet::from_capabilities([
                Capability::PagedSnapshots,
                Capability::EventReplay,
                Capability::ProviderInput,
                Capability::OperationSettlement,
            ]),
            limits: FrameLimits::v1_default(),
            reconnect_grant: None,
        };
        let stub = ClientConnection::inert_stub_for_test(client_id, hello.clone());
        let client = HostClient::from_parts_for_test(
            HostClientConfig {
                named_profile: profile.named_profile().to_string(),
                client_build: "devmanager/native-resync-test".into(),
                client_id,
                requested: CapabilitySet::from_capabilities([
                    Capability::PagedSnapshots,
                    Capability::EventReplay,
                    Capability::ProviderInput,
                    Capability::OperationSettlement,
                ]),
                limits: FrameLimits::v1_default(),
            },
            hello,
            Some(stub),
            BTreeMap::new(),
        );
        fleet.install(host.clone(), client).expect("install");
        assert!(fleet.is_connected(&host).expect("connected"));
        let generation_before = fleet.generation(&host).expect("gen");
        let runtime = tokio::runtime::Builder::new_multi_thread()
            .worker_threads(1)
            .enable_all()
            .build()
            .expect("runtime");
        let cancellation = Arc::new(AtomicBool::new(false));
        let trusted = NativeReconnectSource::TrustedRemote {
            store_root: PathBuf::from("C:/tmp/should-not-open"),
            host_public_id: [0x55u8; 16],
        };
        let probe = TrustedReconnectFactoryProbe::new();
        let _ = resync_or_reconnect_fleet_host(
            &fleet,
            &host,
            true,
            &trusted,
            &runtime,
            &cancellation,
            false,
            Some(&probe),
        );
        assert_eq!(
            probe.builds(),
            0,
            "healthy NeedsResync must synchronize without building a trusted factory"
        );
        assert_eq!(
            fleet.generation(&host).expect("gen"),
            generation_before,
            "same-generation sync must not rotate generation"
        );
        let _ = runtime.block_on(fleet.remove(&host));
    }

    #[test]
    fn reconnect_backoff_is_bounded_reset_and_per_host_independent() {
        assert_eq!(reconnect_backoff_delay_after_failures(0), Duration::ZERO);
        assert_eq!(
            reconnect_backoff_delay_after_failures(1),
            REMOTE_RECONNECT_BACKOFF_MIN
        );
        assert_eq!(
            reconnect_backoff_delay_after_failures(20),
            REMOTE_RECONNECT_BACKOFF_MAX,
            "backoff must cap exactly at 5s"
        );
        let mut host_a = NativeHostReconnectBackoff::default();
        let mut host_b = NativeHostReconnectBackoff::default();
        let now = Instant::now();
        assert!(should_attempt_recovery(&host_a, now));
        record_recovery_attempt_result(&mut host_a, now, false);
        assert!(!should_attempt_recovery(&host_a, now));
        assert!(
            should_attempt_recovery(&host_b, now),
            "per-host backoff must stay independent"
        );
        record_recovery_attempt_result(&mut host_a, Instant::now(), true);
        assert_eq!(host_a.attempts, 0);
        assert!(should_attempt_recovery(&host_a, Instant::now()));
    }

    #[test]
    fn recovery_decision_requires_success_not_mere_connected() {
        let mut backoff = NativeHostReconnectBackoff::default();
        let now = Instant::now();
        record_recovery_attempt_result(&mut backoff, now, false);
        assert!(!should_attempt_recovery(&backoff, now));
        // Connected=true alone must not clear backoff — only validated success.
        assert!(!should_attempt_recovery(&backoff, now));
        record_recovery_attempt_result(&mut backoff, Instant::now(), true);
        assert!(should_attempt_recovery(&backoff, Instant::now()));
        // Same-gen sync failure also arms backoff.
        record_recovery_attempt_result(&mut backoff, Instant::now(), false);
        assert!(!should_attempt_recovery(&backoff, Instant::now()));
    }

    #[test]
    fn bootstrap_ineligible_skips_recovery_attempt_decision() {
        let mut backoff = NativeHostReconnectBackoff::default();
        assert!(should_attempt_recovery(&backoff, Instant::now()));
        record_recovery_attempt_result(&mut backoff, Instant::now(), false);
        assert!(
            !should_attempt_recovery(&backoff, Instant::now()),
            "failed bootstrap recovery must gate the next whole bootstrap/recover unit"
        );
        record_recovery_attempt_result(&mut backoff, Instant::now(), true);
        assert!(
            should_attempt_recovery(&backoff, Instant::now()),
            "validated success must re-arm eligibility without requiring connected=true"
        );
    }

    #[test]
    fn cancel_during_backoff_returns_promptly() {
        let mut backoff = NativeHostReconnectBackoff::default();
        record_recovery_attempt_result(&mut backoff, Instant::now(), false);
        assert!(backoff.attempts >= 1);
        let cancellation = Arc::new(AtomicBool::new(false));
        let cancel_flag = Arc::clone(&cancellation);
        let started = Instant::now();
        let waiter = std::thread::spawn(move || {
            wait_reconnect_backoff_interruptible(&backoff, &cancel_flag)
        });
        std::thread::sleep(Duration::from_millis(20));
        cancellation.store(true, Ordering::Release);
        assert!(
            !waiter.join().expect("waiter"),
            "cancellation must win before full backoff elapses"
        );
        assert!(
            started.elapsed() < REMOTE_RECONNECT_BACKOFF_MIN,
            "shutdown must not block on the full reconnect backoff"
        );
    }

