    #[test]
    fn needs_resync_failure_arms_backoff_like_handshake_failure() {
        // Pump applies should_attempt_recovery to every failed recovery, including
        // healthy same-generation NeedsResync — not only disconnected handshake.
        let mut backoff = NativeHostReconnectBackoff::default();
        assert!(should_attempt_recovery(&backoff, Instant::now()));
        // Simulate same-gen sync failure (force_transport_reconnect=false path).
        record_recovery_attempt_result(&mut backoff, Instant::now(), false);
        assert!(
            !should_attempt_recovery(&backoff, Instant::now()),
            "NeedsResync failure must block the next recovery attempt"
        );
        assert_eq!(backoff.attempts, 1);
        assert_eq!(
            reconnect_backoff_delay_after_failures(backoff.attempts),
            REMOTE_RECONNECT_BACKOFF_MIN
        );
    }

    #[test]
    fn cancel_observes_pending_resync_waiter_without_full_budget() {
        // Mirrors the select! used around fleet resync/reconnect waiters.
        let cancellation = Arc::new(AtomicBool::new(false));
        let cancel_flag = Arc::clone(&cancellation);
        let runtime = tokio::runtime::Builder::new_multi_thread()
            .worker_threads(1)
            .enable_all()
            .build()
            .expect("runtime");
        let started = Instant::now();
        let joined = std::thread::spawn(move || {
            runtime.block_on(async {
                tokio::select! {
                    biased;
                    _ = wait_for_cancellation(cancel_flag) => "cancelled",
                    _ = tokio::time::sleep(NATIVE_STARTUP_BUDGET) => "budget",
                }
            })
        });
        std::thread::sleep(Duration::from_millis(20));
        cancellation.store(true, Ordering::Release);
        assert_eq!(joined.join().expect("join"), "cancelled");
        assert!(
            started.elapsed() < Duration::from_millis(500),
            "pending resync waiter must observe cancel far under the absolute budget"
        );
    }

    #[test]
    fn cancel_during_pending_factory_reconnect_uses_fleet_seam() {
        // Behavioral cancel against a real HostFleet factory wait (inert local host),
        // not a live trusted remote. Proves the waiter fences without claiming live proof.
        let workspace = tempfile::tempdir().expect("workspace");
        let profile = isolated_dev_profile(workspace.path()).expect("profile");
        let host = HostId::local_profile(profile.named_profile()).expect("host");
        let fleet = Arc::new(HostFleet::new());
        let client_id = ClientId::from_bytes([
            0x01, 0x8f, 0x60, 0xb0, 0x9c, 0x1a, 0x70, 0x01, 0x80, 0x00, 0x00, 0x00, 0x00, 0x00,
            0x00, 0xa5,
        ])
        .expect("client");
        let hello = crate::protocol::ServerHello {
            protocol_major: crate::protocol::PROTOCOL_MAJOR,
            protocol_minor: crate::protocol::PROTOCOL_MINOR,
            server_build: "devmanager-host/native-factory-cancel".into(),
            host_boot_id: uuid::Uuid::from_bytes([
                0x01, 0x8f, 0x60, 0xb0, 0x9c, 0x1a, 0x70, 0x01, 0x80, 0x00, 0x00, 0x00, 0x00, 0x00,
                0x00, 0xb4,
            ]),
            connection_id: uuid::Uuid::from_bytes([
                0x01, 0x8f, 0x60, 0xb0, 0x9c, 0x1a, 0x70, 0x01, 0x80, 0x00, 0x00, 0x00, 0x00, 0x00,
                0x00, 0xc4,
            ]),
            profile_fingerprint: ProfileFingerprint::hash_normalized(profile.named_profile()),
            granted: CapabilitySet::from_capabilities([
                Capability::PagedSnapshots,
                Capability::EventReplay,
            ]),
            limits: FrameLimits::v1_default(),
            reconnect_grant: None,
        };
        let stub = ClientConnection::inert_stub_for_test(client_id, hello.clone());
        let client = HostClient::from_parts_for_test(
            HostClientConfig {
                named_profile: profile.named_profile().to_string(),
                client_build: "devmanager/native-factory-cancel".into(),
                client_id,
                requested: CapabilitySet::from_capabilities([
                    Capability::PagedSnapshots,
                    Capability::EventReplay,
                ]),
                limits: FrameLimits::v1_default(),
            },
            hello,
            Some(stub),
            BTreeMap::new(),
        );
        fleet.install(host.clone(), client).expect("install");
        let generation_before = fleet.generation(&host).expect("gen");
        let runtime = tokio::runtime::Builder::new_multi_thread()
            .worker_threads(1)
            .enable_all()
            .build()
            .expect("runtime");
        let (start_tx, start_rx) = std::sync::mpsc::sync_channel::<()>(1);
        let (release_tx, release_rx) = std::sync::mpsc::sync_channel::<()>(1);
        let fleet_rec = Arc::clone(&fleet);
        let host_rec = host.clone();
        let reconnect = std::thread::spawn(move || {
            runtime.block_on(async move {
                fleet_rec
                    .reconnect_with_factory(
                        &host_rec,
                        Box::new(move || {
                            Box::pin(async move {
                                let _ = start_tx.send(());
                                let _ = release_rx.recv();
                                Err(IpcError::Unavailable)
                            })
                        }),
                    )
                    .await
            })
        });
        start_rx.recv().expect("factory admitted");
        // Cancellation-owned waiter pattern used by resync_or_reconnect_fleet_host.
        let cancellation = Arc::new(AtomicBool::new(false));
        let cancel_flag = Arc::clone(&cancellation);
        let observe = std::thread::spawn(move || {
            let rt = tokio::runtime::Builder::new_current_thread()
                .enable_all()
                .build()
                .expect("rt");
            rt.block_on(async {
                tokio::select! {
                    biased;
                    _ = wait_for_cancellation(cancel_flag) => "cancelled",
                    _ = tokio::time::sleep(NATIVE_STARTUP_BUDGET) => "budget",
                }
            })
        });
        std::thread::sleep(Duration::from_millis(20));
        cancellation.store(true, Ordering::Release);
        assert_eq!(observe.join().expect("observe"), "cancelled");
        let _ = release_tx.send(());
        let result = reconnect.join().expect("reconnect join");
        assert!(
            matches!(result, Err(FleetError::Ipc(IpcError::Unavailable))),
            "factory failure must settle under HostFleet even after waiter cancel"
        );
        assert!(fleet.contains(&host));
        assert_ne!(
            fleet.generation(&host).expect("gen"),
            generation_before,
            "factory path still advances generation under fleet ownership"
        );
        let cleanup = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .expect("cleanup");
        let _ = cleanup.block_on(fleet.remove(&host));
    }

    #[test]
    fn snapshot_restart_replay_owner_matches_admission() {
        let workspace = tempfile::tempdir().expect("workspace");
        let profile = isolated_dev_profile(workspace.path()).expect("profile");
        let host = HostId::local_profile(profile.named_profile()).expect("host");
        let fleet = Arc::new(HostFleet::new());
        let client_id = ClientId::from_bytes([
            0x01, 0x8f, 0x60, 0xb0, 0x9c, 0x1a, 0x70, 0x01, 0x80, 0x00, 0x00, 0x00, 0x00, 0x00,
            0x00, 0xa3,
        ])
        .expect("client");
        let hello = crate::protocol::ServerHello {
            protocol_major: crate::protocol::PROTOCOL_MAJOR,
            protocol_minor: crate::protocol::PROTOCOL_MINOR,
            server_build: "devmanager-host/native-replay-test".into(),
            host_boot_id: uuid::Uuid::from_bytes([
                0x01, 0x8f, 0x60, 0xb0, 0x9c, 0x1a, 0x70, 0x01, 0x80, 0x00, 0x00, 0x00, 0x00, 0x00,
                0x00, 0xb2,
            ]),
            connection_id: uuid::Uuid::from_bytes([
                0x01, 0x8f, 0x60, 0xb0, 0x9c, 0x1a, 0x70, 0x01, 0x80, 0x00, 0x00, 0x00, 0x00, 0x00,
                0x00, 0xc2,
            ]),
            profile_fingerprint: ProfileFingerprint::hash_normalized(profile.named_profile()),
            granted: CapabilitySet::from_capabilities([
                Capability::PagedSnapshots,
                Capability::EventReplay,
            ]),
            limits: FrameLimits::v1_default(),
            reconnect_grant: None,
        };
        let stub = ClientConnection::inert_stub_for_test(client_id, hello.clone());
        let client = HostClient::from_parts_for_test(
            HostClientConfig {
                named_profile: profile.named_profile().to_string(),
                client_build: "devmanager/native-replay-test".into(),
                client_id,
                requested: CapabilitySet::from_capabilities([
                    Capability::PagedSnapshots,
                    Capability::EventReplay,
                ]),
                limits: FrameLimits::v1_default(),
            },
            hello,
            Some(stub),
            BTreeMap::new(),
        );
        fleet.install(host.clone(), client).expect("install");
        let admission = fleet.admit_host(&host).expect("admit");
        let replay = fleet.take_replay_events(&admission).expect("replay");
        assert!(owned_matches_admission(&replay, &admission));
        let owner = NativeProjectionOwner::from_owned(&replay);
        assert_eq!(owner.host, admission.host);
        assert_eq!(owner.generation, admission.generation);
        assert_eq!(owner.client_id, admission.client_id);
        let runtime = tokio::runtime::Builder::new_multi_thread()
            .worker_threads(1)
            .enable_all()
            .build()
            .expect("runtime");
        let _ = runtime.block_on(fleet.remove(&host));
    }

    #[test]
    fn queuefull_retained_admission_cannot_authorize_new_generation() {
        let host = HostId::local_profile("native_fleet_queuefull").expect("host");
        let client_id = ClientId::from_bytes([
            0x01, 0x8f, 0x60, 0xb0, 0x9c, 0x1a, 0x70, 0x01, 0x80, 0x00, 0x00, 0x00, 0x00, 0x00,
            0x00, 0x78,
        ])
        .expect("client");
        let retained = FleetAdmission {
            host: host.clone(),
            task_id: None,
            generation: 3,
            client_id,
        };
        let live_after_reconnect = FleetAdmission {
            host,
            task_id: None,
            generation: 4,
            client_id,
        };
        let owner = NativeProjectionOwner::from_admission(&retained);
        assert!(
            !owner.matches_admission(&live_after_reconnect),
            "QueueFull-retained owner token must not execute under a new fleet generation"
        );
        assert!(owner.matches_admission(&retained));
    }

    #[test]
    fn projection_wrapper_and_outcome_admission_must_agree() {
        let host = HostId::local_profile("native_fleet_owner_agree").expect("host");
        let client_a = ClientId::from_bytes([
            0x01, 0x8f, 0x60, 0xb0, 0x9c, 0x1a, 0x70, 0x01, 0x80, 0x00, 0x00, 0x00, 0x00, 0x00,
            0x00, 0x79,
        ])
        .expect("client a");
        let client_b = ClientId::from_bytes([
            0x01, 0x8f, 0x60, 0xb0, 0x9c, 0x1a, 0x70, 0x01, 0x80, 0x00, 0x00, 0x00, 0x00, 0x00,
            0x00, 0x7a,
        ])
        .expect("client b");
        let wrapper = NativeProjectionOwner {
            host: host.clone(),
            generation: 2,
            client_id: client_a,
        };
        let matching = FleetAdmission {
            host: host.clone(),
            task_id: None,
            generation: 2,
            client_id: client_a,
        };
        let foreign = FleetAdmission {
            host,
            task_id: None,
            generation: 2,
            client_id: client_b,
        };
        assert_eq!(
            wrapper,
            NativeProjectionOwner::from_admission(&matching),
            "overflow projection may omit owner but action admission must derive the same token"
        );
        assert_ne!(
            wrapper,
            NativeProjectionOwner::from_admission(&foreign),
            "wrapper/outcome owner disagreement must fail closed"
        );
    }

    #[test]
    fn stale_dirty_and_outcome_suppressed_without_live_owner() {
        let host = HostId::local_profile("native_fleet_stale_msg").expect("host");
        let client_id = ClientId::from_bytes([
            0x01, 0x8f, 0x60, 0xb0, 0x9c, 0x1a, 0x70, 0x01, 0x80, 0x00, 0x00, 0x00, 0x00, 0x00,
            0x00, 0x7b,
        ])
        .expect("client");
        let live = NativeProjectionOwner {
            host: host.clone(),
            generation: 5,
            client_id,
        };
        let stale_owner = NativeProjectionOwner {
            host: host.clone(),
            generation: 4,
            client_id,
        };
        let dirty = NativeHostProjection::kind(NativeHostProjectionKind::ConversationDirty {
            task_id: TaskId::new(),
            high_water: 9,
        })
        .with_owner(stale_owner.clone());
        assert!(
            !fleet_projection_message_accepted(true, Some(&live), &dirty),
            "stale ConversationDirty must not schedule under a new generation"
        );

        let mut interaction = NativeInteraction::new(None);
        let mut action = interaction
            .action(crate::ui::components::ActionRequest::HostStatus)
            .expect("action");
        action.fleet_admission = Some(FleetAdmission {
            host,
            task_id: None,
            generation: 4,
            client_id,
        });
        let outcome_projection = NativeHostProjection {
            kind: NativeHostProjectionKind::Error,
            client_model: None,
            task_preview: None,
            error: Some("retained under pressure".into()),
            epochs: None,
            action_outcome: Some(NativeHostActionOutcome::Failed {
                action,
                error: "retained under pressure".into(),
            }),
            owner: None,
            durable_events: None,
        };
        assert!(
            !fleet_projection_message_accepted(true, Some(&live), &outcome_projection),
            "overflow outcome with stale admission must not apply or auto-retry"
        );
        let local_error = NativeHostProjection {
            kind: NativeHostProjectionKind::Error,
            client_model: None,
            task_preview: None,
            error: Some("local".into()),
            epochs: None,
            action_outcome: None,
            owner: None,
            durable_events: None,
        };
        assert!(
            fleet_projection_message_accepted(true, Some(&live), &local_error),
            "owner-less local errors remain admissible"
        );
    }

    #[test]
    fn preview_attachment_does_not_enable_mutations() {
        assert!(!admits_host_actions(true, false));
        assert!(admits_host_actions(true, true));
    }

    #[test]
    fn idle_photo_fetch_admission_is_oneshot_without_network() {
        assert!(admit_idle_conversation_photo_fetch(
            false, false, false, false
        ));
        assert!(!admit_idle_conversation_photo_fetch(
            true, false, false, false
        ));
        assert!(!admit_idle_conversation_photo_fetch(
            false, true, false, false
        ));
        assert!(!admit_idle_conversation_photo_fetch(
            false, false, true, false
        ));
        assert!(!admit_idle_conversation_photo_fetch(
            false, false, false, true
        ));
        // After a failed attempt the session flag stays set: no second fetch.
        assert!(!admit_idle_conversation_photo_fetch(
            false, false, true, false
        ));
    }

    #[test]
    fn idle_photo_decode_rejects_oversized_and_accepts_tiny() {
        let mut tiny = image::RgbaImage::new(2, 2);
        for pixel in tiny.chunks_exact_mut(4) {
            pixel.copy_from_slice(&[0x10, 0x20, 0x30, 0xff]);
        }
        let mut tiny_bytes = Vec::new();
        image::DynamicImage::ImageRgba8(tiny)
            .write_to(
                &mut std::io::Cursor::new(&mut tiny_bytes),
                image::ImageFormat::Png,
            )
            .expect("encode tiny png");
        assert!(
            decode_idle_conversation_photo_bytes(&tiny_bytes).is_some(),
            "tiny png must decode"
        );
        assert!(!idle_photo_dimensions_allowed(0, 1));
        assert!(!idle_photo_dimensions_allowed(1, 0));
        assert!(!idle_photo_dimensions_allowed(4097, 1));
        assert!(!idle_photo_dimensions_allowed(1, 4097));
        assert!(!idle_photo_dimensions_allowed(4096, 4096));
        assert!(idle_photo_dimensions_allowed(2, 2));
        // PNM header carries oversized dimensions without allocating a bitmap.
        let oversized = b"P6\n5000 5000\n255\n";
        assert!(
            decode_idle_conversation_photo_bytes(oversized).is_none(),
            "oversized header must fail closed before bitmap allocation"
        );
    }

    #[test]
    fn invalid_host_projection_payloads_fail_closed_without_applying() {
        if rerun_headless_shell_test_in_child(
            "ui::native_shell::tests::invalid_host_projection_payloads_fail_closed_without_applying",
        ) {
            return;
        }
        use crate::client::{ClientModelBuilder, TaskInboxPreview};
        use crate::domain::id::{EnvironmentId, ProjectId, SnapshotId, TaskId};
        use crate::domain::snapshot::{
            SnapshotItem, SnapshotPage, SnapshotSection, TaskSnapshotItem,
        };
        use crate::domain::task::{
            ReviewReadiness, TaskActivity, TaskAssignment, TaskAttention, TaskConnectivity,
            TaskFacts, TaskLifecycle, WorkspaceRef,
        };
        use std::sync::Arc;

        let task = TaskId::from_bytes([
            0x01, 0x8f, 0x60, 0xb0, 0x9c, 0x1a, 0x70, 0x01, 0x80, 0x00, 0x00, 0x00, 0x00, 0x00,
            0x00, 0x61,
        ])
        .expect("task");
        let snap = SnapshotId::from_bytes([
            0x01, 0x8f, 0x60, 0xb0, 0x9c, 0x1a, 0x70, 0x01, 0x80, 0x00, 0x00, 0x00, 0x00, 0x00,
            0x00, 0x60,
        ])
        .expect("snap");
        let mut builder = ClientModelBuilder::new();
        builder
            .ingest_page(SnapshotPage {
                snapshot_id: snap,
                through_sequence: 3,
                section: SnapshotSection::Tasks,
                after_item: None,
                items: vec![SnapshotItem::Task(TaskSnapshotItem {
                    task: TaskFacts {
                        id: task,
                        environment_id: EnvironmentId::from_bytes([
                            0x01, 0x8f, 0x60, 0xb0, 0x9c, 0x1a, 0x70, 0x01, 0x80, 0x00, 0x00, 0x00,
                            0x00, 0x00, 0x00, 0x10,
                        ])
                        .expect("env"),
                        title: "Invalid payload".into(),
                        description: None,
                        project_id: ProjectId::from_bytes([
                            0x01, 0x8f, 0x60, 0xb0, 0x9c, 0x1a, 0x70, 0x01, 0x80, 0x00, 0x00, 0x00,
                            0x00, 0x00, 0x00, 0x11,
                        ])
                        .expect("project"),
                        workspace: WorkspaceRef::Main,
                        assignment: TaskAssignment::LocalOwner,
                        lifecycle: TaskLifecycle::Open,
                        action_epoch: 1,
                        revision: 1,
                        created_at_ms: 1,
                    },
                    connectivity: TaskConnectivity::Connected,
                    attention: TaskAttention::None,
                    activity: TaskActivity::Idle,
                    review_readiness: ReviewReadiness::NotReady,
                    primary_agent_id: None,
                })],
                encoded_bytes: 1,
                next_cursor: None,
            })
            .expect("tasks");
        let preview = Arc::new(builder.finish_tasks_preview().expect("preview"));
        let invalid_task_preview = NativeHostProjection {
            kind: NativeHostProjectionKind::TaskPreview,
            client_model: None,
            task_preview: None,
            error: None,
            epochs: None,
            action_outcome: None,
            owner: None,
            durable_events: None,
        };
        let invalid_snapshot = NativeHostProjection {
            kind: NativeHostProjectionKind::Snapshot,
            client_model: None,
            task_preview: Some(Arc::clone(&preview)),
            error: None,
            epochs: None,
            action_outcome: None,
            owner: None,
            durable_events: None,
        };
        assert!(validate_host_projection_payloads(&invalid_task_preview).is_err());
        assert!(validate_host_projection_payloads(&invalid_snapshot).is_err());
        assert!(
            validate_host_projection_payloads(&NativeHostProjection::task_preview(Arc::clone(
                &preview
            )))
            .is_ok()
        );

        let workspace = tempfile::tempdir().expect("workspace");
        let profile = isolated_dev_profile(workspace.path()).expect("profile");
        let (runtime, shared) = TestRuntime::new(true, NativeHostActionResult::Queued);
        shared
            .lock()
            .expect("state")
            .projections
            .push_back(invalid_task_preview);
        shared
            .lock()
            .expect("state")
            .projections
            .push_back(invalid_snapshot);
        let report_slot = std::rc::Rc::new(std::cell::RefCell::new(None));
        let report_slot_for_app = std::rc::Rc::clone(&report_slot);
        gpui::Application::headless().run(move |cx| {
            crate::ui::init(cx);
            let entity = cx.new(|cx| {
                NativeShell::new_with_host_runtime_port(
                    profile,
                    Box::new(runtime),
                    crate::ui::tokens::RuntimePreferencesSnapshot::default(),
                    cx,
                )
            });
            let report = entity.update(cx, |shell, _cx| {
                let kinds = shell.drain_host_projections(8);
                (
                    kinds,
                    shell.client_model_snapshot().is_some(),
                    shell.mutations_enabled(),
                    shell.task_list_ids().is_empty(),
                    matches!(shell.host_state(), NativeHostState::Error { .. }),
                )
            });
            *report_slot_for_app.borrow_mut() = Some(report);
            drop(entity);
            cx.quit();
        });
        let (kinds, has_model, mutations, empty_tasks, errored) = report_slot
            .borrow_mut()
            .take()
            .expect("invalid payload report");
        assert_eq!(
            kinds,
            vec![
                NativeHostProjectionKind::TaskPreview,
                NativeHostProjectionKind::Snapshot
            ]
        );
        assert!(!has_model);
        assert!(!mutations);
        assert!(empty_tasks, "invalid payloads must not apply preview rows");
        assert!(
            errored,
            "invalid payloads must surface a bounded host error"
        );
    }

