                let open_remote = HostTaskKey::new(remote_host.clone(), TaskId::new());
                let agent = AgentSessionId::new();
                let unopened_draft =
                    NativeShell::fleet_draft_key_for(unopened_local.clone(), agent);
                shell.composer_drafts.insert(
                    unopened_draft.clone(),
                    ComposerDraftProjection {
                        text: "keep-me".into(),
                        attachments: Vec::new(),
                        prompt: None,
                    },
                );
                // Only remote is open; local draft is intentionally unopened.
                shell.layout.task_workspace = Some(crate::ui::task_workspace::Workspace::single(
                    open_remote.clone(),
                ));
                shell.selected_task_key = Some(open_remote.clone());
                let (remote_runtime, _) = TestRuntime::new(true, NativeHostActionResult::Queued);
