    #[test]
    fn owner_qualified_remote_chat_send_settles_only_captured_owner() {
        if rerun_headless_shell_test_in_child(
            "ui::native_shell::tests::owner_qualified_remote_chat_send_settles_only_captured_owner",
        ) {
            return;
        }
        let remote_host = HostId::Remote([0x44; 16]);
        let (runtime, local_shared) = TestRuntime::new(true, NativeHostActionResult::Queued);
        let workspace = tempfile::tempdir().expect("workspace");
        let profile = isolated_dev_profile(workspace.path()).expect("profile");
        let report = std::rc::Rc::new(std::cell::RefCell::new(None));
        let report_slot = std::rc::Rc::clone(&report);
        gpui::Application::headless().run(move |cx| {
            crate::ui::init(cx);
            let entity = cx.new(|cx| {
                NativeShell::new_with_host_runtime_port(
                    profile,
                    Box::new(runtime),
                    crate::ui::tokens::RuntimePreferencesSnapshot::default(),
                    cx,
                )
            });
            let observed =
                entity.update(cx, |shell, _cx| {
                    shell.install_idle_conversation_photo_for_test();
                    // Same raw TaskId + AgentSessionId on both hosts.
                    let (model, shared_task) = terminal_bound_client_model();
                    let model = Arc::new(model);
                    let agent = model
                        .task(shared_task)
                        .and_then(|snapshot| snapshot.primary_agent_id)
                        .expect("shared agent");
                    shell
                        .apply_client_model(Arc::clone(&model))
                        .expect("local model");
                    let local = shell.local_host_id();
                    let local_key = HostTaskKey::new(local.clone(), shared_task);
                    let remote_key = HostTaskKey::new(remote_host.clone(), shared_task);

                    let (remote_runtime, remote_shared) =
                        TestRuntime::new(true, NativeHostActionResult::Queued);
                    let mut remote_slot = HostUiState::new_empty(
                        remote_host.clone(),
                        NativeHostState::Connected {
                            endpoint: "fleet://remote-chat".into(),
                        },
                    );
                    let epochs = remote_runtime.epochs();
                    remote_slot.host_runtime = Some(NativeHostRuntimeAttachment::Injected(
                        Box::new(remote_runtime),
                    ));
                    let _ = remote_slot.interaction.sync_host_epochs(epochs);
                    shell
                        .attach_host_ui_slot(remote_slot)
                        .expect("attach remote");
                    shell
                        .apply_client_model_for_host(&remote_host, Arc::clone(&model))
                        .expect("remote model");

                    shell
                        .select_fleet_task_key(remote_key.clone(), FleetSelectMode::Replace)
                        .expect("select remote A");
                    assert_eq!(shell.composer_owner_key(), Some(&remote_key));
                    let focus_a = shell
                        .host_slot(&remote_host)
                        .map(|slot| slot.interaction.current_focus_epoch())
                        .expect("remote focus");
                    shell
                        .composer
                        .as_mut()
                        .expect("remote composer")
                        .replace_draft("remote-A-send", focus_a)
                        .expect("type A draft");
                    let intent = {
                        let composer = shell.composer.as_mut().expect("composer");
                        composer
                            .focus_control(ComposerControl::SendNow, focus_a)
                            .expect("focus send");
                        composer
                            .activate(ComposerControl::SendNow, focus_a)
                            .expect("submit A send")
                    };
                    let command_id = intent.command_id;
                    shell.dispatch_composer_intent(intent);
                    assert!(
                        shell.pending_composer_submissions.contains_key(&command_id),
                        "SendNow must park A's pending submission"
                    );
                    let remote_send_count = remote_shared
                        .lock()
                        .expect("remote")
                        .accepted
                        .iter()
                        .filter(|record| native_command_id(&record.command) == Some(command_id))
                        .count();
                    let local_send_count = local_shared
                        .lock()
                        .expect("local")
                        .accepted
                        .iter()
                        .filter(|record| native_command_id(&record.command) == Some(command_id))
                        .count();
                    assert_eq!(remote_send_count, 1, "A runtime must receive the send");
                    assert_eq!(
                        local_send_count, 0,
                        "B/local runtime must never receive A's send"
                    );
                    let submitted = remote_shared
                        .lock()
                        .expect("remote")
                        .accepted
                        .iter()
                        .find(|record| native_command_id(&record.command) == Some(command_id))
                        .cloned()
                        .expect("A send record");

                    // Focus B and type a newer draft while A's receipt is in flight.
                    shell
                        .select_fleet_task_key(local_key.clone(), FleetSelectMode::Replace)
                        .expect("focus B");
                    let focus_b = shell.local_slot().interaction.current_focus_epoch();
                    shell
                        .composer
                        .as_mut()
                        .expect("local composer")
                        .replace_draft("local-B-newer", focus_b)
                        .expect("type B draft");
                    shell.cache_current_composer_draft();
                    let b_draft_key = NativeShell::fleet_draft_key_for(local_key.clone(), agent);
                    assert_eq!(
                        shell
                            .composer_drafts
                            .get(&b_draft_key)
                            .map(|d| d.text.as_str()),
                        Some("local-B-newer")
                    );
                    let focused_before = shell.selected_task_key.clone();

                    // Stale/mismatched owner receipt must not clear A's pending.
                    let mut foreign = submitted.clone();
                    foreign.fleet_admission = Some(FleetAdmission {
                        host: local.clone(),
                        task_id: Some(shared_task),
                        generation: 1,
                        client_id: ClientId::new(),
                    });
                    shell.apply_epoch_fenced_action_outcome_for_host(
                        &remote_host,
                        NativeHostActionOutcome::Accepted {
                            action: foreign,
                            receipt: crate::domain::command::CommandReceipt::Accepted {
                                command_id,
                                operation_id: crate::domain::id::OperationId::new(),
                                task_revision: None,
                                event_ids: Vec::new(),
                                prompt_mutation: None,
                            },
                        },
                    );
                    assert!(
                        shell.pending_composer_submissions.contains_key(&command_id),
                        "mismatched owner receipt must not clear A's pending"
                    );

                    // Receipt-before-projection path.
                    shell.apply_epoch_fenced_action_outcome_for_host(
                        &remote_host,
                        NativeHostActionOutcome::Accepted {
                            action: submitted.clone(),
                            receipt: crate::domain::command::CommandReceipt::Accepted {
                                command_id,
                                operation_id: crate::domain::id::OperationId::new(),
                                task_revision: None,
                                event_ids: Vec::new(),
                                prompt_mutation: None,
                            },
                        },
                    );
                    assert!(
                        !shell.pending_composer_submissions.contains_key(&command_id),
                        "matched A receipt must clear only A's pending"
                    );
                    assert_eq!(
                        shell
                            .composer_drafts
                            .get(&b_draft_key)
                            .map(|d| d.text.as_str()),
                        Some("local-B-newer"),
                        "B/newer draft must survive A's settlement"
                    );
                    assert_eq!(
                        shell.selected_task_key, focused_before,
                        "background settlement must not steal focus from B"
                    );

                    // Projection-before-receipt order: park another A send, push model
                    // projection first, then settle via drain outcome.
                    shell
                        .select_fleet_task_key(remote_key.clone(), FleetSelectMode::Replace)
                        .expect("reselect A");
                    let focus_a2 = shell
                        .host_slot(&remote_host)
                        .map(|slot| slot.interaction.current_focus_epoch())
                        .expect("remote focus");
                    shell
                        .composer
                        .as_mut()
                        .expect("remote composer")
                        .replace_draft("remote-A-second", focus_a2)
                        .expect("type A2");
                    let intent2 = {
                        let composer = shell.composer.as_mut().expect("composer");
                        composer
                            .focus_control(ComposerControl::SendNow, focus_a2)
                            .expect("focus send");
                        composer
                            .activate(ComposerControl::SendNow, focus_a2)
                            .expect("submit A2")
                    };
                    let command_id2 = intent2.command_id;
                    shell.dispatch_composer_intent(intent2);
                    let submitted2 = remote_shared
                        .lock()
                        .expect("remote")
                        .accepted
                        .last()
                        .cloned()
                        .expect("A2 send");
                    shell
                        .select_fleet_task_key(local_key.clone(), FleetSelectMode::Replace)
                        .expect("focus B again");
                    remote_shared.lock().expect("remote").projections.push_back(
                        NativeHostProjection::client_model(Arc::clone(&model)).at_epochs(epochs),
                    );
                    remote_shared.lock().expect("remote").projections.push_back(
                        NativeHostProjection {
                            kind: NativeHostProjectionKind::Replay,
                            client_model: None,
                            task_preview: None,
                            error: None,
                            epochs: Some(epochs),
                            action_outcome: Some(NativeHostActionOutcome::Accepted {
                                action: submitted2,
                                receipt: crate::domain::command::CommandReceipt::Accepted {
                                    command_id: command_id2,
                                    operation_id: crate::domain::id::OperationId::new(),
                                    task_revision: None,
                                    event_ids: Vec::new(),
                                    prompt_mutation: None,
                                },
                            }),
                            owner: None,
                            durable_events: None,
                        },
                    );
                    let _ = shell.drain_fleet_host_projections_round_robin(8);
                    let local_send_total = local_shared
                        .lock()
                        .expect("local")
                        .accepted
                        .iter()
                        .filter(|record| {
                            matches!(record.command, NativeHostCommand::ProviderInput { .. })
                        })
                        .count();
                    let remote_send_total = remote_shared
                        .lock()
                        .expect("remote")
                        .accepted
                        .iter()
                        .filter(|record| {
                            matches!(record.command, NativeHostCommand::ProviderInput { .. })
                        })
                        .count();
                    (
                        !shell
                            .pending_composer_submissions
                            .contains_key(&command_id2),
                        shell
                            .composer_drafts
                            .get(&b_draft_key)
                            .map(|d| d.text.clone()),
                        shell.selected_task_key.clone(),
                        local_send_total,
                        remote_send_total,
                    )
                });
            *report_slot.borrow_mut() = Some(observed);
            drop(entity);
            cx.quit();
        });
        let (cleared2, local_draft, selected, local_accepted, remote_accepted) =
            report.borrow_mut().take().expect("owner send report");
        assert!(
            cleared2,
            "projection-then-receipt must settle A's second pending"
        );
        assert_eq!(local_draft.as_deref(), Some("local-B-newer"));
        assert!(
            selected
                .as_ref()
                .is_some_and(|key| key.host != HostId::Remote([0x44; 16])),
            "settlement must not steal focus back to remote A"
        );
        assert_eq!(
            local_accepted, 0,
            "local runtime must never receive remote sends"
        );
        assert!(remote_accepted >= 2, "remote runtime captured both sends");
    }

    #[test]
    fn owner_gesture_reopen_send_routes_exact_host_not_raw_task_id() {
        if rerun_headless_shell_test_in_child(
            "ui::native_shell::tests::owner_gesture_reopen_send_routes_exact_host_not_raw_task_id",
        ) {
            return;
        }
        let (runtime, local_shared) = TestRuntime::new(true, NativeHostActionResult::Queued);
        let workspace = tempfile::tempdir().expect("workspace");
        let profile = isolated_dev_profile(workspace.path()).expect("profile");
        let remote_host = HostId::Remote([0x66; 16]);
        let report = std::rc::Rc::new(std::cell::RefCell::new(None));
        let report_slot = std::rc::Rc::clone(&report);
        gpui::Application::headless().run(move |cx| {
            crate::ui::init(cx);
            let entity = cx.new(|cx| {
                NativeShell::new_with_host_runtime_port(
                    profile,
                    Box::new(runtime),
                    crate::ui::tokens::RuntimePreferencesSnapshot::default(),
                    cx,
                )
            });
            let observed = entity.update(cx, |shell, _cx| {
                shell.install_idle_conversation_photo_for_test();
                let (settled_model, shared_task) =
                    terminal_bound_client_model_with_kind_provider_lifecycle_at_epoch(
                        crate::domain::task::TaskAttention::None,
                        ProviderKind::Codex,
                        Some("provider-conversation-ready"),
                        1,
                        crate::domain::task::TaskLifecycle::Settled,
                    );
                let settled_model = Arc::new(settled_model);
                let (open_model, open_task) =
                    terminal_bound_client_model_with_kind_provider_at_epoch(
                        crate::domain::task::TaskAttention::None,
                        ProviderKind::Codex,
                        Some("provider-conversation-ready"),
                        1,
                    );
                assert_eq!(shared_task, open_task);
                let open_model = Arc::new(open_model);
                shell
                    .apply_client_model(Arc::clone(&settled_model))
                    .expect("local settled");
                let local = shell.local_host_id();
                let local_key = HostTaskKey::new(local.clone(), shared_task);
                let remote_key = HostTaskKey::new(remote_host.clone(), shared_task);

                let (remote_runtime, remote_shared) =
                    TestRuntime::new(true, NativeHostActionResult::Queued);
                let mut remote_slot = HostUiState::new_empty(
                    remote_host.clone(),
                    NativeHostState::Connected {
                        endpoint: "fleet://reopen".into(),
                    },
                );
                let epochs = remote_runtime.epochs();
                remote_slot.host_runtime = Some(NativeHostRuntimeAttachment::Injected(Box::new(
                    remote_runtime,
                )));
                let _ = remote_slot.interaction.sync_host_epochs(epochs);
                shell
                    .attach_host_ui_slot(remote_slot)
                    .expect("attach remote");
                shell
                    .apply_client_model_for_host(&remote_host, Arc::clone(&settled_model))
                    .expect("remote settled");

                shell
                    .select_fleet_task_key(remote_key.clone(), FleetSelectMode::Replace)
                    .expect("select remote Done");
                let focus = shell
                    .host_slot(&remote_host)
                    .map(|slot| slot.interaction.current_focus_epoch())
                    .expect("remote focus");
                shell
                    .composer
                    .as_mut()
                    .expect("composer")
                    .replace_draft("reopen-then-send", focus)
                    .expect("draft");
                // Real gesture path — not composer.activate + dispatch_composer_intent.
                shell.activate_composer_control(ComposerControl::SendNow);
                let pending_owner = shell
                    .host_slot(&remote_host)
                    .and_then(|slot| slot.pending_settled_send.as_ref())
                    .map(|pending| pending.owner.clone());
                assert_eq!(pending_owner.as_ref(), Some(&remote_key));
                assert!(
                    shell.local_slot().pending_settled_send.is_none(),
                    "local Done with same raw TaskId must not own remote reopen"
                );
                // Duplicate click must not enqueue a second reopen.
                shell.activate_composer_control(ComposerControl::SendNow);
                let reopen_cmds: Vec<_> = remote_shared
                    .lock()
                    .expect("remote")
                    .accepted
                    .iter()
                    .filter(|record| {
                        matches!(
                            record.command,
                            NativeHostCommand::TaskLifecycle {
                                command: crate::domain::command::Command::ReopenTask,
                                ..
                            }
                        )
                    })
                    .cloned()
                    .collect();
                assert_eq!(reopen_cmds.len(), 1, "duplicate Send must not reopen twice");
                assert_eq!(
                    local_shared
                        .lock()
                        .expect("local")
                        .accepted
                        .iter()
                        .filter(|record| {
                            matches!(
                                record.command,
                                NativeHostCommand::TaskLifecycle {
                                    command: crate::domain::command::Command::ReopenTask,
                                    ..
                                }
                            )
                        })
                        .count(),
                    0,
                    "reopen must never hit local when remote owns the gesture"
                );
                let reopen = reopen_cmds.into_iter().next().expect("reopen");
                let reopen_id = native_command_id(&reopen.command).expect("reopen id");

                // Receipt-before-projection.
                shell.apply_epoch_fenced_action_outcome_for_host(
                    &remote_host,
                    NativeHostActionOutcome::Accepted {
                        action: reopen.clone(),
                        receipt: crate::domain::command::CommandReceipt::Accepted {
                            command_id: reopen_id,
                            operation_id: crate::domain::id::OperationId::new(),
                            task_revision: None,
                            event_ids: Vec::new(),
                            prompt_mutation: None,
                        },
                    },
                );
                assert!(
                    shell
                        .host_slot(&remote_host)
                        .and_then(|slot| slot.pending_settled_send.as_ref())
                        .is_some_and(|pending| {
                            pending.stage
                                == super::PendingSettledSendStage::ReopenAcceptedAwaitingActive
                        }),
                    "accepted reopen waits for Open projection"
                );
                shell
                    .apply_client_model_for_host(&remote_host, Arc::clone(&open_model))
                    .expect("remote open");
                let after_open_pending = shell
                    .host_slot(&remote_host)
                    .and_then(|slot| slot.pending_settled_send.clone());
                let remote_inputs = remote_shared
                    .lock()
                    .expect("remote")
                    .accepted
                    .iter()
                    .filter(|record| {
                        matches!(record.command, NativeHostCommand::ProviderInput { .. })
                    })
                    .count();

                // Focus switch mid-flight: park another reopen then switch to local.
                shell
                    .apply_client_model_for_host(&remote_host, Arc::clone(&settled_model))
                    .expect("re-settle remote");
                shell
                    .select_fleet_task_key(remote_key.clone(), FleetSelectMode::Replace)
                    .expect("reselect remote");
                let focus2 = shell
                    .host_slot(&remote_host)
                    .map(|slot| slot.interaction.current_focus_epoch())
                    .expect("focus");
                shell
                    .composer
                    .as_mut()
                    .expect("composer")
                    .replace_draft("keep-on-cancel", focus2)
                    .expect("draft");
                shell.activate_composer_control(ComposerControl::SendNow);
                shell
                    .select_fleet_task_key(local_key.clone(), FleetSelectMode::Replace)
                    .expect("switch to local identical TaskId");
                let cancelled = shell
                    .host_slot(&remote_host)
                    .map(|slot| slot.pending_settled_send.is_none())
                    .unwrap_or(false);
                let remote_error = shell
                    .host_slot(&remote_host)
                    .and_then(|slot| slot.composer_error.clone());
                let local_error = shell.local_slot().composer_error.clone();
                let draft_key = NativeShell::fleet_draft_key_for(
                    remote_key.clone(),
                    settled_model
                        .task(shared_task)
                        .and_then(|snap| snap.primary_agent_id)
                        .expect("agent"),
                );
                let retained_draft = shell
                    .composer_drafts
                    .get(&draft_key)
                    .map(|draft| draft.text.clone());

                // Stale epoch fence: reopen receipt after runtime bump must cancel.
                shell
                    .select_fleet_task_key(remote_key.clone(), FleetSelectMode::Replace)
                    .expect("back to remote");
                shell
                    .apply_client_model_for_host(&remote_host, Arc::clone(&settled_model))
                    .expect("settled again");
                let focus3 = shell
                    .host_slot(&remote_host)
                    .map(|slot| slot.interaction.current_focus_epoch())
                    .expect("focus");
                shell
                    .composer
                    .as_mut()
                    .expect("composer")
                    .replace_draft("stale-fence", focus3)
                    .expect("draft");
                shell.activate_composer_control(ComposerControl::SendNow);
                let stale_reopen = remote_shared
                    .lock()
                    .expect("remote")
                    .accepted
                    .iter()
                    .rev()
                    .find(|record| {
                        matches!(
                            record.command,
                            NativeHostCommand::TaskLifecycle {
                                command: crate::domain::command::Command::ReopenTask,
                                ..
                            }
                        )
                    })
                    .cloned()
                    .expect("stale reopen");
                if let Some(slot) = shell.host_slot_mut(&remote_host) {
                    let _ = slot.interaction.sync_host_epochs(NativeHostRuntimeEpochs {
                        connection_epoch: epochs.connection_epoch.saturating_add(1),
                        resource_generation: epochs.resource_generation,
                        runtime_generation: epochs.runtime_generation,
                    });
                }
                shell.apply_epoch_fenced_action_outcome_for_host(
                    &remote_host,
                    NativeHostActionOutcome::Accepted {
                        action: stale_reopen.clone(),
                        receipt: crate::domain::command::CommandReceipt::Accepted {
                            command_id: native_command_id(&stale_reopen.command).expect("id"),
                            operation_id: crate::domain::id::OperationId::new(),
                            task_revision: None,
                            event_ids: Vec::new(),
                            prompt_mutation: None,
                        },
                    },
                );
                let stale_cleared = shell
                    .host_slot(&remote_host)
                    .map(|slot| slot.pending_settled_send.is_none())
                    .unwrap_or(false);
                let stale_error = shell
                    .host_slot(&remote_host)
                    .and_then(|slot| slot.composer_error.clone());

                (
                    after_open_pending.is_none(),
                    remote_inputs,
                    cancelled,
                    remote_error,
                    local_error,
                    retained_draft,
                    stale_cleared,
                    stale_error,
                    shell.local_slot().pending_settled_send.is_none(),
                )
            });
            *report_slot.borrow_mut() = Some(observed);
            drop(entity);
            cx.quit();
        });
        let (
            advanced,
            remote_inputs,
            cancelled,
            remote_error,
            local_error,
            retained_draft,
            stale_cleared,
            stale_error,
            local_pending_clear,
        ) = report.borrow_mut().take().expect("reopen report");
        assert!(
            advanced,
            "Open projection must clear reopen pending then send"
        );
        assert!(
            remote_inputs >= 1,
            "exact owner must receive one follow-up send after reopen"
        );
        assert!(
            cancelled,
            "focus switch must cancel remote reopen follow-up"
        );
        assert!(
            remote_error
                .as_deref()
                .is_some_and(|msg| msg.contains("Selection changed")),
            "cancel must surface on owner slot: {remote_error:?}"
        );
        assert!(
            local_error.is_none(),
            "focus switch must not write cancel onto the other host"
        );
        assert_eq!(retained_draft.as_deref(), Some("keep-on-cancel"));
        assert!(stale_cleared, "stale epoch must clear pending reopen");
        assert!(
            stale_error
                .as_deref()
                .is_some_and(|msg| msg.contains("connection changed")),
            "stale fence must keep draft with owner error: {stale_error:?}"
        );
        assert!(local_pending_clear);
    }

    #[test]
    fn owner_gesture_first_send_routes_readiness_and_focus_fences() {
        if rerun_headless_shell_test_in_child(
            "ui::native_shell::tests::owner_gesture_first_send_routes_readiness_and_focus_fences",
        ) {
            return;
        }
        let (runtime, local_shared) = TestRuntime::new(true, NativeHostActionResult::Queued);
        let workspace = tempfile::tempdir().expect("workspace");
        let profile = isolated_dev_profile(workspace.path()).expect("profile");
        let remote_host = HostId::Remote([0x77; 16]);
        let report = std::rc::Rc::new(std::cell::RefCell::new(None));
        let report_slot = std::rc::Rc::clone(&report);
        gpui::Application::headless().run(move |cx| {
            crate::ui::init(cx);
            let entity = cx.new(|cx| {
                NativeShell::new_with_host_runtime_port(
                    profile,
                    Box::new(runtime),
                    crate::ui::tokens::RuntimePreferencesSnapshot::default(),
                    cx,
                )
            });
            let observed = entity.update(cx, |shell, _cx| {
                shell.install_idle_conversation_photo_for_test();
                let (draft_model, shared_task) =
                    terminal_bound_client_model_with_kind_provider_at_epoch(
                        crate::domain::task::TaskAttention::None,
                        ProviderKind::Codex,
                        None,
                        1,
                    );
                let draft_model = Arc::new(draft_model);
                let (ready_model, ready_task) =
                    terminal_bound_client_model_with_kind_provider_at_epoch(
                        crate::domain::task::TaskAttention::None,
                        ProviderKind::Codex,
                        Some("provider-conversation-ready"),
                        1,
                    );
                assert_eq!(shared_task, ready_task);
                let ready_model = Arc::new(ready_model);
                shell
                    .apply_client_model(Arc::clone(&draft_model))
                    .expect("local draft");
                let local = shell.local_host_id();
                let local_key = HostTaskKey::new(local.clone(), shared_task);
                let remote_key = HostTaskKey::new(remote_host.clone(), shared_task);

                let (remote_runtime, remote_shared) =
                    TestRuntime::new(true, NativeHostActionResult::Queued);
                let mut remote_slot = HostUiState::new_empty(
                    remote_host.clone(),
                    NativeHostState::Connected {
                        endpoint: "fleet://first-send".into(),
                    },
                );
                let epochs = remote_runtime.epochs();
                remote_slot.host_runtime = Some(NativeHostRuntimeAttachment::Injected(Box::new(
                    remote_runtime,
                )));
                let _ = remote_slot.interaction.sync_host_epochs(epochs);
                shell.attach_host_ui_slot(remote_slot).expect("attach");
                shell
                    .apply_client_model_for_host(&remote_host, Arc::clone(&draft_model))
                    .expect("remote draft");
                shell
                    .select_fleet_task_key(remote_key.clone(), FleetSelectMode::Replace)
                    .expect("select remote draft");
                let draft_snapshot = draft_model.task(shared_task).expect("draft snapshot");
                let draft_agent = draft_snapshot.primary_agent_id.expect("draft agent");
                let draft_resource = draft_snapshot
                    .resources
                    .values()
                    .find(|resource| {
                        resource.resource_kind == crate::domain::resource::ResourceKind::Terminal
                    })
                    .expect("draft terminal resource");
                shell
                    .task_surfaces
                    .admit_terminal(
                        remote_key.clone(),
                        &crate::domain::cockpit::TaskTerminalProjection {
                            task_id: shared_task,
                            terminal_id: crate::domain::TerminalId::new(),
                            session_id: crate::terminal::protocol::TerminalSessionId::new(),
                            agent_session_id: draft_agent,
                            resource_id: draft_resource.id,
                            runtime_generation: draft_snapshot.agents[&draft_agent]
                                .runtime_generation,
                            resource_generation: draft_resource.runtime_generation,
                            action_epoch: draft_snapshot.task.action_epoch,
                            focus_epoch: crate::terminal::protocol::FocusEpoch::initial(),
                            accepted_input_sequence: 0,
                            accepts_input_without_conversation_id: false,
                            sequence: 1,
                            title: Some("provider terminal starting".into()),
                            text_lines: vec!["> ".into()],
                            screen: Default::default(),
                            is_provider: true,
                            runtime_state: crate::domain::cockpit::TerminalRuntimeStateWire::Running,
                        },
                    )
                    .expect("interactive provider terminal projection");
                assert!(
                    shell.selected_task_is_unstarted_draft_for(&remote_key),
                    "a terminal surface alone must not bypass the explicit first-send provider launch"
                );
                shell.set_composer_model(crate::providers::ProviderModel::CodexTerra);
                shell.set_composer_reasoning(crate::providers::ProviderReasoningEffort::High);
                shell.set_composer_access(crate::providers::ProviderAccessMode::ReadOnly);
                // Model the real text-input gesture: the eager conversation query
                // advances the host interaction epoch after the composer binds, so
                // editing must first rearm the exact remote owner.
                let focus = shell.rearm_composer_focus().expect("fresh remote focus");
                shell
                    .composer
                    .as_mut()
                    .expect("composer")
                    .replace_draft("first-send-body", focus)
                    .expect("draft");
                shell.activate_composer_control(ComposerControl::SendNow);
                assert!(
                    shell
                        .host_slot(&remote_host)
                        .and_then(|slot| slot.pending_draft_first_send.as_ref())
                        .is_some_and(|pending| {
                            pending.owner == remote_key
                                && pending.stage
                                    == super::PendingDraftFirstSendStage::AwaitingRuntimeProbe
                        }),
                    "first-send pending must retain immutable remote owner at probe stage"
                );
                assert!(shell.local_slot().pending_draft_first_send.is_none());
                shell.draft_launch_prefs.insert(
                    remote_key.clone(),
                    (
                        ProviderKind::Codex,
                        crate::providers::ProviderLaunchOptions {
                            model: crate::providers::ProviderModel::CodexLuna,
                            reasoning_effort:
                                crate::providers::ProviderReasoningEffort::Medium,
                            access: crate::providers::ProviderAccessMode::FullAccess,
                            ..crate::providers::ProviderLaunchOptions::default()
                        },
                    ),
                );
                let probes: Vec<_> = remote_shared
                    .lock()
                    .expect("remote")
                    .accepted
                    .iter()
                    .filter(|record| {
                        matches!(
                            record.command,
                            NativeHostCommand::TaskCockpitQuery {
                                query: TaskCockpitQuery::TerminalReadiness,
                                ..
                            }
                        )
                    })
                    .cloned()
                    .collect();
                assert_eq!(
                    probes.len(),
                    1,
                    "first send must probe TerminalReadiness before start"
                );
                assert_eq!(
                    remote_shared
                        .lock()
                        .expect("remote")
                        .accepted
                        .iter()
                        .filter(|record| {
                            matches!(record.command, NativeHostCommand::ProviderStart { .. })
                        })
                        .count(),
                    0,
                    "must not StartProviderSession before probe settles"
                );
                shell.activate_composer_control(ComposerControl::SendNow);
                assert_eq!(
                    remote_shared
                        .lock()
                        .expect("remote")
                        .accepted
                        .iter()
                        .filter(|record| {
                            matches!(
                                record.command,
                                NativeHostCommand::TaskCockpitQuery {
                                    query: TaskCockpitQuery::TerminalReadiness,
                                    ..
                                }
                            )
                        })
                        .count(),
                    1,
                    "duplicate click must not re-probe while pending"
                );
                let probe = probes.into_iter().next().expect("probe");
                shell.apply_epoch_fenced_action_outcome_for_host(
                    &remote_host,
                    NativeHostActionOutcome::Queried {
                        action: probe,
                        detail: "unattested terminal placeholder".into(),
                        body: NativeHostQueryBody::TaskCockpit(
                            crate::domain::TaskCockpitResult::Terminal(
                                crate::domain::TaskTerminalProjection {
                                    task_id: shared_task,
                                    terminal_id: crate::domain::TerminalId::new(),
                                    session_id:
                                        crate::terminal::protocol::TerminalSessionId::new(),
                                    agent_session_id: draft_agent,
                                    resource_id: draft_resource.id,
                                    runtime_generation: draft_snapshot.agents[&draft_agent]
                                        .runtime_generation,
                                    resource_generation: draft_resource.runtime_generation,
                                    action_epoch: draft_snapshot.task.action_epoch,
                                    focus_epoch:
                                        crate::terminal::protocol::FocusEpoch::initial(),
                                    accepted_input_sequence: 0,
                                    accepts_input_without_conversation_id: false,
                                    sequence: 2,
                                    title: Some("provider terminal placeholder".into()),
                                    text_lines: vec!["> ".into()],
                                    screen: Default::default(),
                                    is_provider: true,
                                    runtime_state: crate::domain::cockpit::TerminalRuntimeStateWire::Running,
                                },
                            ),
                        ),
                    },
                );
                let starts: Vec<_> = remote_shared
                    .lock()
                    .expect("remote")
                    .accepted
                    .iter()
                    .filter(|record| {
                        matches!(record.command, NativeHostCommand::ProviderStart { .. })
                    })
                    .cloned()
                    .collect();
                assert_eq!(
                    starts.len(),
                    1,
                    "an unattested terminal placeholder must dispatch exactly one start"
                );
                let NativeHostCommand::ProviderStart { arguments, .. } = &starts[0].command else {
                    unreachable!("filtered to provider start")
                };
                assert_eq!(
                    arguments.launch_options.model,
                    crate::providers::ProviderModel::CodexTerra
                );
                assert_eq!(
                    arguments.launch_options.reasoning_effort,
                    crate::providers::ProviderReasoningEffort::High
                );
                assert_eq!(
                    arguments.launch_options.access,
                    crate::providers::ProviderAccessMode::ReadOnly
                );
                assert_eq!(
                    local_shared
                        .lock()
                        .expect("local")
                        .accepted
                        .iter()
                        .filter(|record| {
                            matches!(record.command, NativeHostCommand::ProviderStart { .. })
                        })
                        .count(),
                    0
                );
                let start = starts.into_iter().next().expect("start");
                let start_id = native_command_id(&start.command).expect("start id");

                // Projection-before-receipt: Open/ready model first must not send yet.
                shell
                    .apply_client_model_for_host(&remote_host, Arc::clone(&ready_model))
                    .expect("ready before receipt");
                assert!(
                    shell
                        .host_slot(&remote_host)
                        .and_then(|slot| slot.pending_draft_first_send.as_ref())
                        .is_some_and(|pending| {
                            pending.stage == super::PendingDraftFirstSendStage::AwaitingStartReceipt
                        }),
                    "missing start receipt must keep waiting"
                );
                assert_eq!(
                    remote_shared
                        .lock()
                        .expect("remote")
                        .accepted
                        .iter()
                        .filter(|record| {
                            matches!(record.command, NativeHostCommand::ProviderInput { .. })
                        })
                        .count(),
                    0,
                    "must not send before exact start receipt"
                );

                // Receipt then ready → one send.
                shell
                    .apply_client_model_for_host(&remote_host, Arc::clone(&draft_model))
                    .expect("back to draft for receipt order");
                shell.apply_epoch_fenced_action_outcome_for_host(
                    &remote_host,
                    NativeHostActionOutcome::Accepted {
                        action: start.clone(),
                        receipt: crate::domain::command::CommandReceipt::Accepted {
                            command_id: start_id,
                            operation_id: crate::domain::id::OperationId::new(),
                            task_revision: None,
                            event_ids: Vec::new(),
                            prompt_mutation: None,
                        },
                    },
                );
                shell
                    .apply_client_model_for_host(&remote_host, Arc::clone(&ready_model))
                    .expect("ready after receipt");
                let sent_after_ready = remote_shared
                    .lock()
                    .expect("remote")
                    .accepted
                    .iter()
                    .filter(|record| {
                        matches!(record.command, NativeHostCommand::ProviderInput { .. })
                    })
                    .count();

                // Focus switch cancels follow-up; draft retained on owner.
                shell
                    .apply_client_model_for_host(&remote_host, Arc::clone(&draft_model))
                    .expect("draft again");
                shell
                    .select_fleet_task_key(remote_key.clone(), FleetSelectMode::Replace)
                    .expect("reselect");
                let focus2 = shell
                    .host_slot(&remote_host)
                    .map(|slot| slot.interaction.current_focus_epoch())
                    .expect("focus");
                shell
                    .composer
                    .as_mut()
                    .expect("composer")
                    .replace_draft("first-send-cancel", focus2)
                    .expect("draft");
                shell.activate_composer_control(ComposerControl::SendNow);
                shell
                    .select_fleet_task_key(local_key.clone(), FleetSelectMode::Replace)
                    .expect("switch host");
                let cancelled = shell
                    .host_slot(&remote_host)
                    .map(|slot| slot.pending_draft_first_send.is_none())
                    .unwrap_or(false);
                let remote_error = shell
                    .host_slot(&remote_host)
                    .and_then(|slot| slot.composer_error.clone());
                let local_error_before = shell.local_slot().composer_error.clone();
                let agent = draft_model
                    .task(shared_task)
                    .and_then(|snap| snap.primary_agent_id)
                    .expect("agent");
                let draft_key = NativeShell::fleet_draft_key_for(remote_key.clone(), agent);
                let retained = shell
                    .composer_drafts
                    .get(&draft_key)
                    .map(|draft| draft.text.clone());

                // Unsupported Cursor transport: exercise the real provider picker.
                // Unstarted drafts prefer draft_launch_prefs / layout over durable
                // agent kind — applying a Cursor model alone does not select Cursor.
                shell
                    .select_fleet_task_key(remote_key.clone(), FleetSelectMode::Replace)
                    .expect("remote again");
                let (cursor_model, cursor_task) =
                    terminal_bound_client_model_with_kind_provider_at_epoch(
                        crate::domain::task::TaskAttention::None,
                        ProviderKind::Cursor,
                        None,
                        1,
                    );
                assert_eq!(cursor_task, shared_task);
                shell
                    .apply_client_model_for_host(&remote_host, Arc::new(cursor_model))
                    .expect("cursor draft");
                let focus3 = shell
                    .host_slot(&remote_host)
                    .map(|slot| slot.interaction.current_focus_epoch())
                    .expect("focus");
                shell
                    .composer
                    .as_mut()
                    .expect("composer")
                    .replace_draft("cursor-blocked", focus3)
                    .expect("draft");
                shell.set_composer_provider(ProviderKind::Cursor);
                assert_eq!(
                    shell.composer_provider_for_launch(),
                    Some(ProviderKind::Cursor),
                    "provider picker must bind Cursor before SendNow"
                );
                let starts_before_cursor = remote_shared
                    .lock()
                    .expect("remote")
                    .accepted
                    .iter()
                    .filter(|record| {
                        matches!(record.command, NativeHostCommand::ProviderStart { .. })
                    })
                    .count();
                shell.activate_composer_control(ComposerControl::SendNow);
                let starts_after_cursor = remote_shared
                    .lock()
                    .expect("remote")
                    .accepted
                    .iter()
                    .filter(|record| {
                        matches!(record.command, NativeHostCommand::ProviderStart { .. })
                    })
                    .count();
                let cursor_error = shell
                    .host_slot(&remote_host)
                    .and_then(|slot| slot.composer_error.clone());
                let local_error_after = shell.local_slot().composer_error.clone();
                let launch_after = shell.composer_provider_for_launch();

                (
                    sent_after_ready,
                    cancelled,
                    remote_error,
                    local_error_before,
                    retained,
                    starts_before_cursor,
                    starts_after_cursor,
                    cursor_error,
                    local_error_after,
                    launch_after,
                )
            });
            *report_slot.borrow_mut() = Some(observed);
            drop(entity);
            cx.quit();
        });
        let (
            sent_after_ready,
            cancelled,
            remote_error,
            local_error_before,
            retained,
            starts_before_cursor,
            starts_after_cursor,
            cursor_error,
            local_error_after,
            launch_after,
        ) = report.borrow_mut().take().expect("first-send report");
        assert_eq!(
            sent_after_ready, 1,
            "exact receipt + ready projection must send once"
        );
        assert!(cancelled);
        assert!(
            remote_error
                .as_deref()
                .is_some_and(|msg| msg.contains("Selection changed")),
            "{remote_error:?}"
        );
        assert_eq!(local_error_before, None);
        assert_eq!(retained.as_deref(), Some("first-send-cancel"));
        assert_eq!(starts_before_cursor, starts_after_cursor);
        assert!(
            cursor_error
                .as_deref()
                .is_some_and(|msg| msg.contains("Cursor") || msg.contains("chat transport")),
            "{cursor_error:?}"
        );
        assert_eq!(
            local_error_after, local_error_before,
            "cursor refusal must not mutate the other host error"
        );
        assert_eq!(
            launch_after,
            Some(ProviderKind::Cursor),
            "Cursor picker selection must remain the last-used draft default"
        );
    }

    #[test]
    fn remote_done_click_opens_without_restoring_lifecycle() {
        if rerun_headless_shell_test_in_child(
            "ui::native_shell::tests::remote_done_click_opens_without_restoring_lifecycle",
        ) {
            return;
        }
        let (runtime, _) = TestRuntime::new(true, NativeHostActionResult::Queued);
        let workspace = tempfile::tempdir().expect("workspace");
        let profile = isolated_dev_profile(workspace.path()).expect("profile");
        let remote_host = HostId::Remote([0x55; 16]);
        let report = std::rc::Rc::new(std::cell::RefCell::new(None));
        let report_slot = std::rc::Rc::clone(&report);
        gpui::Application::headless().run(move |cx| {
            crate::ui::init(cx);
            let entity = cx.new(|cx| {
                NativeShell::new_with_host_runtime_port(
                    profile,
                    Box::new(runtime),
                    crate::ui::tokens::RuntimePreferencesSnapshot::default(),
                    cx,
                )
            });
            let observed = entity.update(cx, |shell, _cx| {
                let shared = TaskId::new();
                let remote_key = HostTaskKey::new(remote_host.clone(), shared);
                let (remote_runtime, shared_state) =
                    TestRuntime::new(true, NativeHostActionResult::Queued);
                let mut remote_slot = HostUiState::new_empty(
                    remote_host.clone(),
                    NativeHostState::Connected {
                        endpoint: "fleet://done".into(),
                    },
                );
                remote_slot.host_runtime = Some(NativeHostRuntimeAttachment::Injected(Box::new(
                    remote_runtime,
                )));
                let mut snapshot = preview_task_snapshot(shared, "done-remote");
                snapshot.task.lifecycle = crate::domain::task::TaskLifecycle::Settled;
                let preview =
                    TaskInboxPreview::from_tasks_for_test(BTreeMap::from([(shared, snapshot)]), 1);
                remote_slot.inbox = Inbox::from_task_preview(&preview);
                remote_slot.task_list =
                    TaskList::from_virtual_task_ids(vec![shared]).expect("list");
                shell.attach_host_ui_slot(remote_slot).expect("attach");
                shell
                    .select_fleet_task_key(remote_key.clone(), FleetSelectMode::Replace)
                    .expect("open done");
                let restore_commands = shared_state
                    .lock()
                    .expect("state")
                    .accepted
                    .iter()
                    .filter(|record| {
                        matches!(
                            record.command,
                            NativeHostCommand::TaskLifecycle {
                                command: crate::domain::command::Command::ReopenTask,
                                ..
                            }
                        )
                    })
                    .count();
                let lifecycle = shell
                    .host_slot(&remote_host)
                    .and_then(|slot| slot.inbox.row(shared))
                    .map(|row| row.lifecycle);
                (shell.selected_task_key.clone(), lifecycle, restore_commands)
            });
            *report_slot.borrow_mut() = Some(observed);
            drop(entity);
            cx.quit();
        });
        let (selected, lifecycle, restore_commands) =
            report.borrow_mut().take().expect("done report");
        assert_eq!(
            selected.as_ref().map(|key| &key.host),
            Some(&HostId::Remote([0x55; 16]))
        );
        assert_eq!(
            lifecycle,
            Some(crate::domain::task::TaskLifecycle::Settled),
            "Done click must not restore lifecycle"
        );
        assert_eq!(
            restore_commands, 0,
            "Done click must not dispatch a restore command"
        );
    }

    #[test]
    fn first_send_live_identityless_codex_probes_without_start() {
        if rerun_headless_shell_test_in_child(
            "ui::native_shell::tests::first_send_live_identityless_codex_probes_without_start",
        ) {
            return;
        }
        let (runtime, _) = TestRuntime::new(true, NativeHostActionResult::Queued);
        let workspace = tempfile::tempdir().expect("workspace");
        let profile = isolated_dev_profile(workspace.path()).expect("profile");
        let remote_host = HostId::Remote([0x41; 16]);
        let report = std::rc::Rc::new(std::cell::RefCell::new(None));
        let report_slot = std::rc::Rc::clone(&report);
        gpui::Application::headless().run(move |cx| {
            crate::ui::init(cx);
            let entity = cx.new(|cx| {
                NativeShell::new_with_host_runtime_port(
                    profile,
                    Box::new(runtime),
                    crate::ui::tokens::RuntimePreferencesSnapshot::default(),
                    cx,
                )
            });
            let observed = entity.update(cx, |shell, _cx| {
                shell.install_idle_conversation_photo_for_test();
                let (draft_model, task_id) =
                    terminal_bound_client_model_with_kind_provider_at_epoch(
                        crate::domain::task::TaskAttention::None,
                        ProviderKind::Codex,
                        None,
                        1,
                    );
                let draft_model = Arc::new(draft_model);
                let snapshot = draft_model.task(task_id).expect("task");
                let agent_id = snapshot.primary_agent_id.expect("agent");
                let resource = snapshot.resources.values().next().expect("resource");
                let terminal = crate::domain::TaskTerminalProjection {
                    task_id,
                    terminal_id: crate::domain::TerminalId::new(),
                    session_id: crate::terminal::protocol::TerminalSessionId::new(),
                    agent_session_id: agent_id,
                    resource_id: resource.id,
                    runtime_generation: snapshot.agents[&agent_id].runtime_generation,
                    resource_generation: resource.runtime_generation,
                    action_epoch: 1,
                    focus_epoch: crate::terminal::protocol::FocusEpoch::initial(),
                    accepted_input_sequence: 0,
                    accepts_input_without_conversation_id: true,
                    sequence: 1,
                    title: None,
                    text_lines: vec!["  › Ask Codex to do anything".into()],
                    screen: Default::default(),
                    is_provider: true,
                    runtime_state: crate::domain::cockpit::TerminalRuntimeStateWire::Running,
                };
                let (remote_runtime, remote_shared) =
                    TestRuntime::new(true, NativeHostActionResult::Queued);
                let epochs = remote_runtime.epochs();
                let mut remote_slot = HostUiState::new_empty(
                    remote_host.clone(),
                    NativeHostState::Connected {
                        endpoint: "https://live-codex.example:9443".into(),
                    },
                );
                remote_slot.host_runtime = Some(NativeHostRuntimeAttachment::Injected(Box::new(
                    remote_runtime,
                )));
                let _ = remote_slot.interaction.sync_host_epochs(epochs);
                shell.attach_host_ui_slot(remote_slot).expect("attach");
                shell
                    .apply_client_model_for_host(&remote_host, Arc::clone(&draft_model))
                    .expect("draft");
                let remote_key = HostTaskKey::new(remote_host.clone(), task_id);
                shell
                    .select_fleet_task_key(remote_key.clone(), FleetSelectMode::Replace)
                    .expect("select");
                let focus = shell
                    .host_slot(&remote_host)
                    .map(|slot| slot.interaction.current_focus_epoch())
                    .expect("focus");
                shell
                    .composer
                    .as_mut()
                    .expect("composer")
                    .replace_draft("identityless-live", focus)
                    .expect("draft");
                shell.activate_composer_control(ComposerControl::SendNow);
                let probe = remote_shared
                    .lock()
                    .expect("remote")
                    .accepted
                    .iter()
                    .find(|record| {
                        matches!(
                            record.command,
                            NativeHostCommand::TaskCockpitQuery {
                                query: TaskCockpitQuery::TerminalReadiness,
                                ..
                            }
                        )
                    })
                    .cloned()
                    .expect("probe");
                shell.apply_epoch_fenced_action_outcome_for_host(
                    &remote_host,
                    NativeHostActionOutcome::Queried {
                        action: probe,
                        detail: "live terminal".into(),
                        body: NativeHostQueryBody::TaskCockpit(
                            crate::domain::TaskCockpitResult::Terminal(terminal),
                        ),
                    },
                );
                let starts = remote_shared
                    .lock()
                    .expect("remote")
                    .accepted
                    .iter()
                    .filter(|record| {
                        matches!(record.command, NativeHostCommand::ProviderStart { .. })
                    })
                    .count();
                let sends = remote_shared
                    .lock()
                    .expect("remote")
                    .accepted
                    .iter()
                    .filter(|record| {
                        matches!(record.command, NativeHostCommand::ProviderInput { .. })
                    })
                    .count();
                let probes = remote_shared
                    .lock()
                    .expect("remote")
                    .accepted
                    .iter()
                    .filter(|record| {
                        matches!(
                            record.command,
                            NativeHostCommand::TaskCockpitQuery {
                                query: TaskCockpitQuery::TerminalReadiness,
                                ..
                            }
                        )
                    })
                    .count();
                (probes, starts, sends)
            });
            *report_slot.borrow_mut() = Some(observed);
            drop(entity);
            cx.quit();
        });
        let (probes, starts, sends) = report.borrow_mut().take().expect("report");
        assert_eq!(probes, 1, "exactly one TerminalReadiness probe");
        assert_eq!(
            starts, 0,
            "live identityless Codex must not StartProviderSession"
        );
        assert_eq!(sends, 1, "exact attestation must advance one send");
    }

    #[test]
    fn first_send_trust_screen_presents_approval_and_keeps_pending_send() {
        if rerun_headless_shell_test_in_child(
            "ui::native_shell::tests::first_send_trust_screen_presents_approval_and_keeps_pending_send",
        ) {
            return;
        }
        let (runtime, _) = TestRuntime::new(true, NativeHostActionResult::Queued);
        let workspace = tempfile::tempdir().expect("workspace");
        let profile = isolated_dev_profile(workspace.path()).expect("profile");
        let remote_host = HostId::Remote([0x4b; 16]);
        let report = std::rc::Rc::new(std::cell::RefCell::new(None));
        let report_slot = std::rc::Rc::clone(&report);
        gpui::Application::headless().run(move |cx| {
            crate::ui::init(cx);
            let entity = cx.new(|cx| {
                NativeShell::new_with_host_runtime_port(
                    profile,
                    Box::new(runtime),
                    crate::ui::tokens::RuntimePreferencesSnapshot::default(),
                    cx,
                )
            });
            let observed = entity.update(cx, |shell, _cx| {
                shell.install_idle_conversation_photo_for_test();
                let project_id = crate::domain::id::ProjectId::new();
                shell.install_project_for_test("DevManager", project_id);
                let (draft_model, task_id) =
                    terminal_bound_client_model_with_kind_provider_at_epoch(
                        crate::domain::task::TaskAttention::None,
                        ProviderKind::Codex,
                        None,
                        1,
                    );
                let draft_model = Arc::new(draft_model);
                let (remote_runtime, remote_shared) =
                    TestRuntime::new(true, NativeHostActionResult::Queued);
                let epochs = remote_runtime.epochs();
                let mut remote_slot = HostUiState::new_empty(
                    remote_host.clone(),
                    NativeHostState::Connected {
                        endpoint: "https://trust-hold.example:9443".into(),
                    },
                );
                remote_slot.host_runtime =
                    Some(NativeHostRuntimeAttachment::Injected(Box::new(remote_runtime)));
                let _ = remote_slot.interaction.sync_host_epochs(epochs);
                shell.attach_host_ui_slot(remote_slot).expect("attach");
                shell
                    .apply_client_model_for_host(&remote_host, Arc::clone(&draft_model))
                    .expect("draft");
                let remote_key = HostTaskKey::new(remote_host.clone(), task_id);
                shell
                    .select_fleet_task_key(remote_key.clone(), FleetSelectMode::Replace)
                    .expect("select");
                let focus = shell
                    .host_slot(&remote_host)
                    .map(|slot| slot.interaction.current_focus_epoch())
                    .expect("focus");
                shell
                    .composer
                    .as_mut()
                    .expect("composer")
                    .replace_draft("held on trust", focus)
                    .expect("draft");
                shell.cache_current_composer_draft();
                shell.activate_composer_control(ComposerControl::SendNow);
                let probe = remote_shared
                    .lock()
                    .expect("remote")
                    .accepted
                    .iter()
                    .find(|record| {
                        matches!(
                            record.command,
                            NativeHostCommand::TaskCockpitQuery {
                                query: TaskCockpitQuery::TerminalReadiness,
                                ..
                            }
                        )
                    })
                    .cloned()
                    .expect("probe");
                shell.apply_epoch_fenced_action_outcome_for_host(
                    &remote_host,
                    NativeHostActionOutcome::Queried {
                        action: probe,
                        detail: "trust setup".into(),
                        body: NativeHostQueryBody::TaskCockpit(
                            crate::domain::TaskCockpitResult::Unavailable {
                                surface: crate::domain::TaskCockpitSurface::Terminal,
                                reason:
                                    crate::domain::TaskCockpitUnavailableReason::TerminalProviderSetupRequired,
                            detail: None,},
                        ),
                    },
                );
                let sends = remote_shared
                    .lock()
                    .expect("remote")
                    .accepted
                    .iter()
                    .filter(|record| {
                        matches!(record.command, NativeHostCommand::ProviderInput { .. })
                    })
                    .count();
                let draft = shell
                    .composer
                    .as_ref()
                    .expect("composer")
                    .draft_text()
                    .to_string();
                let error = shell
                    .host_slot(&remote_host)
                    .and_then(|slot| slot.composer_error.clone());
                let pending = shell
                    .host_slot(&remote_host)
                    .and_then(|slot| slot.pending_draft_first_send.clone());
                let approval = shell
                    .host_slot(&remote_host)
                    .and_then(|slot| slot.provider_setup_approvals.get(&task_id))
                    .cloned();
                let status = shell.task_row_status_for_owner(&remote_key);
                shell.refresh_accessibility_tree();
                let accessibility_ids = shell
                    .accessibility_tree
                    .gpui_nodes()
                    .into_iter()
                    .map(|node| node.element_id)
                    .collect::<std::collections::HashSet<_>>();
                let approval_accessible = accessibility_ids
                    .contains("native-provider-setup-approval")
                    && accessibility_ids.contains("native-provider-setup-reject")
                    && accessibility_ids.contains("native-provider-setup-approve");
                let setup_command_id = CommandId::new();
                let completion: ProviderSetupInputCompletion = Arc::new(Mutex::new(Some(Ok(
                    InputAck::Accepted { sequence: 1 },
                ))));
                if let Some(slot) = shell.host_slot_mut(&remote_host) {
                    slot.provider_setup_approvals.insert(
                        task_id,
                        ProviderSetupApproval {
                            owner: remote_key.clone(),
                            state: ProviderSetupApprovalState::Resolving {
                                command_id: setup_command_id,
                                allow: true,
                                started_at: Instant::now(),
                            },
                        },
                    );
                    slot.provider_setup_input_completions
                        .insert(task_id, completion);
                }
                let resolving = shell
                    .host_slot(&remote_host)
                    .and_then(|slot| slot.provider_setup_approvals.get(&task_id))
                    .map(|approval| approval.state.clone());
                assert!(shell.settle_provider_setup_input_completions());
                let approval_after_receipt = shell
                    .host_slot(&remote_host)
                    .and_then(|slot| slot.provider_setup_approvals.get(&task_id))
                    .map(|approval| approval.state.clone());
                let pending_after_receipt = shell
                    .host_slot(&remote_host)
                    .is_some_and(|slot| slot.pending_draft_first_send.is_some());
                (
                    sends,
                    draft,
                    error,
                    pending.is_some(),
                    approval,
                    status,
                    approval_accessible,
                    remote_key,
                    resolving,
                    setup_command_id,
                    approval_after_receipt,
                    pending_after_receipt,
                )
            });
            *report_slot.borrow_mut() = Some(observed);
            drop(entity);
            cx.quit();
        });
        let (
            sends,
            draft,
            error,
            pending,
            approval,
            status,
            approval_accessible,
            remote_key,
            resolving,
            setup_command_id,
            approval_after_receipt,
            pending_after_receipt,
        ) = report.borrow_mut().take().expect("report");
        assert_eq!(sends, 0, "trust screen must produce zero provider writes");
        assert_eq!(draft, "held on trust");
        assert_eq!(
            error, None,
            "approval is a task state, not a composer error"
        );
        assert!(
            pending,
            "the accepted Send gesture must remain parked until the user decides"
        );
        let approval = approval.expect("provider setup approval");
        assert_eq!(approval.owner, remote_key);
        assert_eq!(approval.state, super::ProviderSetupApprovalState::Waiting);
        assert_eq!(status, Some(VisibleTaskStatus::NeedsApproval));
        assert!(
            approval_accessible,
            "workspace trust decision must be exposed to accessibility actions"
        );
        assert!(matches!(
            resolving,
            Some(super::ProviderSetupApprovalState::Resolving {
                command_id,
                allow: true,
                ..
            }) if command_id == setup_command_id
        ));
        assert!(
            matches!(
                approval_after_receipt,
                Some(super::ProviderSetupApprovalState::Resolving {
                    command_id,
                    allow: true,
                    ..
                }) if command_id == setup_command_id
            ),
            "accepted PTY write must keep the card single-flight until the provider consumes it",
        );
        assert!(
            pending_after_receipt,
            "accepted trust must resume the original parked send workflow"
        );
    }

    #[test]
    fn provider_setup_resolution_is_bounded() {
        let now = Instant::now();
        let state = ProviderSetupApprovalState::Resolving {
            command_id: CommandId::new(),
            allow: true,
            started_at: now - PROVIDER_SETUP_RESOLUTION_TIMEOUT,
        };
        assert!(provider_setup_resolution_expired(&state, now));
        assert!(!provider_setup_resolution_expired(
            &ProviderSetupApprovalState::Waiting,
            now,
        ));
    }

